var MREST=[{"id":6331,"bg":"Когато при преминаване през жп прелез се включат звуковия сигнал и червените светлини на светофара, водачът трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да продължи движението си и да освободи прелеза","ok":true,"i":null,"es":"continuar y abandonar el paso a nivel lo antes posible"},{"t":"да спре незабавно и да включи аварийните светлини","ok":false,"i":null,"es":"parar inmediatamente y activar las luces de emergencia"},{"t":"да завие в обратна посока за да освободи прелеза по-бързо","ok":false,"i":null,"es":"dar la vuelta para salir más rápido"}],"f":8,"es":"Cuando al cruzar el paso a nivel se activan las señales de alarma, el conductor que ya está sobre las vías debe:","explain":"Si ya estás SOBRE las vías cuando se activan las señales, nunca pares ni des la vuelta: continúa y libera el paso cuanto antes. Detenerse sobre las vías (aunque sea con luces de emergencia) te deja en la trayectoria del tren."},{"id":6341,"bg":"На водача е забранено да навлиза на железопътния прелез когато:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"бариерите се спускат","ok":true,"i":null,"es":"las barreras están bajando"},{"t":"бариерите са спуснати","ok":true,"i":null,"es":"las barreras están bajadas"},{"t":"на прелеза трябва да се размине с друго ППС","ok":false,"i":null,"es":"en el paso debe cruzarse con otro vehículo"},{"t":"на прелеза няма съоръжения за подаване на звуков и светлинен сигнал","ok":false,"i":null,"es":"el paso no tiene señalización"}],"f":8,"es":"Al conductor le está PROHIBIDO entrar al paso a nivel cuando: (2 correctas)","explain":"Está prohibido entrar cuando las barreras BAJAN o están BAJADAS: el tren viene. Cruzarse con otro vehículo en el paso no está prohibido, y un paso sin señalización se puede cruzar tras parar y comprobar que no viene tren."},{"id":6355,"bg":"Задължително ли е спирането пред жп прелез, когато той е без бариери?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да, във всички случаи","ok":true,"i":null,"es":"sí, en todos los casos"},{"t":"да, но само когато към прелеза приближава влак","ok":false,"i":null,"es":"sí, pero solo cuando se aproxima un tren"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":8,"es":"¿Es obligatorio parar ante un paso a nivel sin barreras?","explain":"Sí, SIEMPRE: ante un paso a nivel sin barreras la parada es obligatoria en todos los casos, haya o no tren a la vista. Es la única forma segura de comprobar; 'solo si se acerca un tren' invierte la lógica de la norma."},{"id":6460,"bg":"Ще извърши ли нарушение водачът на автомобила, ако при тази ситуация завие наляво?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/82690.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":8,"es":"¿Cometerá infracción el conductor si gira a la izquierda en esta situación?","explain":"SÍ, comete infracción.\n\nLO QUE MANDA AQUÍ. Sobre el semáforo hay un disco azul de DIRECCIÓN OBLIGATORIA que solo dibuja recto y derecha. La izquierda no está entre las direcciones autorizadas.\n\nPOR QUÉ EL VERDE NO LE SALVA. El semáforo en verde te autoriza a PASAR, no a tomar cualquier dirección. Un semáforo deja sin efecto las señales de prioridad (STOP, ceda el paso, rombo), pero nunca las de obligación ni las de prohibición.\n\nLAS MARCAS DE LA CALZADA repiten lo mismo con flechas pintadas, así que el aviso te llega por dos vías a la vez.\n\nCLAVE: verde significa 'puedes pasar', no 'puedes ir donde quieras'."},{"id":6475,"bg":"При спиране в тунел с дължина над 500 м, дистанцията между автомобилите трябва да е не по-малка от:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"5 м","ok":true,"i":null,"es":"5 m"},{"t":"4 м","ok":false,"i":null,"es":"4 m"},{"t":"3 м","ok":false,"i":null,"es":"3 m"},{"t":"2 м","ok":false,"i":null,"es":"2 m"}],"f":8,"explain":"En túnel de más de 500 m, al parar (retención) deja mínimo 5 m con el de delante: ese hueco permite evacuar, maniobrar a los servicios de emergencia y aleja el fuego en caso de incendio. Es el dato numérico de túneles: 500 m → 5 m.","es":"Al parar en túnel de más de 500 m la distancia entre vehículos debe ser de no menos de:"},{"id":6479,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/54367.png","v":null,"a":[{"t":"трябва да премина преди синия автомобил","ok":true,"i":null,"es":"debo pasar antes que el coche azul"},{"t":"спирам, за да пропусна синия автомобил и преминавам след него","ok":false,"i":null,"es":"paro para dejar al azul y paso después"},{"t":"спирам, за да изчакам разрешаващ сигнал от регулировчика","ok":false,"i":null,"es":"paro para esperar señal de paso del agente"}],"f":8,"es":"En esta situación:","explain":"Debo PASAR ANTES que el coche azul.\n\nEL AGENTE MANDA SOBRE EL STOP. Hay una señal de STOP en el cruce, pero cuando un agente dirige el tráfico, sus indicaciones dejan sin efecto las señales que reparten la prioridad. El orden es: regulador, después semáforo, después señales.\n\nSU POSTURA. Lo ves DE PERFIL, por su costado, con el brazo derecho extendido al frente. Desde el costado izquierdo con el brazo al frente se abren todas las direcciones.\n\nEL AZUL espera, porque a él la misma señal no le autoriza.\n\nCLAVE: si hay agente, deja de mirar las señales de prioridad. Ya no deciden nada."},{"id":6524,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57242.png","v":null,"a":[{"t":"да премина преди червения автомобил","ok":true,"i":null,"es":"pasar antes que el coche rojo"},{"t":"да премина преди синия автомобил","ok":true,"i":null,"es":"pasar antes que el coche azul"},{"t":"да пропусна червения автомобил","ok":false,"i":null,"es":"dejar pasar al rojo"},{"t":"да пропусна синия автомобил","ok":false,"i":null,"es":"dejar pasar al azul"}],"f":8,"es":"En esta situación debo: (2 correctas)","explain":"MULTIRESPUESTA: paso antes que el rojo y antes que el azul.\n\nPOR QUÉ. El rombo amarillo mira hacia ti: circulas por la VÍA CON PRIORIDAD. Los dos coches llegan por brazos secundarios, así que ambos te ceden el paso a ti.\n\nUN COCHE A CADA LADO no cambia nada cuando tú vas por la prioritaria. La regla de la derecha decide entre vehículos de vías del mismo valor, y aquí no lo son.\n\nCLAVE: identifica primero si hay señal de prioridad. Solo cuando no la hay entras a mirar quién viene por la derecha."},{"id":6536,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/58116.png","v":null,"a":[{"t":"да премина преди червения автомобил","ok":true,"i":null,"es":"pasar antes que el coche rojo"},{"t":"да пропусна синия автомобил","ok":true,"i":null,"es":"dejar pasar al azul"},{"t":"да премина преди синия автомобил","ok":false,"i":null,"es":"pasar antes que el coche azul"},{"t":"да пропусна червения автомобил","ok":false,"i":null,"es":"dejar pasar al rojo"}],"f":8,"es":"En esta situación debo: (2 correctas)","explain":"Dos cosas: paso antes que el vehículo rojo Y cedo el paso al azul.\n\nEL ROMBO AMARILLO A MI DERECHA es «vía con prioridad». Me dice que la calle por la que voy manda sobre las que la cruzan.\n\nEL ROJO LLEGA POR LA CALLE TRANSVERSAL, sin prioridad. Frente a él no tengo que hacer nada: es él quien me cede a mí. Por eso «paso antes que el rojo» es correcto y «dejar pasar al rojo» es falso.\n\nDEBAJO DEL ROMBO HAY UN CÍRCULO AZUL CON LA FLECHA DOBLADA A LA IZQUIERDA: dirección obligatoria a la izquierda. Mi intermitente izquierdo, encendido en el salpicadero, confirma la maniobra.\n\nEL AZUL VIENE DE FRENTE Y AHÍ ENTRA OTRA REGLA DISTINTA: el чл. 37 obliga al que gira a la izquierda a ceder el paso a los que circulan en sentido contrario. Estar en la vía con prioridad no me libera: el azul también está en ella, viene de cara, y yo soy el que cruza su trayectoria.\n\nCLAVE: dos reglas trabajando a la vez. El rombo resuelve el cruce con las calles laterales; el giro a la izquierda se resuelve aparte, con чл. 37, frente a los que vienen de cara. Contesta el cruce coche por coche, no de un golpe."},{"id":6553,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/66833.png","v":null,"a":[{"t":"пропускам синия автомобил","ok":true,"i":null,"es":"cedo el paso al azul"},{"t":"преминавам преди синия автомобил","ok":false,"i":null,"es":"paso antes que el coche azul"}],"f":8,"es":"En esta situación:","explain":"Cedo el paso a la furgoneta azul.\n\nES UN CRUCE SIN SEÑALES Y SIN SEMÁFORO. Cuando no hay nada que reparta la prioridad, las dos vías valen lo mismo y se aplica la regla de la derecha del чл. 50, ал. 1: cedo a todo el que se me acerque por la derecha.\n\nEL AZUL LLEGA POR MI DERECHA. Con eso está resuelto: pasa él primero.\n\nQUE YO VAYA RECTO NO CAMBIA NADA. Es el error clásico: seguir de frente no es una maniobra privilegiada, no me da ninguna preferencia sobre el que llega por la derecha.\n\nPOR ESO «PASO ANTES QUE EL AZUL» ES FALSO: solo sería cierto si él llegara por mi izquierda, o si yo tuviera una señal de vía con prioridad, o un semáforo o un agente que me diera paso. No hay nada de eso.\n\nCLAVE: sin señales, sin semáforo y sin agente, manda la derecha. Vaya yo recto o gire."},{"id":6555,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68438.png","v":null,"a":[{"t":"да пропусна червения автомобил","ok":true,"i":null,"es":"dejar pasar al rojo"},{"t":"да премина преди синия автомобил","ok":true,"i":null,"es":"pasar antes que el coche azul"},{"t":"да премина преди червения автомобил","ok":false,"i":null,"es":"pasar antes que el coche rojo"},{"t":"да пропусна синия автомобил","ok":false,"i":null,"es":"dejar pasar al azul"}],"f":8,"explain":"Dos cosas: cedo el paso al coche rojo Y paso antes que el azul.\n\nES UN CRUCE SIN SEÑALES NI SEMÁFORO, así que las tres vías valen lo mismo y todo se resuelve con la regla de la derecha (чл. 50, ал. 1). La forma segura de contestar es ir de uno en uno.\n\nEL ROJO ESTÁ A MI DERECHA. Le cedo. Por eso «pasar antes que el coche rojo» es falso.\n\nEL AZUL ESTÁ A MI IZQUIERDA. Yo estoy a la derecha de él, así que me cede a mí y paso antes. Por eso «dejar pasar al azul» es falso.\n\nYO GIRO A LA IZQUIERDA — el intermitente está encendido — PERO ESO NO AÑADE NADA AQUÍ. El чл. 37 obliga a ceder a los que vienen de frente cuando giras a la izquierda, y en esta escena no viene nadie de frente. La maniobra no me quita ni me da prioridad frente a los laterales.\n\nCLAVE: cruce sin señales = resuélvelo coche por coche, no de un vistazo. El de mi izquierda me cede; al de mi derecha le cedo yo. Y solo si hay alguien de frente entra además el чл. 37.","es":"En esta situación debo: (2 correctas)"},{"id":6560,"bg":"При тази ситуация с предимство е водачът на:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67148.png","v":null,"a":[{"t":"автомобила","ok":true,"i":null,"es":"el coche"},{"t":"мотоциклета","ok":false,"i":null,"es":"la moto"}],"f":8,"es":"En esta situación tiene prioridad:","explain":"EL CONDUCTOR DEL COCHE. Una sola correcta.\n\nQUÉ VES. Un cruce SIN SEÑALES. Un coche ROJO (en primer plano) lleva el intermitente IZQUIERDO y va a girar a la izquierda. Por su IZQUIERDA llega una MOTO que sigue recto.\n\nLA MOTO TIENE AL COCHE A SU DERECHA. Sin señales, cede quien tiene al otro a su derecha: la moto cede al coche.\n\n«LA MOTO» es el cebo de quien piensa que el que gira a la izquierda siempre cede. Eso es frente a lo que viene de FRENTE; la moto llega por un lateral.\n\nCLAVE: compárala con la 5924 (la misma escena preguntando qué regla decide). MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). Ver Leyes → «Regla de la derecha»."},{"id":6563,"bg":"При тази ситуация първи трябва да премине:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68370.png","v":null,"a":[{"t":"червеният автомобил","ok":true,"i":null,"es":"el coche rojo"},{"t":"зеленият автомобил","ok":false,"i":null,"es":"el coche verde"},{"t":"синият автомобил","ok":false,"i":null,"es":"el coche azul"}],"f":8,"es":"En esta situación el primero en pasar debe ser:","explain":"EL COCHE ROJO. Una sola correcta.\n\nQUÉ VES. Un cruce SIN SEÑALES. El coche VERDE (en primer plano) lleva el intermitente IZQUIERDO. De frente viene un coche ROJO con el intermitente, que gira a SU derecha. Por la derecha del verde llega un coche AZUL que sigue recto.\n\nAVERIGUA QUIÉN NO TIENE A NADIE A SU DERECHA:\n• El ROJO: a su derecha no viene nadie, y gira a la derecha. No tiene que ceder a nadie.\n• El AZUL: tiene al rojo a su derecha. Cede al rojo.\n• El VERDE: tiene al azul a su derecha y, además, gira a la izquierda con el rojo de frente. Cede a los dos.\n\nORDEN: rojo, azul, verde.\n\n«EL VERDE» y «EL AZUL» son los cebos de quien mira solo a un par de coches.\n\nCLAVE: en cruces con tres coches, empieza por el que tiene la derecha libre. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). Ver Leyes → «Regla de la derecha»."},{"id":6567,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68303.png","v":null,"a":[{"t":"да премина преди синия автомобил","ok":true,"i":null,"es":"pasar antes que el coche azul"},{"t":"да премина преди червения автомобил","ok":true,"i":null,"es":"pasar antes que el coche rojo"},{"t":"да пропусна синия автомобил","ok":false,"i":null,"es":"dejar pasar al azul"},{"t":"да пропусна червения автомобил","ok":false,"i":null,"es":"dejar pasar al rojo"}],"f":8,"es":"En esta situación debo: (2 correctas)","explain":"PASAR ANTES QUE EL AZUL Y PASAR ANTES QUE EL ROJO. Dos correctas.\n\nQUÉ VES. Un cruce SIN SEÑALES. Vas RECTO. Por tu IZQUIERDA llega una furgoneta AZUL que sigue recto. De frente viene un coche ROJO con el intermitente, que va a girar a SU izquierda cruzando tu trayectoria.\n\nAL AZUL LE PASAS: te llega por la izquierda; tú estás a su derecha.\n\nAL ROJO LE PASAS: gira a la izquierda y tú vienes de frente recto; el que gira a la izquierda cede al de frente.\n\n«CEDER AL AZUL» y «CEDER AL ROJO» son los cebos de quien cede «por si acaso».\n\nCLAVE: aquí nadie te llega por la derecha y el de frente gira a la izquierda: pasas tú primero. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). Ver Leyes → «Regla de la derecha»."},{"id":6588,"bg":"Този знак изисква от водачите да спрат:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/55422.png","v":null,"a":[{"t":"винаги, независимо дали по пресичания път се движи превозно средство","ok":true,"i":null,"es":"siempre, independientemente de si hay vehículos en la vía cruzada"},{"t":"само ако по пресичания път се движи превозно средство","ok":false,"i":null,"es":"solo si hay vehículos en la vía cruzada"},{"t":"ако те преценят, че е необходимо","ok":false,"i":null,"es":"si el conductor lo considera necesario"}],"f":8,"es":"Esta señal obliga a los conductores a parar:","explain":"SIEMPRE, INDEPENDIENTEMENTE DE SI HAY VEHÍCULOS EN LA VÍA QUE CRUZAS. Una sola correcta.\n\nQUÉ VES. Un cruce. En tu poste, la señal octogonal roja de STOP. En los otros accesos se ven rombos de vía con prioridad.\n\nSTOP = DETENCIÓN OBLIGATORIA. Tienes que pararte del todo antes de entrar en el cruce, venga alguien o no. Después cedes a los que circulan por la vía principal.\n\n«SOLO SI HAY VEHÍCULOS EN LA VÍA QUE CRUZAS» es el cebo: eso sería el ceda el paso.\n\n«SI EL CONDUCTOR LO CONSIDERA NECESARIO» convierte la obligación en una opción.\n\nCLAVE: ceda el paso = cedo si viene alguien; STOP = paro siempre y luego cedo. Ver Leyes → «Vía con prioridad»."},{"id":6594,"bg":"При този пътен знак:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/56647.png","v":null,"a":[{"t":"е разрешено да премина, без да спирам, защото пътят, по който се движа, е с предимство","ok":true,"i":null,"es":"puedo pasar sin parar porque estoy en vía preferente"},{"t":"задължен съм да спра, преди да премина през кръстовището","ok":false,"i":null,"es":"estoy obligado a parar antes de cruzar"},{"t":"мога да премина, без да спирам, но трябва да пропусна ППС от другия път","ok":false,"i":null,"es":"puedo pasar sin parar pero cediendo el paso"}],"f":8,"explain":"PUEDO PASAR SIN PARAR PORQUE ESTOY EN VÍA PREFERENTE. Una sola correcta.\n\nQUÉ VES. Vas RECTO. En tu poste hay una señal de VÍA CON PRIORIDAD (rombo). Por la DERECHA, por la vía transversal, llega una furgoneta AZUL.\n\nEL ROMBO TE DA PREFERENCIA. Los de la otra vía tienen que cederte el paso, aunque vengan por tu derecha.\n\n«DEBO PARAR ANTES DE CRUZAR» es el STOP.\n\n«PUEDO PASAR SIN PARAR CEDIENDO AL TRÁFICO DEL OTRO CAMINO» es el ceda el paso.\n\nCLAVE: rombo = preferencia; triángulo invertido = cedes; octógono = paras. Compárala con la 6592 y la 6596.  Ver Leyes → «Vía con prioridad».","es":"Con esta señal:"},{"id":6603,"bg":"Разрешено ли е на водача на ППС да навлезе в кръстовище, ако обстановката ще го принуди да спре в кръстовището и да възпрепятства преминаването през него?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да, при разрешаващ сигнал на светофар","ok":false,"i":null,"es":"sí, con semáforo verde"},{"t":"да, но само когато се намира на пътя с предимство","ok":false,"i":null,"es":"sí, si estás en vía preferente"}],"f":8,"es":"¿Está permitido entrar en una intersección si la situación le obligará a parar dentro?","explain":"No: si vas a quedar detenido DENTRO de la intersección obstaculizando el cruce, no debes entrar, ni con semáforo verde ni circulando por vía con prioridad. Bloquear el cruce es infracción independiente de tu prioridad."},{"id":6605,"bg":"В кой от случаите водачът не трябва да навлиза в кръстовище?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"когато обстановката ще го принуди да спре в кръстовището, при което ще възпрепятства напречното движение","ok":true,"i":null,"es":"cuando tendría que parar en la intersección obstaculizando el paso"},{"t":"когато по напречния път приближава автомобил със специален режим на движение","ok":true,"i":null,"es":"cuando se acerca un vehículo de emergencia por la vía cruzada"},{"t":"когато преминаването се регулира от светофар със жълта мигаща светлина","ok":false,"i":null,"es":"cuando el semáforo tiene luz amarilla parpadeante"}],"f":8,"es":"¿En qué casos el conductor NO debe entrar en la intersección? (2 correctas)","explain":"Dos supuestos: cuando quedarías parado dentro obstaculizando el tráfico transversal, y cuando se aproxima un vehículo de emergencia con señales especiales. El ámbar intermitente solo exige precaución, no prohíbe entrar."},{"id":6679,"bg":"При тази ситуация с предимство е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/62132.png","v":null,"a":[{"t":"червеният автомобил","ok":false,"i":null,"es":"el coche rojo"},{"t":"жълтият автомобил","ok":true,"i":null,"es":"el coche amarillo"}],"f":8,"es":"En esta situación tiene prioridad:","explain":"EL COCHE AMARILLO. Una sola correcta.\n\nQUÉ VES. Una ROTONDA con la señal azul de rotonda, pero SIN señal de ceda el paso en la entrada. El coche AMARILLO va a entrar. El coche ROJO ya circula por el anillo y se acerca por la IZQUIERDA del amarillo.\n\nSIN CEDA EL PASO EN LA ENTRADA, DECIDE LA REGLA DE LA DERECHA. El amarillo está a la derecha del rojo, así que tiene preferencia, aunque el rojo ya esté dentro.\n\n«EL ROJO» es el cebo de quien da por hecho que el que está dentro de una rotonda siempre tiene preferencia. Eso solo ocurre cuando la entrada tiene ceda el paso (compárala con la 6506).\n\nCLAVE: rotonda con ceda el paso en la entrada = el de dentro primero; rotonda sin él = la derecha (el que entra). MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? 4) si nada separa a los dos, decide la derecha. Ver Leyes → «Regla de la derecha»."},{"id":6680,"bg":"При тази ситуация трябва да премина преди червения автомобил защото:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64639.png","v":null,"a":[{"t":"съм на пътя с предимство","ok":true,"i":null,"es":"estoy en vía preferente"},{"t":"се движа направо","ok":false,"i":null,"es":"voy recto"},{"t":"червеният автомобил завива наляво","ok":false,"i":null,"es":"el rojo gira a la izquierda"}],"f":8,"es":"En esta situación paso antes que el rojo porque:","explain":"PORQUE ESTOY EN VÍA PREFERENTE. Una sola correcta.\n\nQUÉ VES. Vas RECTO. A la derecha hay una señal de VÍA CON PRIORIDAD con PANEL: el trazo GRUESO sube desde tu posición y gira a la DERECHA. De frente, por una rama fina, viene un coche ROJO con el intermitente.\n\nEL ROJO VIENE DE LA SECUNDARIA Y TÚ DE LA PREFERENTE. Por eso pasas antes que él.\n\n«PORQUE VOY RECTO» es una razón falsa: ir recto no da prioridad.\n\n«PORQUE EL ROJO GIRA A LA IZQUIERDA» sería la razón entre dos vehículos de la misma vía; aquí lo que decide es la señal.\n\nCLAVE: si la señal os separa, la razón es la señal. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha. Ver Leyes → «Cuando la prioritaria cambia de dirección»."},{"id":7965,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64917965.png","v":null,"a":[{"t":"трябва да премина преди лекия автомобил","ok":true,"i":null,"es":"debo pasar antes que el turismo"},{"t":"трябва да пропусна лекия автомобил, който се движи направо","ok":false,"i":null,"es":"debo ceder el paso al turismo que va recto"}],"f":8,"es":"En esta situación:","explain":"DEBO PASAR ANTES QUE EL TURISMO. Una sola correcta.\n\nQUÉ VES. Llevas el intermitente IZQUIERDO y vas a girar a la izquierda. A la derecha hay una señal de VÍA CON PRIORIDAD con PANEL: el trazo GRUESO sube desde tu posición y gira a la DERECHA; las ramas de la izquierda y de enfrente son finas. Por la IZQUIERDA, por la rama fina, llega un turismo ROJO que sigue recto.\n\nTÚ VIENES POR LA PREFERENTE Y EL ROJO POR LA SECUNDARIA. Aunque tú salgas de la preferente girando a la izquierda, el rojo te cede.\n\n«DEBO CEDER AL TURISMO QUE VA RECTO» es el cebo: ir recto no le da prioridad, y además viene por la secundaria.\n\nCLAVE: lo que decide es por qué rama llega cada uno, no hacia dónde va. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha. Ver Leyes → «Cuando la prioritaria cambia de dirección»."},{"id":5334,"bg":"С този пътен знак се обозначава:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/40658.png","v":null,"a":[{"t":"автомобилен път","ok":true,"i":null,"es":"vía rápida"},{"t":"автомагистрала","ok":false,"i":null,"es":"autopista"},{"t":"път, за движение само на леки автомобили","ok":false,"i":null,"es":"vía solo para turismos"},{"t":"задължетелен път само за леки автомобили","ok":false,"i":null,"es":"vía obligatoria solo para turismos"}],"f":8,"es":"Esta señal de tráfico indica:","explain":"VÍA RÁPIDA («автомобилен път»). Una sola correcta.\n\nLA SEÑAL. Cuadrado AZUL con la silueta blanca de un COCHE de frente.\n\nAZUL CON COCHE = VÍA RÁPIDA, reservada a vehículos de motor. La autopista es la VERDE con la calzada doble (compárala con la 6707).\n\n«VÍA SOLO PARA TURISMOS» es el cebo de leer el dibujo al pie de la letra: el coche representa a los vehículos de motor en general, no solo a los turismos.\n\nCLAVE: verde = autopista; azul con coche = vía rápida. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5409,"bg":"При тази ситуация на автомагистрала:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/41739.png","v":null,"a":[{"t":"на водача на лекия автомобил е забранено да пресича разделителната ивица","ok":true,"i":null,"es":"al conductor del turismo le está prohibido cruzar la franja divisoria"},{"t":"водачът на лекия автомобил може да пресече раздилителната ивица, когато няма автомобили в другото платно","ok":false,"i":null,"es":"el conductor del turismo puede cruzar la franja divisoria cuando no hay automóviles en la otra calzada"},{"t":"водачът на лекия автомобил трябва да пропусне товарния автомобил","ok":false,"i":null,"es":"el conductor del turismo debe ceder el paso al camión"},{"t":"водачът на лекия автомобил преминава преди товарния автомобил","ok":false,"i":null,"es":"el conductor del turismo pasa antes que el camión"}],"f":8,"es":"En esta situación en autopista:","explain":"AL CONDUCTOR DEL TURISMO LE ESTÁ PROHIBIDO CRUZAR LA FRANJA DIVISORIA. Una sola correcta.\n\nQUÉ VES. Una AUTOPISTA (señal verde). Un coche AZUL lleva el intermitente IZQUIERDO y la flecha dibuja que quiere atravesar la mediana para pasar a la otra calzada. Por la otra calzada viene un camión.\n\nEN AUTOPISTA NO SE CRUZA LA MEDIANA NUNCA, ni para dar la vuelta ni para pasar al otro sentido, aunque la otra calzada esté vacía.\n\n«PUEDE CRUZARLA CUANDO NO HAY COCHES EN LA OTRA CALZADA» es el cebo: la prohibición no depende del tráfico.\n\n«DEBE CEDER AL CAMIÓN» y «PASA ANTES QUE EL CAMIÓN» son cebos que dan por hecho que la maniobra está permitida y solo discuten el orden.\n\nCLAVE: si la maniobra está prohibida, no hay orden de paso que discutir. Ver Leyes → «Autopista: incorporación y vehículos lentos»."},{"id":8277,"bg":"При движение по скоростен път на водача е забранено:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да спира пътното превозно средство за престой извън специално обозначените за това места","ok":true,"i":null,"es":"detener el vehículo para una parada fuera de los lugares especialmente señalizados para ello"},{"t":"да навлиза в разделителната ивица или да я пресича, включително и на местата, където тя е прекъсната","ok":true,"i":null,"es":"invadir o cruzar la mediana, incluso en los lugares donde está interrumpida"},{"t":"да завива в обратна посока","ok":true,"i":null,"es":"girar en sentido contrario"},{"t":"да тегли повредено МПС с твърда връзка","ok":false,"i":null,"es":"remolcar un vehículo averiado con barra rígida"}],"f":8,"es":"Al circular por vía rápida al conductor le está prohibido: (3 correctas)","explain":"Tres prohibiciones de vía rápida: parar fuera de los lugares señalizados, invadir o cruzar la mediana (incluso interrumpida) y girar en sentido contrario. Remolcar con barra rígida está permitido: es la opción trampa recurrente."},{"id":5621,"bg":"Паркирането в жилищна зона, обозначена със съответния пътен знак, е разрешено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"само на специално обозначените за това места","ok":true,"i":null,"es":"solo en los lugares especialmente señalizados para ello"},{"t":"в най-дясната пътна лента","ok":false,"i":null,"es":"en el carril más a la derecha"},{"t":"най-вдясно на пътното платно","ok":false,"i":null,"es":"lo más a la derecha de la calzada"},{"t":"най-вдясно на платното за движение","ok":false,"i":null,"es":"lo más a la derecha de la calzada de circulación"}],"f":8,"es":"El estacionamiento en una zona residencial, señalizada con la señal correspondiente, está permitido:","explain":"En zona residencial señalizada solo se estaciona en los lugares específicamente marcados para ello: la calle es espacio compartido con peatones y niños, no un aparcamiento libre."},{"id":11624,"bg":"В жилищна зона обозначена със съответния пътен знак, водачите на МПС трябва да се движат със скорост не по-висока от:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"20 km/h","ok":true,"i":null,"es":"20 km/h"},{"t":"30 km/h","ok":false,"i":null,"es":"30 km/h"},{"t":"40 km/h","ok":false,"i":null,"es":"40 km/h"},{"t":"50 km/h","ok":false,"i":null,"es":"50 km/h"}],"f":8,"es":"En una zona residencial señalizada con la señal correspondiente, los conductores deben circular a una velocidad no superior a:","explain":"20 km/h: en zona residencial señalizada la calle es espacio compartido con peatones y niños jugando, por eso el límite es el más bajo del código."},{"id":5558,"bg":"Задължително ли е присъствието на водача в близост до превозното средство, когато то е спряно за престой?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":8,"es":"¿Es obligatoria la presencia del conductor cerca del vehículo cuando está detenido en una parada?","explain":"Sí: el conductor debe permanecer cerca del vehículo durante la parada breve (престой), para poder moverlo si estorba. Eso es precisamente lo que distingue la parada del estacionamiento."},{"id":5572,"bg":"Спирането след знака върху платното за движение за качване на пътника е:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42890.png","v":null,"a":[{"t":"забранено","ok":true,"i":null,"es":"prohibido"},{"t":"разрешено","ok":false,"i":null,"es":"permitido"}],"f":8,"es":"Detenerse después de la señal, sobre la calzada, para que suba el pasajero es:","explain":"PROHIBIDO.\n\nQUÉ VES. Calle urbana. A la derecha, la señal de PROHIBIDO ADELANTAR A LOS CAMIONES. Un coche ROJO se detiene sobre la calzada, con el intermitente derecho, junto a un hombre que espera en la acera para subir.\n\nDONDE ESTÁ PROHIBIDO ADELANTAR, TAMBIÉN ESTÁ PROHIBIDO DETENERSE Y APARCAR SOBRE LA CALZADA: un vehículo parado ahí obligaría a los demás a rebasarlo justo donde no se puede. Vale también para la de los camiones, y también para una parada breve para recoger a alguien.\n\n«PERMITIDO» es el cebo de quien cree que una parada corta no cuenta.\n\nCLAVE: compárala con la 5543."},{"id":5576,"bg":"При тази ситуация правилно ли е спрян за престой лекият автомобил?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/160581.png","v":null,"a":[{"t":"да, защото не пречи на движението","ok":true,"i":null,"es":"sí, porque no interfiere con el tráfico"},{"t":"не, защото престоят е разрешен само от дясната страна на платното за движение","ok":false,"i":null,"es":"no, porque la parada solo está permitida en el lado derecho de la calzada"}],"f":8,"es":"En esta situación, ¿está el turismo correctamente detenido (parada)?","explain":"SÍ, PORQUE NO INTERFIERE CON EL TRÁFICO. Una sola correcta.\n\nQUÉ VES. Calle de SENTIDO ÚNICO (cuadrado azul con flecha). Un coche AZUL está detenido junto a la acera IZQUIERDA, pegado al bordillo; en la acera hay peatones.\n\nEN UNA CALLE DE SENTIDO ÚNICO SE PUEDE HACER UNA PARADA BREVE TAMBIÉN A LA IZQUIERDA, siempre junto al borde y sin estorbar (aparcar, en cambio, solo a la derecha: 5582). Eso es lo que hace el azul.\n\n«SOLO EN EL LADO DERECHO» es el cebo: es la regla de las calles de doble sentido.\n\nCLAVE: compárala con la 5585 (la misma calle, el azul mal colocado)."},{"id":5612,"bg":"Кой от автомобилите е спрян правилно за престой?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43862.png","v":null,"a":[{"t":"товарният автомобил","ok":false,"i":null,"es":"el camión"},{"t":"автобусът","ok":true,"i":null,"es":"el autobús"}],"f":8,"es":"¿Cuál de los automóviles está correctamente detenido (parada)?","explain":"EL AUTOBÚS. Una sola correcta.\n\nQUÉ VES. Calle urbana con un paso de peatones señalizado. Un CAMIÓN azul está parado ENCIMA del paso de peatones; un AUTOBÚS está parado más adelante, junto a la acera derecha, pasado el paso.\n\nESTÁ PROHIBIDO DETENERSE SOBRE UN PASO DE PEATONES y a menos de 5 m antes de él: tapa la vista y obliga a los peatones a rodearlo. El camión lo incumple; el autobús, no.\n\n«EL CAMIÓN» es el cebo directo.\n\nCLAVE: compárala con la 5634 (la misma escena). Ver Leyes → «Paso de peatones»."},{"id":5620,"bg":"На кое от изброените места е забранено спирането за престой?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на места, където ППС създава опасност или е пречка за движението","ok":true,"i":null,"es":"en lugares donde el vehículo crea peligro u obstaculiza el tráfico"},{"t":"на място, където ППС закрива от другите участници в движението сигнал на светофара","ok":true,"i":null,"es":"en un lugar donde el vehículo oculta a los demás usuarios la señal del semáforo"},{"t":"до друго, спряно за престой или паркирано ППС, от страната на движението","ok":true,"i":null,"es":"junto a otro vehículo parado o aparcado, en el lado de la circulación"},{"t":"на път с еднопосочно движение","ok":false,"i":null,"es":"en vía de sentido único"}],"f":8,"es":"¿En cuál de los lugares indicados está prohibida la detención (parada)? (3 correctas)","explain":"La parada está prohibida donde el vehículo crea peligro u obstáculo, donde tapa un semáforo o señal a los demás, y en doble fila (junto a otro vehículo parado por el lado de circulación). En vía de sentido único la parada no está prohibida por sí misma."},{"id":5634,"bg":"Кой от автомобилите е паркиран в нарушение на правилата за движение?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43879.png","v":null,"a":[{"t":"товарният автомобил","ok":true,"i":null,"es":"el camión"},{"t":"автобусът","ok":false,"i":null,"es":"el autobús"}],"f":8,"es":"¿Cuál de los automóviles está estacionado infringiendo las normas de circulación?","explain":"EL CAMIÓN. Una sola correcta.\n\nQUÉ VES. La misma escena que la 5612: el CAMIÓN parado encima del paso de peatones y el AUTOBÚS más adelante, junto a la acera, pasado el paso.\n\nEL CAMIÓN ESTÁ SOBRE EL PASO DE PEATONES, donde está prohibido detenerse y aparcar.\n\n«EL AUTOBÚS» es el cebo: está bien colocado.\n\nCLAVE: compárala con la 5612. Ver Leyes → «Paso de peatones»."},{"id":5643,"bg":"Паркирането е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"пред входовете на паркове, театри, кина, предприятия","ok":true,"i":null,"es":"delante de las entradas de parques, teatros, cines y empresas"},{"t":"на места, където е възможно да влизат или да излизат пътни превозни средства","ok":true,"i":null,"es":"en lugares donde los vehículos puedan entrar o salir"},{"t":"непосредствено пред входовете на гаражи, когато това затруднява достъпа до тях","ok":true,"i":null,"es":"inmediatamente ante las entradas de garajes, cuando dificulta el acceso"},{"t":"на участък от пътя в ремонт","ok":false,"i":null,"es":"en un tramo de carretera en obras"}],"f":8,"es":"El estacionamiento está prohibido: (3 correctas)","explain":"Prohibido estacionar delante de entradas de parques, teatros, cines y empresas, en accesos de vehículos y ante entradas de garajes cuando se dificulta su uso. Un tramo en obras prohíbe el estacionamiento solo si está señalizado."},{"id":5649,"bg":"При паркиране върху платното за движение, водачът е в нарушение, ако разстоянието между ППС и пътната маркировка, забранена за пресичане, е:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"1 м","ok":true,"i":null,"es":"1 m"},{"t":"2 м","ok":true,"i":null,"es":"2 m"},{"t":"2.5 м","ok":true,"i":null,"es":"2,5 m"},{"t":"3.5 м","ok":false,"i":null,"es":"3,5 m"}],"f":8,"es":"Al estacionar en la calzada, el conductor comete infracción si la distancia entre el vehículo y la marca vial que está prohibido cruzar es: (3 correctas)","explain":"Hay infracción si al estacionar dejas menos de 3 m hasta una marca vial que está prohibido cruzar: obligarías a los demás a pisarla. Por eso 1 m, 2 m y 2,5 m son infracción y 3,5 m no."},{"id":5650,"bg":"Разрешен ли е престоят на ППС в участъци от пътя, които са в ремонт?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":8,"es":"¿Está permitida la parada de vehículos en tramos de vía en obras?","explain":"Sí: la PARADA (detención breve) en tramos en obras está permitida. Lo que puede estar restringido por señalización es el estacionamiento prolongado."},{"id":5662,"bg":"При отстраняване на повреда по ППС, което се намира на платно за движение, водачът е задължен:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да е облечен със светлоотразителна жилетка, когато се намира извън превозното средство","ok":true,"i":null,"es":"llevar chaleco reflectante cuando se encuentre fuera del vehículo"},{"t":"да обозначи превозното средство","ok":true,"i":null,"es":"señalizar el vehículo"},{"t":"да съобщи на контролните органи за повредата","ok":false,"i":null,"es":"comunicar la avería a las autoridades de control"},{"t":"да се обади на „пътна помощ”","ok":false,"i":null,"es":"llamar a la asistencia en carretera"}],"f":8,"es":"Al reparar una avería de un vehículo que se encuentra en la calzada, el conductor está obligado a: (2 correctas)","explain":"Al reparar una avería en la calzada: chaleco reflectante fuera del vehículo y señalizar el vehículo (triángulo, luces de emergencia). Avisar a las autoridades o llamar a la grúa no son obligaciones legales."},{"id":8283,"bg":"Този пътен знак:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/125668477.png","v":null,"a":[{"t":"указва място, определено за паркиране на ППС, обслужващи хора с трайни увреждания","ok":true,"i":null,"es":"indica lugar reservado para aparcar vehículos que sirven a personas con discapacidad"},{"t":"предупреждава за възможна поява на ППС, обслужващи хора с трайни увреждания","ok":false,"i":null,"es":"advierte de posible presencia de esos vehículos"},{"t":"забранява движението на ППС, обслужващи хора с трайни увреждания","ok":false,"i":null,"es":"prohíbe la circulación de esos vehículos"},{"t":"указва пътна лента за ППС, обслужващи хора с трайни увреждания","ok":false,"i":null,"es":"indica carril para esos vehículos"}],"f":8,"es":"Esta señal:","explain":"INDICA UN LUGAR RESERVADO PARA APARCAR VEHÍCULOS QUE SIRVEN A PERSONAS CON DISCAPACIDAD. Una sola correcta.\n\nLA SEÑAL. Cuadrado AZUL con una persona en SILLA DE RUEDAS en blanco.\n\nCUADRADO AZUL = INFORMACIÓN: esa plaza está reservada para los vehículos que transportan a personas con discapacidad (con su tarjeta). Los demás no pueden aparcar ahí.\n\n«ADVIERTE DE SU PRESENCIA» sería un triángulo. «PROHÍBE SU CIRCULACIÓN» sería un círculo rojo. «CARRIL PARA ELLOS» no es el significado.\n\nCLAVE: silla de ruedas en azul = plaza reservada. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5682,"bg":"Допълнителна задна светлина за мъгла е разрешено да се използва:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"при движение през нощта","ok":false,"i":null,"es":"de noche"},{"t":"винаги при намалена видимост","ok":false,"i":null,"es":"siempre con visibilidad reducida"},{"t":"само когато видимостта е намалена под 50 м","ok":true,"i":null,"es":"solo cuando la visibilidad está reducida por debajo de 50 m"}],"f":8,"es":"La luz antiniebla trasera adicional está permitido usarla:","explain":"La antiniebla trasera solo con visibilidad reducida por debajo de 50 m: es una luz muy intensa que deslumbra al que te sigue. De noche despejada o con niebla ligera está prohibida."},{"id":5712,"bg":"При пътуване на дълги разстояния за водачът с малък опит ще бъде по-безопасно ако:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"избягва пътуването през нощта","ok":true,"i":null,"es":"evitar viajar de noche"},{"t":"не се движи с високи скорости","ok":true,"i":null,"es":"no circular a altas velocidades"},{"t":"избягва движението по автомагистрали","ok":false,"i":null,"es":"evitar circular por autopistas"}],"f":8,"es":"En viajes de larga distancia, para el conductor con poca experiencia será más seguro si: (2 correctas)","explain":"Para el conductor novato es más seguro evitar la noche (menos visibilidad, más fatiga) y no ir a altas velocidades. Las autopistas NO deben evitarse: estadísticamente son las vías más seguras."},{"id":5716,"bg":"Какви са последиците за водача, когато той управлява продържително време при нерегулирана седалка?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"по-бързо настъпване на умора","ok":true,"i":null,"es":"la aparición más rápida de la fatiga"},{"t":"натоварване и болки в гръбначния стълб и мускулатурата","ok":true,"i":null,"es":"sobrecarga y dolores en la columna vertebral y la musculatura"},{"t":"остава по-дълго време концентриран","ok":false,"i":null,"es":"permanece concentrado durante más tiempo"},{"t":"намаляване на умората","ok":false,"i":null,"es":"la reducción de la fatiga"}],"f":8,"es":"¿Cuáles son las consecuencias para el conductor cuando conduce mucho tiempo con el asiento mal regulado? (2 correctas)","explain":"Asiento mal regulado durante horas = fatiga más rápida y sobrecarga con dolores en columna y musculatura. Jamás mejora la concentración: la postura incorrecta la deteriora."},{"id":6129,"bg":"Какво въздействие оказва приемането на голямо количество тонизиращи напитки - кафе или чай, за преодоляване умората на водача?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"има кратковременен ободрителен ефект","ok":true,"i":null,"es":"tiene un efecto estimulante de corta duración"},{"t":"може да предизвика нервно напрежение","ok":true,"i":null,"es":"puede provocar tensión nerviosa"},{"t":"позволява на водача да управлява продължително време без да чувства умора","ok":false,"i":null,"es":"permite al conductor conducir durante mucho tiempo sin sentir fatiga"}],"f":8,"es":"¿Qué efecto tiene tomar gran cantidad de bebidas estimulantes —café o té— para superar la fatiga del conductor? (2 correctas)","explain":"El café o té en gran cantidad da un estímulo de CORTA duración y puede provocar tensión nerviosa. No elimina la fatiga real: el único remedio verdadero es descansar."},{"id":6151,"bg":"При умора на водача риска от попадане в ПТП се повишава поради:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"притъпяване на бдителността","ok":true,"i":null,"es":"embotamiento de la atención (vigilancia)"},{"t":"понижаване на концентрацията на вниманието","ok":true,"i":null,"es":"la disminución de la concentración de la atención"},{"t":"намаляване на времето за реакция","ok":false,"i":null,"es":"la reducción del tiempo de reacción"}],"f":8,"es":"Con el conductor fatigado, el riesgo de accidente aumenta debido a: (2 correctas)","explain":"La fatiga aumenta el riesgo por el embotamiento de la vigilancia y la caída de la concentración. Ojo: el tiempo de reacción AUMENTA con la fatiga (la opción dice 'reducción', por eso es falsa)."},{"id":5993,"bg":"Разрешено ли е да превозвате пътници в товарно ремарке?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":8,"es":"¿Está permitido transportar pasajeros en un remolque de carga?","explain":"No: está prohibido transportar pasajeros en un remolque de carga. No tiene asientos, cinturones ni protección alguna para personas."},{"id":5996,"bg":"Задължение на водача е превозваният товар да бъде:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"покрит, когато отразява светлината и може да заслепи други участници в движението","ok":true,"i":null,"es":"cubierto, cuando refleja la luz y puede deslumbrar a otros usuarios de la vía"},{"t":"укрепен","ok":true,"i":null,"es":"sujeto (asegurado)"},{"t":"застрахован","ok":false,"i":null,"es":"asegurado"},{"t":"опакован съгласно изискванията на производителя","ok":false,"i":null,"es":"embalado según los requisitos del fabricante"}],"f":8,"es":"Es obligación del conductor que la carga transportada esté: (2 correctas)","explain":"La carga debe estar SUJETA (укрепен = bien amarrada) y cubierta cuando refleja la luz y puede deslumbrar. Ojo con la trampa lingüística: 'застрахован' (asegurado = con seguro) no es un requisito de la carga."},{"id":6008,"bg":"При движение през нощта по кой от изброените начини може да се обозначи товар, който излиза с повече от 1 м отпред на най-издадената част на превозното средство?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"с бял светлоотразител","ok":true,"i":null,"es":"con reflectante BLANCO"},{"t":"с бяла светлина","ok":true,"i":null,"es":"con luz BLANCA"},{"t":"с червен флаг","ok":false,"i":null,"es":"con bandera roja"},{"t":"с червена светлина","ok":false,"i":null,"es":"con luz ROJA"}],"f":8,"es":"De noche, ¿cómo puede señalizarse la carga que sobresale más de 1 m por DELANTE de la parte más saliente del vehículo? (2 correctas)","explain":"La carga sobresale por DELANTE (ojo: la pregunta dice 'отпред'): de noche se señaliza con reflectante BLANCO o luz BLANCA, los colores que corresponden al frente del vehículo. La bandera roja es señalización diurna y la luz roja corresponde a salientes TRASEROS."},{"id":6013,"bg":"Товарът не се обозначава, ако излиза отстрани на най-издадената част на ППС на разстояние:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"до 0,2 м","ok":true,"i":null,"es":"hasta 0.2 m"},{"t":"до 0,5 м","ok":false,"i":null,"es":"hasta 0.5 m"},{"t":"до 1,0 м","ok":false,"i":null,"es":"hasta 1.0 m"},{"t":"до 1,5 м","ok":false,"i":null,"es":"hasta 1.5 m"}],"f":8,"es":"La carga no necesita señalizarse si sobresale POR LOS LADOS:","explain":"Hasta 0,2 m por los lados no se exige señalización: es el margen tolerado. Cualquier saliente lateral mayor debe señalizarse porque invade el espacio de otros carriles."},{"id":5451,"bg":"Извършва ли нарушение водач, който при изпреварване принуждава изпреварваното ППС да промени посоката си на движение?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":8,"es":"¿Comete infracción el conductor que, al adelantar, obliga al vehículo adelantado a cambiar su dirección de marcha?","explain":"Sí, comete infracción: el que adelanta no puede obligar al adelantado a cambiar su trayectoria ni su velocidad. Si tu maniobra fuerza al otro a apartarse, la has hecho mal legalmente."},{"id":8300,"bg":"Подлежи ли на наказание водач, който без да има това право, паркира на място определено за превозно средство обслужващо хора с трайни увреждания?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"},{"t":"не, освен в случаите, когато превозното средство се паркира на това място през нощта","ok":false,"i":null,"es":"no, salvo cuando el vehículo se estaciona en ese lugar durante la noche"}],"f":8,"es":"¿Es sancionable el conductor que, sin tener derecho, estaciona en un lugar reservado a vehículos que atienden a personas con discapacidad permanente?","explain":"Sí, es sancionable: estacionar sin derecho en plaza reservada para personas con discapacidad es infracción a cualquier hora, también de noche."},{"id":5319,"bg":"Разрешено ли е да се премества превозно средство участвало в пътнотранспортно произшествие с пострадали хора?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да, когато с него трябва да се превозят пострадалите до здравно заведение","ok":true,"i":null,"es":"sí, cuando con él haya que transportar a los heridos a un centro de salud"},{"t":"да, когато пречи на движението","ok":true,"i":null,"es":"sí, cuando obstaculiza el tráfico"},{"t":"да, разрешено е във всички случаи","ok":false,"i":null,"es":"sí, está permitido en todos los casos"},{"t":"не, забранено е във всички случаи","ok":false,"i":null,"es":"no, está prohibido en todos los casos"}],"f":8,"es":"¿Está permitido mover un vehículo implicado en un accidente de tráfico con personas heridas? (2 correctas)","explain":"Se puede mover el vehículo del accidente con heridos en dos casos: para transportar a los heridos a un centro de salud o cuando obstaculiza el tráfico. Fuera de eso, la posición debe conservarse para el atestado."},{"id":5321,"bg":"Кои от изброените действия трябва да предприеме водачът при ПТП с превозно средство обозначено с опознавателен знак за опасен товар:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да стои на безопасно разстояние от превозното средство освен ако се налага да спаси нечий живот","ok":true,"i":null,"es":"mantenerse a distancia segura del vehículo, salvo que haya que salvar la vida de alguien"},{"t":"да се отнася внимателно с изсипания на пътя товар независимо от неговото количество","ok":true,"i":null,"es":"tratar con cuidado la carga derramada en la vía, independientemente de su cantidad"},{"t":"да премести това превозно средство извън платното за движение","ok":false,"i":null,"es":"apartar ese vehículo fuera de la calzada"},{"t":"да отстрани опасния товар от пътя","ok":false,"i":null,"es":"retirar la carga peligrosa de la vía"}],"f":8,"es":"¿Cuáles de las acciones indicadas debe emprender el conductor en un accidente con un vehículo señalizado con el distintivo de mercancías peligrosas?: (2 correctas)","explain":"Con mercancías peligrosas: mantente a distancia segura (salvo para salvar una vida) y trata con extremo cuidado cualquier derrame. Apartar el vehículo o retirar la carga tú mismo puede provocar la catástrofe que intentas evitar."},{"id":5348,"bg":"Задължен ли е водачът участник в ПТП без пострадали хора да оказва съдействие за установяване на вредите от произшествието?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да, във всички случаи","ok":true,"i":null,"es":"sí, en todos los casos"},{"t":"да, но само когато вредите са значителни","ok":false,"i":null,"es":"sí, pero solo cuando los daños son significativos"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":8,"es":"¿Está obligado el conductor implicado en un accidente sin heridos a colaborar en la determinación de los daños del accidente?","explain":"Sí, en todos los casos: en un accidente sin heridos los implicados están obligados a colaborar en la determinación de los daños, sean grandes o pequeños (rellenar el parte amistoso, intercambiar datos)."},{"id":5354,"bg":"Телефонен номер 112 е:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"единен европейски телефонен номер за спешни и аварийни обаждания","ok":true,"i":null,"es":"el número único europeo de emergencias"},{"t":"телефонен номер за денонощна пътна помощ","ok":false,"i":null,"es":"el número de asistencia en carretera 24 horas"}],"f":8,"es":"El número de teléfono 112 es:","explain":"El 112 es el número único europeo de emergencias: policía, bomberos y ambulancia en toda la UE. No es un servicio de asistencia mecánica en carretera."},{"id":5543,"bg":"След кой от тези знаци е забранено спирането за престой върху платното за движение?","p":1,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42085.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42086.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42087.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42088.png","es":""}],"f":8,"es":"¿Después de cuál de estas señales está prohibida la parada breve en la calzada? (3 correctas)","explain":"LA PRIMERA, LA SEGUNDA Y LA TERCERA. Tres correctas.\n\nQUÉ VES. Cuatro señales: 1) PROHIBIDO ADELANTAR; 2) PROHIBIDO ADELANTAR A LOS CAMIONES; 3) círculo azul con borde rojo y DOS barras en aspa (prohibida la parada y el estacionamiento); 4) el mismo con UNA sola barra (prohibido estacionar).\n\nDONDE ESTÁ PROHIBIDO ADELANTAR, TAMBIÉN ESTÁ PROHIBIDO DETENERSE Y APARCAR SOBRE LA CALZADA: un vehículo parado ahí obligaría a los demás a rebasarlo justo donde no se puede.\n\nLA DEL ASPA lo prohíbe directamente.\n\n«LA DE UNA SOLA BARRA» es el cebo: prohíbe aparcar, pero deja hacer la parada breve.\n\nCLAVE: compárala con la 5548 (la misma pregunta sobre el estacionamiento). Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5902,"bg":"Значението на кой от показаните немигащи сигнали на светофара е “Преминаването е забранено”?","p":3,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42121.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42122.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42123.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42124.png","es":""}],"f":8,"es":"¿Cuál de las señales fijas (no parpadeantes) del semáforo mostradas significa 'Prohibido el paso'? (2 correctas)","explain":"Las DOS primeras: el semáforo con la luz ROJA sola y el semáforo con ROJA + ÁMBAR encendidas a la vez.\n\nROJO SOLO es la prohibición básica: no puedes entrar en el cruce ni rebasar la línea de detención.\n\nROJO + ÁMBAR es la misma prohibición con un aviso añadido: el verde está a punto de llegar. El rojo sigue encendido, así que el paso sigue prohibido. Es la que más gente falla, porque el ámbar hace pensar en «prepárate para salir» y se lee como permiso.\n\nEL VERDE es la tercera imagen: paso permitido. Descartado.\n\nEL ÁMBAR SOLO es la cuarta y aquí está la trampa fina. También impide entrar en el cruce, pero su significado oficial en la ley es «Внимание! Спри!» — atención, para —, no «преминаването е забранено». La pregunta pide literalmente las señales que significan «prohibido el paso», y esa etiqueta la llevan solo el rojo y el rojo+ámbar.\n\nCLAVE: para esta pregunta, «prohibido el paso» = las dos que llevan rojo encendido. El ámbar solo tiene nombre propio y va en otra pregunta."},{"id":13554,"bg":"Когато няма други ограничения, водачът на МПС от категория В при движение по автомагистрала не трябва да превишава:","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"140 km/h","ok":true,"i":null,"es":"140 km/h"},{"t":"100 km/h","ok":false,"i":null,"es":"100 km/h"},{"t":"110 km/h","ok":false,"i":null,"es":"110 km/h"},{"t":"120 km/h","ok":false,"i":null,"es":"120 km/h"}],"f":8,"es":"Cuando no hay otras restricciones, el conductor de un vehículo categoría B en autopista no debe superar:","explain":"140 km/h: es el límite de los turismos categoría B en autopista búlgara cuando no hay otra restricción señalizada. En vía rápida baja a 120 y fuera de población a 90."},{"id":5239,"bg":"Номерът на път по международната класификация се означава с:","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/20034.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/20035.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/20036.png","es":""}],"f":8,"es":"El número de una carretera según la clasificación internacional se indica con:","explain":"LA PRIMERA: RECTÁNGULO VERDE «E 79». Una sola correcta.\n\nQUÉ VES. Tres placas: 1) verde con «E 79»; 2) verde con «A 2»; 3) azul con «81».\n\nLA LETRA «E» ES LA RED INTERNACIONAL (carreteras europeas). Esas placas son verdes con la «E» delante del número.\n\n«A 2» (verde, con «A») es la numeración de una autopista búlgara, y el número solo sobre fondo azul es otra numeración nacional: ninguna de las dos es la clasificación internacional.\n\nCLAVE: la letra E delante del número = carretera internacional. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5249,"bg":"Кой от пътните знаци предупреждава, че платното за движение е стеснено отдясно?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334669.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/21263.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/21264.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334667.png","es":""}],"f":8,"es":"¿Cuál de las señales advierte que la calzada se estrecha por la derecha?","explain":"LA PRIMERA: TRIÁNGULO CON LA CALZADA QUE SE ESTRECHA POR LA DERECHA. Una sola correcta.\n\nQUÉ VES. Cuatro señales: 1) triángulo de peligro con dos líneas, y la de la DERECHA se mete hacia dentro; 2) cuadrado azul con dos flechas, la de la derecha se une a la otra (fin de un carril); 3) señal amarilla de desvío por obras; 4) triángulo con un coche patinando sobre gravilla (arcén o firme deslizante).\n\nEL ESTRECHAMIENTO POR LA DERECHA ES EL TRIÁNGULO cuya línea derecha se curva hacia el centro.\n\n«EL CUADRADO AZUL» es el cebo fino: indica que un CARRIL se acaba y hay que incorporarse, no que la calzada se estreche (y es azul: información, no peligro).\n\nCLAVE: triángulo = peligro; mira de qué lado se dobla la línea. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5548,"bg":"След кой от тези знаци е забранено паркирането върху платното за движение?","p":1,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42142.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/160215.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42087.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42088.png","es":""}],"f":8,"es":"¿Después de cuál de estas señales está prohibido el estacionamiento en la calzada? (3 correctas)","explain":"LA PRIMERA, LA TERCERA Y LA CUARTA. Tres correctas.\n\nQUÉ VES. Cuatro señales: 1) PROHIBIDO ADELANTAR; 2) «МИТНИЦА / DOUANE» (prohibido pasar sin detenerse); 3) DOS barras en aspa (prohibida la parada y el estacionamiento); 4) UNA barra (prohibido estacionar).\n\nDONDE ESTÁ PROHIBIDO ADELANTAR, TAMBIÉN ESTÁ PROHIBIDO DETENERSE Y APARCAR SOBRE LA CALZADA: un vehículo parado ahí obligaría a los demás a rebasarlo justo donde no se puede.\n\nLAS DOS AZULES prohíben aparcar: la de una barra y la del aspa.\n\n«LA ADUANA» es el cebo: te obliga a parar un momento, no prohíbe aparcar.\n\nCLAVE: compárala con la 5543. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5432,"bg":"Когато налягането на въздуха в автомобилната гума е по-ниско от предписаното, протекторът на гумата се износва:","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"в двата края, по цялата окръжност","ok":true,"i":null,"es":"en ambos bordes, en toda la circunferencia"},{"t":"неравномерно, на отделни места","ok":false,"i":null,"es":"de forma irregular, en puntos aislados"},{"t":"в средата на протектора по цялата окръжност","ok":false,"i":null,"es":"en el centro de la banda de rodadura, en toda la circunferencia"},{"t":"винаги в дясната част по посока на въртенето","ok":false,"i":null,"es":"siempre en la parte derecha según el sentido de giro"}],"f":7,"es":"Cuando la presión de aire del neumático es más baja que la prescrita, la banda de rodadura se desgasta:","explain":"Con presión baja el neumático se apoya en los BORDES y se desgasta por ambos lados de la banda en toda la circunferencia. El desgaste central es el síntoma contrario (presión alta); los puntos aislados indican otros defectos."},{"id":6159,"bg":"Антиблокиращата спирачна система (ABS) не допуска блокирането на:","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"колелата на автомобила в процеса на спиране","ok":true,"i":null,"es":"las ruedas del automóvil durante la frenada"},{"t":"спирачния педал","ok":false,"i":null,"es":"el pedal de freno"},{"t":"буталото в главния спирачен цилиндър","ok":false,"i":null,"es":"el pistón del cilindro maestro de freno"}],"f":7,"es":"El sistema antibloqueo de frenos (ABS) no permite el bloqueo de:","explain":"El ABS impide el bloqueo de las RUEDAS al frenar: modula la presión para que sigan girando y puedas dirigir. No tiene nada que ver con bloquear el pedal ni el pistón del cilindro maestro."},{"id":6163,"bg":"В кой случай ефектът от действието на антиблокиращата спирачна система (ABS) е най–голям?","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"при спиране на хлъзгъв път","ok":true,"i":null,"es":"al frenar en carretera resbaladiza"},{"t":"при спиране на сух път","ok":false,"i":null,"es":"al frenar en carretera seca"},{"t":"когато накладките на спирачните механизми са износени","ok":false,"i":null,"es":"cuando las pastillas de freno están desgastadas"}],"f":7,"es":"¿Cuándo es mayor el efecto del sistema ABS?","explain":"El ABS rinde más en carretera RESBALADIZA: ahí es donde las ruedas se bloquearían con facilidad y el sistema marca la diferencia entre dirigir o deslizar. En seco casi no interviene, y las pastillas gastadas son otro problema."},{"id":5442,"bg":"Как се контролира нивото на течността в охладителната уредба на МПС?","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"като се следи нивото на течността в разширителния резервоар","ok":true,"i":null,"es":"vigilando el nivel del líquido en el depósito de expansión"},{"t":"зависи от вида на охладителната течност","ok":false,"i":null,"es":"depende del tipo de líquido refrigerante"},{"t":"нивото на течността в охладителната уредба не се контролира","ok":false,"i":null,"es":"el nivel del líquido del sistema de refrigeración no se controla"}],"f":7,"es":"¿Cómo se controla el nivel del líquido del sistema de refrigeración del vehículo?","explain":"El nivel del refrigerante se controla mirando el depósito de expansión (entre MIN y MAX, en frío). No depende del tipo de líquido y por supuesto que se controla: quedarse sin refrigerante funde el motor."},{"id":6156,"bg":"Вредно ли е за хората шумовото замърсяване, предизвикано от превозните средства при движение?","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":7,"es":"¿Es dañina para las personas la contaminación acústica que producen los vehículos al circular?","explain":"Sí: el ruido del tráfico es contaminación acústica dañina: estrés, trastornos del sueño y problemas cardiovasculares en la población expuesta. Es parte del bloque de conducción responsable."},{"id":5220,"bg":"Кои от изброените правила се прилагат при движение в населено място?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"пътниците в лекия автомобил може да не използват обезопасителните колани","ok":false,"i":null,"es":"los pasajeros del turismo pueden no usar los cinturones de seguridad"},{"t":"по двулентовите двупосочни пътища пешеходците могат да пресичат платното за движение и извън пешеходните пътеки","ok":true,"i":null,"es":"en vías de dos carriles y doble sentido los peatones pueden cruzar la calzada también fuera de los pasos de peatones"},{"t":"допуска се паркиране на платното за движение","ok":true,"i":null,"es":"se permite estacionar en la calzada"},{"t":"може да се паркира на обозначени места върху тротоарите","ok":true,"i":null,"es":"se puede estacionar en lugares señalizados sobre las aceras"}],"f":7,"es":"¿Cuáles de las siguientes normas se aplican al circular en población? (3 correctas)","explain":"En población: los peatones pueden cruzar fuera de los pasos en vías de dos carriles y doble sentido, se permite estacionar en la calzada y también sobre aceras EN lugares señalizados. Los cinturones son SIEMPRE obligatorios: esa es la falsa."},{"id":5233,"bg":"Този пътен знак:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/23560.png","v":null,"a":[{"t":"предупреждава за кръстовище с път без предимство","ok":true,"i":null,"es":"advierte de una intersección con una vía sin prioridad"},{"t":"указва, че на следващото кръстовище задължително трябва да се премине направо","ok":false,"i":null,"es":"indica que en la próxima intersección es obligatorio seguir de frente"},{"t":"сигнализира за край на пътя с предимство","ok":false,"i":null,"es":"señaliza el fin de la vía con prioridad"},{"t":"сигнализира за начало на пътя с предимство","ok":false,"i":null,"es":"señaliza el inicio de la vía con prioridad"}],"f":7,"es":"Esta señal de tráfico:","explain":"ADVIERTE DE UNA INTERSECCIÓN CON UNA VÍA SIN PRIORIDAD. Una sola correcta.\n\nLA SEÑAL. Triángulo de peligro con un trazo vertical GRUESO cruzado por trazos FINOS a ambos lados.\n\nCÓMO SE LEEN LAS SEÑALES DE CRUCE (triángulos con trazos):\n• trazo GRUESO = tu vía, la que tiene prioridad;\n• trazo FINO = la vía sin prioridad que llega al cruce (por un lado, por el otro o por ambos);\n• una X (dos trazos iguales cruzados) = cruce de vías iguales, sin prioridad para nadie.\n\n«OBLIGA A SEGUIR RECTO» confunde el dibujo con una flecha: es un triángulo (aviso), no un círculo azul (obligación).\n\n«FIN» o «INICIO DE LA VÍA CON PRIORIDAD» son el rombo tachado y el rombo.\n\nCLAVE: triángulo con trazo grueso = vas por la principal y se acerca un cruce. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6028,"bg":"При тази ситуация задължени ли сте да се съобразявате с поведението на децата?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/25999.png","v":null,"a":[{"t":"да, защото са в близост до платното за движение","ok":true,"i":null,"es":"sí, porque están cerca de la calzada"},{"t":"да, защото са деца","ok":true,"i":null,"es":"sí, porque son niños"},{"t":"не, защото се движат по тротоара","ok":false,"i":null,"es":"no, porque van por la acera"},{"t":"не, защото ме виждат","ok":false,"i":null,"es":"no, porque me ven"}],"f":7,"es":"En esta situación, ¿estás obligado a tener en cuenta el comportamiento de los niños? (2 correctas)","explain":"SÍ, PORQUE ESTÁN CERCA DE LA CALZADA, Y SÍ, PORQUE SON NIÑOS. Dos correctas.\n\nQUÉ VES. Calle urbana. En la acera DERECHA, un NIÑO con un balón y otra persona caminan junto al bordillo.\n\nLOS NIÑOS SON IMPREVISIBLES Y ESTÁN AL LADO DE LA CALZADA. Aunque vayan por la acera, pueden bajar de repente (sobre todo con un balón). Tienes que contar con ello y moderar la velocidad.\n\n«NO, PORQUE VAN POR LA ACERA» y «NO, PORQUE ME VEN» son los cebos: que estén en la acera o te hayan visto no garantiza nada con un niño.\n\nCLAVE: niño cerca de la calzada = prepárate para que baje. Ver Leyes → «Niños en la vía»."},{"id":6066,"bg":"За какво сигнализира стоящият на тротоара пешеходец, когато е с изпъната нагоре или напречно на пътя ръка?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"за намерението си да навлезе на платното за движение","ok":true,"i":null,"es":"de su intención de entrar en la calzada"},{"t":"указва на водачите, че ще изчака преминаващите автомобили","ok":false,"i":null,"es":"indica a los conductores que esperará a que pasen los automóviles"},{"t":"дава знак на другите пешеходци, че могат да преминат през платното за движение","ok":false,"i":null,"es":"hace una señal a los demás peatones de que pueden cruzar la calzada"},{"t":"дава знак на другите пешеходци, да не преминават през платното за движение","ok":false,"i":null,"es":"hace una señal a los demás peatones de que no crucen la calzada"}],"f":7,"es":"¿Qué señaliza el peatón parado en la acera con el brazo extendido hacia arriba o en perpendicular a la carretera?","explain":"El peatón con el brazo extendido en alto o perpendicular a la vía señala su INTENCIÓN DE ENTRAR en la calzada: es su forma legal de anunciar el cruce. No es una señal hacia otros peatones ni una renuncia a cruzar."},{"id":6692,"bg":"Пътното превозно средство е извънгабаритно когато:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"височината му, включително товара, е 4,5 м","ok":true,"i":null,"es":"4.5 m"},{"t":"широчината му, включително товара, е 2,8 м","ok":true,"i":null,"es":"su ANCHURA, incluyendo carga, es 2.8 m"},{"t":"дължината му, включително товара, е 9 м","ok":false,"i":null,"es":"su LONGITUD, incluyendo carga, es 9 m"}],"f":7,"es":"Un vehículo es 'fuera de gálibo' cuando: (2 correctas)","explain":"Un vehículo es 'fuera de gálibo' si supera los límites: altura mayor de 4 m (por eso 4,5 m cuenta) o anchura mayor de 2,55 m (por eso 2,8 m cuenta). Una longitud de 9 m NO supera el límite legal de longitud."},{"id":11820,"bg":"С този опознавателен знак се обозначават:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123828421.png","v":null,"a":[{"t":"само ремаркетата с маса над 750 kg","ok":false,"i":null,"es":"solo los remolques de masa superior a 750 kg"},{"t":"всички ремаркета, независимо от тяхната маса","ok":true,"i":null,"es":"todos los remolques, independientemente de su masa"},{"t":"само ремаркетата с две и повече оси","ok":false,"i":null,"es":"solo los remolques de dos o más ejes"},{"t":"всички ремаркета, независимо от броя на осите","ok":true,"i":null,"es":"todos los remolques, independientemente del número de ejes"}],"f":7,"es":"Con este signo distintivo se identifican: (2 correctas)","explain":"TODOS LOS REMOLQUES, INDEPENDIENTEMENTE DE SU MASA, Y TODOS, INDEPENDIENTEMENTE DEL NÚMERO DE EJES. Dos correctas.\n\nQUÉ VES. La parte trasera de un REMOLQUE con dos placas verticales AMARILLAS con BORDE ROJO.\n\nESTA PLACA LA LLEVAN TODOS LOS REMOLQUES, sin distinción de peso ni de ejes.\n\n«SOLO LOS DE MÁS DE 750 kg» y «SOLO LOS DE DOS O MÁS EJES» son cebos que inventan una condición.\n\nCLAVE: amarillo con borde rojo = remolque, cualquiera. Compárala con la 11816."},{"id":6280,"bg":"В кои случаи, при тази допълнителна табела, водачът е задължен да спазва забраната, въведена с пътния знак?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/159579.png","v":null,"a":[{"t":"при снеговалеж","ok":true,"i":null,"es":"cuando nieva"},{"t":"при сняг на платното за движение","ok":true,"i":null,"es":"con nieve en la calzada"},{"t":"при температури, при които пътното покритие може да се заледи","ok":true,"i":null,"es":"con temperaturas en las que el pavimento puede helarse"},{"t":"при силен дъжд","ok":false,"i":null,"es":"con lluvia intensa"}],"f":7,"es":"¿En qué casos, con esta tablilla adicional, el conductor está obligado a respetar la prohibición de la señal? (3 correctas)","explain":"CUANDO NIEVA, CON NIEVE EN LA CALZADA Y CON TEMPERATURAS EN LAS QUE EL PAVIMENTO PUEDE HELARSE. Tres correctas.\n\nQUÉ VES. Una señal de PROHIBIDO ESTACIONAR (círculo azul con borde rojo y una barra roja) con una placa debajo con un COPO DE NIEVE.\n\nLA PLACA LIMITA CUÁNDO SE APLICA LA SEÑAL: solo en condiciones invernales. Es decir, cuando nieva, cuando hay nieve en la calzada y cuando la temperatura permite que se forme hielo (por ejemplo, para dejar paso a las máquinas quitanieves).\n\n«CON LLUVIA INTENSA» es el cebo: la lluvia no es una condición invernal; el copo de nieve no la incluye.\n\nCLAVE: la placa complementaria dice cuándo o a quién se aplica la señal principal. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6287,"bg":"На какво разстояние след знака, когато е поставен извън населено място, се намира опасният завой?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/55851.png","v":null,"a":[{"t":"от 100 до 150 м","ok":true,"i":null,"es":"entre 100 y 150 m"},{"t":"от 150 до 200 м","ok":false,"i":null,"es":"entre 150 y 200 m"},{"t":"от 200 до 500 м","ok":false,"i":null,"es":"entre 200 y 500 m"},{"t":"над 500 м","ok":false,"i":null,"es":"más de 500 m"}],"f":7,"es":"¿A qué distancia después de la señal, colocada fuera de población, está la curva peligrosa?","explain":"ENTRE 100 Y 150 m. Una sola correcta.\n\nLA SEÑAL. Triángulo de CURVA PELIGROSA a la derecha, colocado FUERA de población.\n\nLAS SEÑALES DE PELIGRO SE COLOCAN ANTES DEL PELIGRO:\n• fuera de población: de 100 a 150 m;\n• en población: de 50 a 100 m.\n\n«150-200 m», «200-500 m» y «más de 500 m» son demasiado lejos: si la distancia es distinta, lo indica una placa.\n\nCLAVE: compárala con la 11888 y la 6288. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5834,"bg":"За кой от водачите, това положение на тялото и ръцете на регулировчика е сигнал, че може да премине направо или да завие надясно?","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/24064.png","v":null,"a":[{"t":"на жълтия автомобил","ok":true,"i":null,"es":"para el coche amarillo"},{"t":"на синия автомобил","ok":true,"i":null,"es":"para el coche azul"},{"t":"на червения автомобил","ok":false,"i":null,"es":"para el coche rojo"},{"t":"на зеления автомобил","ok":false,"i":null,"es":"para el coche verde"}],"f":7,"es":"¿Para qué conductores esta posición del cuerpo y los brazos del agente significa que pueden seguir recto o girar a la derecha? (2 correctas)","explain":"PARA EL COCHE AMARILLO Y PARA EL COCHE AZUL. Dos correctas.\n\nQUÉ VES. Un AGENTE en el centro del cruce con los BRAZOS BAJADOS. Está de cara al coche ROJO (le muestra el pecho) y de espaldas al VERDE. El AMARILLO (a la izquierda) y el AZUL (a la derecha) lo ven de COSTADO.\n\nCÓMO SE LEE AL AGENTE CON LOS BRAZOS EXTENDIDOS O BAJADOS:\n• Si te muestra el COSTADO (izquierdo o derecho): puedes seguir RECTO o girar a la DERECHA.\n• Si te muestra el PECHO o la ESPALDA: prohibido pasar.\n\nPOR ESO pueden seguir recto o girar a la derecha el amarillo y el azul, que ven sus costados. El rojo (pecho) y el verde (espalda) tienen que parar.\n\n«EL ROJO» y «EL VERDE» son los cebos: están justo delante y detrás del agente, que es justo la posición que obliga a parar.\n\nCLAVE: costado = paso (recto y derecha); pecho o espalda = parar. Ver Leyes → «Quién manda sobre quién»."},{"id":5853,"bg":"Сигналът на регулировчика означава, че:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/35066.png","v":null,"a":[{"t":"мога да премина направо","ok":true,"i":null,"es":"continuar recto"},{"t":"мога да завия надясно","ok":true,"i":null,"es":"puedo girar a la derecha"},{"t":"мога да завия наляво","ok":false,"i":null,"es":"puedo girar a la izquierda"},{"t":"мога да завия в обратна посока","ok":false,"i":null,"es":"puedo dar la vuelta"}],"f":7,"es":"La señal del agente regulador significa que puedo: (2 correctas)","explain":"PUEDO SEGUIR RECTO Y PUEDO GIRAR A LA DERECHA. Dos correctas.\n\nQUÉ VES. Un AGENTE en el cruce, con los BRAZOS BAJADOS, que te muestra su COSTADO.\n\nCÓMO SE LEE AL AGENTE CON LOS BRAZOS EXTENDIDOS O BAJADOS:\n• Si te muestra el COSTADO (izquierdo o derecho): puedes seguir RECTO o girar a la DERECHA.\n• Si te muestra el PECHO o la ESPALDA: prohibido pasar.\n\n«GIRAR A LA IZQUIERDA» y «DAR LA VUELTA» son los cebos: con el agente de costado solo se permite recto y derecha.\n\nCLAVE: costado = recto y derecha, nada más. Compárala con la 5834 (la misma posición vista desde varios coches). Ver Leyes → «Quién manda sobre quién»."},{"id":5867,"bg":"За кой от водачите, това положение на тялото и ръцете на регулировчика е сигнал, значението на който е „Преминаването е забранено”?","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/36578.png","v":null,"a":[{"t":"на червения автомобил","ok":true,"i":null,"es":"para el coche rojo"},{"t":"на зеления автомобил","ok":true,"i":null,"es":"para el coche verde"},{"t":"на жълтия автомобил","ok":true,"i":null,"es":"para el coche amarillo"},{"t":"на синия автомобил","ok":false,"i":null,"es":"para el coche azul"}],"f":7,"es":"¿Para qué conductores esta posición del cuerpo y los brazos del agente es una señal cuyo significado es 'El paso está prohibido'? (3 correctas)","explain":"El ROJO, el VERDE y el AMARILLO. Tres de los cuatro.\n\nLA POSTURA. El agente está DE CARA a ti (el coche rojo), con el brazo derecho extendido horizontalmente hacia delante.\n\nCON ESTE GESTO SOLO PASA UNO: el que está frente a su hombro izquierdo. Como está de cara a ti, su izquierda es tu derecha: el AZUL. Todos los demás quedan prohibidos, y por eso la respuesta son tres.\n\nEL ROJO le ve el pecho. EL VERDE le ve la espalda. EL AMARILLO le ve el hombro derecho — y es hacia donde apunta la porra, que es justo lo que hace caer a mucha gente.\n\nEL GESTO, EN LA LEY (чл. 10, ал. 2, т. 3 ЗДвП): «дясна ръка, протегната хоризонтално напред» — brazo derecho extendido horizontalmente hacia delante. «Преминаването е разрешено» solo para quien está frente al hombro IZQUIERDO del agente (y para los peatones que cruzan por detrás de su espalda); «Преминаването е забранено» para todos los demás.\n\nMÉTODO: 1) ¿brazo vertical? alto total. 2) ¿qué te muestra a TI: pecho, espalda o costado? pecho y espalda son muro siempre. 3) ¿costado sin brazo extendido? pasas, recto o derecha. 4) ¿costado CON brazo extendido? solo el izquierdo pasa. Está desarrollado con casos en Leyes → «Quién manda sobre quién».\n\nCLAVE: es la pregunta espejo de la 5857 sobre la misma postura. Con brazo extendido, tres de cuatro siempre están parados. Si dudas, busca primero el ÚNICO que pasa y marca el resto."},{"id":5891,"bg":"Значението на този немигащ сигнал на светофара е:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/39865.png","v":null,"a":[{"t":"„Преминаването е забранено”","ok":true,"i":null,"es":"'El paso está prohibido'"},{"t":"„Преминаването е разрешено”","ok":false,"i":null,"es":"'El paso está permitido'"},{"t":"„Внимание!”","ok":false,"i":null,"es":"'¡Atención!'"},{"t":"„Внимание, спри!”","ok":false,"i":null,"es":"'¡Atención, para!'"}],"f":7,"es":"El significado de esta señal fija del semáforo es:","explain":"«EL PASO ESTÁ PROHIBIDO». Una sola correcta.\n\nQUÉ VES. Un semáforo con la luz ROJA encendida, fija.\n\nROJO FIJO = «ПРЕМИНАВАНЕТО Е ЗАБРАНЕНО». Es la prohibición de pasar.\n\n«¡ATENCIÓN, PARA!» es el nombre oficial del ÁMBAR fijo, no del rojo. Es el cebo principal: los dos impiden entrar, pero cada luz tiene su nombre.\n\n«¡ATENCIÓN!» es el ámbar INTERMITENTE.\n\n«EL PASO ESTÁ PERMITIDO» es el verde.\n\nCLAVE: memoriza los cuatro nombres: rojo = paso prohibido; ámbar fijo = atención, para; ámbar intermitente = atención; verde = paso permitido. Ver Leyes → «El semáforo: cada luz tiene un nombre oficial»."},{"id":5918,"bg":"Значението на жълтата мигаща светлина на светофара е:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43915.png","v":null,"a":[{"t":"„Внимание”","ok":true,"i":null,"es":"'¡Atención!'"},{"t":"„Преминаването е забранено”","ok":false,"i":null,"es":"'El paso está prohibido'"},{"t":"„Внимание, спри!”","ok":false,"i":null,"es":"'¡Atención, para!'"},{"t":"„Преминаването без спиране е забранено”","ok":false,"i":null,"es":"'Paso sin detenerse prohibido'"}],"f":7,"es":"El significado de la luz amarilla parpadeante del semáforo es:","explain":"«¡ATENCIÓN!». Una sola correcta.\n\nQUÉ VES. Un semáforo con la luz ÁMBAR encendida (la pregunta indica que es INTERMITENTE).\n\nÁMBAR INTERMITENTE = «ВНИМАНИЕ» (¡ATENCIÓN!). El semáforo no regula el cruce en ese momento: pasas con precaución, aplicando las señales o la regla de la derecha.\n\n«¡ATENCIÓN, PARA!» es el nombre del ámbar FIJO. Es el cebo principal.\n\n«PASO PROHIBIDO» es el rojo. «PASAR SIN DETENERSE ESTÁ PROHIBIDO» es lo que indica un STOP, no un semáforo.\n\nCLAVE: los cuatro nombres oficiales: rojo = paso prohibido; ámbar fijo = atención, para; ámbar intermitente = atención; verde = paso permitido. Compárala con la 5915 y la 5891. Ver Leyes → «El semáforo: cada luz tiene un nombre oficial»."},{"id":5933,"bg":"Този светлинен сигнал:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/44686.png","v":null,"a":[{"t":"сигнализира, че навлизането по пътната лента, над която е поставен, е забранено","ok":true,"i":null,"es":"indica que la entrada al carril sobre el que está es PROHIBIDA"},{"t":"указва, че е забранено движението в най-лявата пътна лента","ok":false,"i":null,"es":"indica que está prohibido el carril izquierdo"},{"t":"указва място за задължително спиране","ok":false,"i":null,"es":"indica lugar de parada obligatoria"},{"t":"забранява движението по пътното платно над което е поставен","ok":false,"i":null,"es":"prohíbe la circulación en toda la calzada"}],"f":7,"es":"Esta señal luminosa:","explain":"INDICA QUE LA ENTRADA AL CARRIL SOBRE EL QUE ESTÁ ES PROHIBIDA. Una sola correcta.\n\nQUÉ VES. Un pórtico sobre la calzada con semáforos de carril. Sobre el carril izquierdo se ve un ASPA ROJA (X); sobre el otro, la luz está apagada.\n\nEL ASPA ROJA CIERRA SOLO SU CARRIL. Por ese carril no se puede circular; los demás no quedan afectados por esta luz.\n\n«PROHÍBE CIRCULAR POR TODA LA CALZADA» es el cebo de quien extiende la prohibición a todos los carriles.\n\n«PROHIBIDO EL CARRIL IZQUIERDO» parece correcto en esta imagen, pero la señal no significa «el izquierdo», sino «el carril sobre el que está», sea cual sea.\n\n«LUGAR DE PARADA OBLIGATORIA» no tiene relación con esta luz.\n\nCLAVE: aspa roja = carril cerrado; flecha verde = carril abierto (compárala con la 5930). Ver Leyes → «El semáforo: cada luz tiene un nombre oficial»."},{"id":6073,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/60166.png","v":null,"a":[{"t":"следва участък от пътя с двупосочно движение","ok":true,"i":null,"es":"sigue un tramo de doble sentido"},{"t":"лявата част на пътното платно е за автомобилите от насрещното движение","ok":true,"i":null,"es":"la parte izquierda es para el tráfico contrario"},{"t":"движещите се насреща автомобили са с предимство","ok":false,"i":null,"es":"los vehículos de frente tienen prioridad"},{"t":"навлизаме в участък от пътя, в който е забранено разминаването","ok":false,"i":null,"es":"entramos en tramo donde está prohibido el cruce"}],"f":7,"es":"En esta situación: (2 correctas)","explain":"SIGUE UN TRAMO DE DOBLE SENTIDO Y LA PARTE IZQUIERDA ES PARA EL TRÁFICO CONTRARIO. Dos correctas.\n\nQUÉ VES. Una calzada por la que vas detrás de un coche rojo. A la derecha, una señal TRIANGULAR de peligro con dos flechas, una hacia arriba y otra hacia abajo: TRÁFICO EN DOBLE SENTIDO.\n\nLA SEÑAL AVISA DE QUE SE ACABA EL SENTIDO ÚNICO. A partir de aquí vendrán vehículos de frente, y la parte izquierda de la calzada será la suya.\n\n«LOS DE FRENTE TIENEN PRIORIDAD» es el cebo: la señal es de PELIGRO (triángulo), no de prioridad. No da preferencia a nadie.\n\n«PROHIBIDO CRUZARSE» es lo contrario: en un tramo de doble sentido precisamente te vas a cruzar con otros vehículos.\n\nCLAVE: triángulo con flechas opuestas = viene tráfico de frente; ocupa solo tu mitad. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6075,"bg":"На двулентов път с двупосочно движение водачът трябва да се движи:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"възможно най-вдясно по платното за движение, когато лентите не са очертани с пътна маркировка","ok":true,"i":null,"es":"todo lo posible a la derecha cuando los carriles no están marcados"},{"t":"в дясната лента, когато лентите са очертани с пътна маркировка","ok":true,"i":null,"es":"en el carril derecho cuando hay marcas"},{"t":"в по-удобната за него пътна лента","ok":false,"i":null,"es":"en el carril más cómodo"},{"t":"в лявата пътна лента винаги, когато е свободна","ok":false,"i":null,"es":"siempre en el carril izquierdo cuando esté libre"}],"f":7,"es":"En vía de dos carriles de doble sentido el conductor debe circular: (2 correctas)","explain":"Regla de posición básica: sin carriles marcados, circula lo más a la derecha posible; con marcas, por el carril derecho. El 'carril más cómodo' no existe legalmente y el izquierdo se reserva para adelantar."},{"id":6085,"bg":"При тази ситуация, на път извън населено място, на водачите е разрешено:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/140619.png","v":null,"a":[{"t":"да се движат в най-дясната свободна лента","ok":true,"i":null,"es":"circular en el carril disponible más a la derecha"},{"t":"да се движат в средната пътна лента, когато дясната е заета","ok":true,"i":null,"es":"circular en el carril central cuando el derecho está ocupado"},{"t":"да се движат в най удобната за тях пътна лента","ok":false,"i":null,"es":"circular en el carril más cómodo"},{"t":"да се движат в средната пътна лента винаги, когато е свободна","ok":false,"i":null,"es":"circular en el central siempre que esté libre"}],"f":7,"es":"En esta situación fuera de población, está PERMITIDO: (2 correctas)","explain":"CIRCULAR POR EL CARRIL LIBRE MÁS A LA DERECHA Y POR EL CENTRAL CUANDO EL DERECHO ESTÁ OCUPADO. Dos correctas.\n\nQUÉ VES. Carretera FUERA DE POBLACIÓN con TRES carriles. La señal azul de la derecha muestra dos flechas hacia arriba y una hacia abajo: DOS carriles en tu sentido y UNO para el sentido contrario (el de la izquierda).\n\nFUERA DE POBLACIÓN, EL CARRIL LIBRE MÁS A LA DERECHA. Si el derecho está ocupado, puedes usar el central (el segundo de tu sentido).\n\n«EL CARRIL MÁS CÓMODO» solo se permite en población con carriles señalizados.\n\n«EL CENTRAL SIEMPRE QUE ESTÉ LIBRE» es el cebo: si el derecho está libre, tienes que ir por él.\n\nCLAVE: fuera de población, la derecha libre manda; el siguiente carril solo cuando el derecho está ocupado o para adelantar (compárala con la 6087). Ver Leyes → «Carril: dónde debes circular»."},{"id":6095,"bg":"При тази ситуация задължени ли сте да преминете в крайната дясна лента, ако не успеете да изпреварите двата автомобила?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/63478.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":7,"es":"En esta situación ¿está obligado a pasar al carril derecho si no puede adelantar?","explain":"NO.\n\nQUÉ VES. Calle EN POBLACIÓN con TRES carriles en tu sentido, señalizados con la señal de carriles (tres flechas hacia arriba). Vas por el carril de la IZQUIERDA (flecha). En los otros carriles hay un coche rojo y uno azul.\n\nEN POBLACIÓN, CON CARRILES SEÑALIZADOS, PUEDES ELEGIR CARRIL. Es la excepción a la regla de ir por la derecha: puedes seguir por el carril que estás usando aunque no hayas adelantado a esos coches. No estás obligado a cambiarte al de la derecha.\n\n«SÍ» es el cebo de quien aplica la regla de fuera de población (volver a la derecha después de adelantar).\n\n(Corrección: la explicación anterior lo justificaba por la seguridad de la maniobra; el motivo real es que en población, con carriles señalizados, se puede elegir carril).\n\nLAS DOS CONDICIONES DE ESTA EXCEPCIÓN: dos o más carriles en tu sentido y velocidad máxima permitida no superior a 80 km/h (aquí se cumplen; compárala con la 11686).\n\nCLAVE: población + carriles señalizados = libertad de carril. Compárala con la 6097. Ver Leyes → «Carril: dónde debes circular»."},{"id":6100,"bg":"Разположението на автомобила върху платното за движение е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64020.png","v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcto"},{"t":"неправилно","ok":false,"i":null,"es":"INCORRECTO"}],"f":7,"explain":"CORRECTA.\n\nQUÉ VES. Un pórtico con semáforos de carril sobre una calzada de tres carriles. Sobre el carril IZQUIERDO hay un ASPA ROJA; sobre los otros dos, FLECHAS VERDES hacia abajo. Tu coche circula por el carril CENTRAL (flecha).\n\nESTÁS EN UN CARRIL ABIERTO. La flecha verde sobre tu carril indica que se puede circular por él. Solo el carril izquierdo está cerrado.\n\n«INCORRECTA» sería si estuvieras bajo el aspa roja.\n\nCLAVE: aspa roja = carril cerrado; flecha verde = carril abierto (compárala con la 5930 y la 5933). Ver Leyes → «El semáforo: cada luz tiene un nombre oficial».","es":"La posición del vehículo en la calzada es:"},{"id":11821,"bg":"При тази ситуация, в крайната лява пътна лента е забранено движението на:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/65242.png","v":null,"a":[{"t":"леки автомобили с ремаркета над 750 kg","ok":true,"i":null,"es":"turismos con remolque de más de 750 kg"},{"t":"мотоциклети","ok":true,"i":null,"es":"motocicletas"},{"t":"мотопеди","ok":true,"i":null,"es":"ciclomotores"},{"t":"всички товарни автомобили","ok":false,"i":null,"es":"todos los camiones"}],"f":7,"es":"En esta situación, en el carril izquierdo está PROHIBIDO circular a: (3 correctas)","explain":"TURISMOS CON REMOLQUE DE MÁS DE 750 kg, MOTOS Y CICLOMOTORES. Tres correctas.\n\nQUÉ VES. Una autovía con TRES carriles en tu sentido (señal azul con tres flechas hacia arriba).\n\nEL CARRIL IZQUIERDO, EN VÍAS DE TRES O MÁS CARRILES POR SENTIDO, ESTÁ VEDADO A LOS MÁS LENTOS O PESADOS: entre otros, los turismos con remolque de más de 750 kg, las motos y los ciclomotores.\n\n«TODOS LOS CAMIONES» es el cebo: la prohibición no alcanza a todos los camiones sin distinción.\n\nCLAVE: compárala con la 11585 (quién no puede ir por el carril izquierdo según su velocidad). Ver Leyes → «Carril: dónde debes circular»."},{"id":11870,"bg":"При тази ситуация на кои от посочените ППС е разрешено да се движат в средната пътна лента:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64852.png","v":null,"a":[{"t":"автобуси","ok":true,"i":null,"es":"autobuses"},{"t":"леки автомобили","ok":true,"i":null,"es":"turismos"},{"t":"товарни автомобили с допустима максимална маса над 3,5 t","ok":false,"i":null,"es":"camiones con MMA superior a 3.5 t"},{"t":"товарни автомобили с допустима максимална маса до 3,5 t","ok":false,"i":null,"es":"camiones con MMA hasta 3.5 t"}],"f":7,"es":"En esta situación ¿a qué vehículos está permitido circular por el carril central? (2 correctas)"},{"id":5795,"bg":"Разрешено ли е след този пътен знак движение със скорост по-висока от означената?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53771.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":7,"es":"¿Está permitido circular a velocidad superior a la indicada después de esta señal?","explain":"NO.\n\nQUÉ VES. Carretera fuera de población con la señal de VELOCIDAD MÁXIMA 50 (círculo de borde rojo). Delante va un coche rojo.\n\nDESPUÉS DE ESTA SEÑAL NO PUEDES SUPERAR 50 km/h, aunque fuera de población el límite general sea más alto. La señal manda sobre el límite general hasta que otra señal la cancele (fin de limitación) o la cambie.\n\n«SÍ» es el cebo de quien recuerda que fuera de población se puede ir a 90.\n\nCLAVE: la señal de máxima prevalece sobre el límite general. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5796,"bg":"Разрешено ли е след този пътен знак движение със скорост по-висока от означената?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53889.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да, във всички случаи","ok":false,"i":null,"es":"sí, en todos los casos"},{"t":"да, но само когато има необходимите условия за безопасност","ok":false,"i":null,"es":"sí, pero solo con condiciones de seguridad"},{"t":"да, но само когато пътят е сух","ok":false,"i":null,"es":"sí, pero solo con carretera seca"}],"f":7,"es":"¿Está permitido circular a velocidad superior a la indicada después de esta señal?","explain":"NO.\n\nQUÉ VES. La misma escena que la 5795: señal de VELOCIDAD MÁXIMA 50 (círculo de borde rojo) en una carretera fuera de población.\n\nEL MÁXIMO NO TIENE EXCEPCIONES POR BUEN TIEMPO. Ni la carretera seca, ni la buena visibilidad, ni que haya «condiciones de seguridad» te permiten superar la cifra. Esas condiciones sirven para ir MÁS DESPACIO del máximo, nunca para pasarlo.\n\n«SÍ, EN TODOS LOS CASOS», «SÍ, CON CONDICIONES DE SEGURIDAD» y «SÍ, CON CARRETERA SECA» son tres cebos con la misma idea falsa: que el límite se puede estirar.\n\nCLAVE: las condiciones de seguridad pueden obligarte a ir por debajo del máximo, nunca te permiten superarlo. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5832,"bg":"След този пътен знак движението със скорост, по-висока от означената е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57621.png","v":null,"a":[{"t":"забранено за всички ППС","ok":true,"i":null,"es":"prohibido para todos los vehículos"},{"t":"разрешено за транзитно преминаващите ППС","ok":false,"i":null,"es":"permitido para los que hacen tránsito"},{"t":"разрешено за МПС от категория “В”","ok":false,"i":null,"es":"permitido para categoría B"},{"t":"забранено само за водачите на двуколесни ППС","ok":false,"i":null,"es":"prohibido solo para vehículos de dos ruedas"}],"f":7,"es":"Después de esta señal, circular a velocidad superior a la indicada está:","explain":"PROHIBIDO PARA TODOS LOS VEHÍCULOS. Una sola correcta.\n\nLA SEÑAL. Rectángulo blanco con la palabra «ЗОНА» (ZONA) y, debajo, la señal de velocidad máxima (círculo de borde rojo).\n\nLA LIMITACIÓN DE ZONA VALE PARA TODOS. Dentro de la zona, ningún vehículo puede superar la velocidad indicada, sea de la categoría que sea y esté de paso o no.\n\n«PERMITIDO PARA LOS QUE ESTÁN DE PASO», «PERMITIDO PARA LA CATEGORÍA B» y «PROHIBIDO SOLO PARA LOS DE DOS RUEDAS» son cebos que inventan excepciones que la señal no tiene.\n\nCLAVE: si la señal no lleva una placa que diga a quién se aplica, se aplica a todos. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5833,"bg":"При тази ситуация забраната за движение със скорост, по-висока от означената се отнася:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57654.png","v":null,"a":[{"t":"за всички улици в зоната","ok":true,"i":null,"es":"todas las calles de la zona"},{"t":"само за улицата, в чието начало е поставен","ok":false,"i":null,"es":"solo la calle donde está la señal"},{"t":"за водачите на всички ППС","ok":true,"i":null,"es":"todos los conductores"},{"t":"само за водачите на леки автомобили","ok":false,"i":null,"es":"solo los conductores de turismos"}],"f":7,"es":"En esta situación la prohibición de circular a velocidad superior a la indicada se refiere a: (2 correctas)","explain":"A TODAS LAS CALLES DE LA ZONA Y A LOS CONDUCTORES DE TODOS LOS VEHÍCULOS. Dos correctas.\n\nQUÉ VES. Calle urbana con peatones en las aceras. A la derecha, la señal «ЗОНА» con el límite de 40 km/h. Delante va un coche rojo.\n\nUNA SEÑAL DE ZONA NO SE ACABA EN EL SIGUIENTE CRUCE. A diferencia de una señal normal, vale para todas las calles del área hasta la señal de fin de zona. Y vale para todos los vehículos.\n\n«SOLO PARA LA CALLE DONDE ESTÁ LA SEÑAL» es el cebo de quien aplica la lógica de una señal normal.\n\n«SOLO PARA LOS TURISMOS» inventa una excepción.\n\nCLAVE: «ЗОНА» = toda el área y todos los vehículos, hasta el fin de zona. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":12029,"bg":"При тази ситуация трябва да управлявам с готовност за спиране заради:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":15,"a":[{"t":"трактора","ok":true,"i":null,"es":"el tractor"},{"t":"ограничението на скоростта","ok":false,"i":null,"es":"la señal de velocidad"},{"t":"мотоциклета","ok":false,"i":null,"es":"la moto"}],"f":7,"es":"En esta situación debo circular listo para frenar por:"},{"id":6230,"bg":"При тази ситуация с предимство е водачът:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71987.png","v":null,"a":[{"t":"на червения автомобил","ok":true,"i":null,"es":"para el coche rojo"},{"t":"на синия автомобил","ok":false,"i":null,"es":"para el coche azul"}],"f":7,"es":"En esta situación tiene prioridad:","explain":"EL CONDUCTOR DEL COCHE ROJO. Una sola correcta.\n\nQUÉ VES. Carretera de dos carriles en el mismo sentido. La señal azul de la derecha muestra que el carril DERECHO se ACABA y se une al izquierdo. El coche AZUL, en el carril derecho, lleva el intermitente izquierdo para pasarse al carril del ROJO.\n\nCEDE EL QUE CAMBIA DE CARRIL. Al terminarse su carril, el azul tiene que meterse en el del rojo, y para eso le cede el paso al que ya circula por él.\n\n«EL AZUL» es el cebo de quien aplica la regla de la derecha. Aquí no hay dos vehículos que convergen en un tercer carril (como en la 6233): hay uno que entra en el carril del otro.\n\nCLAVE: si tu carril se acaba, cedes al que va por el carril al que entras. Ver Leyes → «Carril: dónde debes circular»."},{"id":6243,"bg":"Разрешено ли е да започнете завиването надясно от най-лявата пътна лента на платното за движение?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да, но само когато радиусът на завиване на автомобила е по-голям от радиуса на завоя","ok":true,"i":null,"es":"sí, pero solo cuando el radio de giro del vehículo es mayor que el del cruce"},{"t":"да, винаги когато пътните ленти не са обозначени с пътна маркировка","ok":false,"i":null,"es":"sí, siempre cuando no hay marcas"},{"t":"да, във всички случаи","ok":false,"i":null,"es":"sí, en todos los casos"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":7,"explain":"Sí, pero solo cuando el radio de giro del vehículo es mayor que el del cruce: vehículos largos (camiones, autobuses) que físicamente no pueden girar desde la derecha. Para un turismo normal, girar a la derecha desde el carril izquierdo es infracción.","es":"¿Está permitido iniciar un giro a la derecha desde el carril más a la izquierda?"},{"id":6279,"bg":"При тази ситуация съм задължен да пропусна синия автомобил.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/72020.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":7,"es":"En esta situación estoy obligado a dejar pasar al coche azul. Esto es:","explain":"INCORRECTO.\n\nQUÉ VES. Tienes una señal de STOP y vas RECTO (flecha). De frente viene un coche AZUL con el intermitente, que va a girar a SU izquierda (hacia la calle de tu derecha), cruzando tu trayectoria. Las señales de los otros accesos se ven de espaldas; la respuesta del banco implica que el azul también viene por una vía secundaria.\n\nENTRE LOS DOS, CEDE EL QUE GIRA A LA IZQUIERDA. Si los dos llegáis por vías secundarias, vuestras señales no os separan, y entre vosotros decide la regla del giro: el azul gira a la izquierda y cruza tu trayectoria, así que te cede a ti, que vas recto.\n\nOjo: el STOP te obliga a detenerte antes de entrar en el cruce, pero no te obliga a ceder a quien también viene de una vía secundaria.\n\n«CORRECTO» es el cebo de quien cree que el STOP obliga a ceder a todo el mundo.\n\nCLAVE: el STOP te hace parar y ceder a los de la preferente; entre secundarias, siguen valiendo las reglas de giro y de la derecha. Ver Leyes → «Giro a la izquierda»."},{"id":6283,"bg":"При тази ситуация съм с предимство за преминаване преди червения автомобил.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70415.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":7,"es":"En esta situación tengo prioridad sobre el coche rojo. Esto es:","explain":"INCORRECTO.\n\nQUÉ VES. En tu poste hay una señal de VÍA CON PRIORIDAD (rombo). Llevas el intermitente IZQUIERDO y vas a girar a la izquierda. De frente viene un coche ROJO con el intermitente, que gira a SU derecha. Los dos vais a entrar en la misma calle (la de tu izquierda).\n\nEL ROMBO NO OS SEPARA: el rojo viene de frente por la misma vía preferente que tú. Entre vosotros decide la regla del giro:\n\nCUANDO DOS VEHÍCULOS QUE VIENEN DE FRENTE VAN A LA MISMA CALLE, el que gira a la DERECHA pasa antes que el que gira a la IZQUIERDA. El que gira a la izquierda cruza la trayectoria del otro y le cede.\n\n«CORRECTO» es el cebo de quien cree que el rombo le da preferencia frente a todos, incluido el que viene de frente.\n\nCLAVE: el rombo te da preferencia sobre los de la secundaria, no sobre los que van por tu misma vía. Ver Leyes → «Giro a la izquierda»."},{"id":6340,"bg":"При тази ситуация с предимство е водачът на:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70846.png","v":null,"a":[{"t":"трамвая","ok":true,"i":null,"es":"el tranvía"},{"t":"лекия автомобил","ok":false,"i":null,"es":"el turismo"}],"f":7,"es":"En esta situación tiene prioridad:","explain":"EL TRANVÍA. Una sola correcta.\n\nQUÉ VES. Un cruce con SEMÁFORO en VERDE. El coche AZUL lleva el intermitente DERECHO y va a girar a la derecha atravesando las VÍAS del tranvía, que quedan a su derecha. Por esas vías viene un TRANVÍA de frente.\n\nEL QUE GIRA CRUZA LAS VÍAS: CEDE. ANTE UN TRANVÍA, EL COCHE CEDE. Los vehículos sin raíles dejan pasar al tranvía cuando sus trayectorias se cruzan, aunque el tranvía gire y tú sigas recto. El semáforo en verde para los dos no cambia esta regla.\n\n«EL TURISMO» es el cebo de quien piensa que el verde o el giro a la derecha le dan preferencia.\n\nCLAVE: antes de cruzar unas vías, mira si viene un tranvía. Ver Leyes → «Quién manda sobre quién»."},{"id":6350,"bg":"На кръстовище на равнозначни пътища водачът на нерелсово ППС:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"трябва да пропусне релсовите ППС, когато те завиват надясно","ok":true,"i":null,"es":"debe ceder al tranvía cuando gira a la derecha"},{"t":"не е длъжен да пропусне релсовите ППС, когато те завиват наляво","ok":false,"i":null,"es":"no está obligado a ceder al tranvía cuando gira a la izquierda"},{"t":"трябва да пропусне релсовите ППС, когато те продължават направо","ok":true,"i":null,"es":"debe ceder al tranvía cuando continúa recto"}],"f":7,"es":"En intersección de vías equivalentes, el conductor no ferroviario: (2 correctas)","explain":"En cruce de vías equivalentes el tranvía tiene prioridad sobre los vehículos no ferroviarios: debes cederle al girar a la derecha Y al seguir recto (y también al girar a la izquierda, por eso esa opción negativa es falsa)."},{"id":6360,"bg":"Завиването в обратна посока може да започне:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"от най-лявата пътна лента по посока на движението","ok":true,"i":null,"es":"desde el carril más a la izquierda en el sentido de marcha"},{"t":"от дясната част на платното за движение, когато е с недостатъчна широчина","ok":true,"i":null,"es":"desde la derecha cuando la anchura es insuficiente"},{"t":"от най-удобната за водача пътна лента","ok":false,"i":null,"es":"desde el carril más cómodo para el conductor"}],"f":7,"es":"El cambio de sentido puede iniciarse: (2 correctas)","explain":"El cambio de sentido se inicia desde el carril más a la IZQUIERDA en tu sentido; excepcionalmente desde la derecha cuando la anchura de la calzada es insuficiente para girar desde la izquierda. La comodidad no es criterio."},{"id":6361,"bg":"Завиването в обратна посока от крайната дясна лента е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"разрешено при недостатъчна широчина на платното за движение","ok":true,"i":null,"es":"permitido cuando la anchura de la vía es insuficiente"},{"t":"разрешено във всички случаи","ok":false,"i":null,"es":"permitido siempre"},{"t":"забранено","ok":false,"i":null,"es":"prohibido"}],"f":7,"es":"El cambio de sentido desde el carril derecho está:","explain":"Desde el carril derecho solo está permitido cuando la anchura de la vía es insuficiente para completar el giro desde la izquierda. No es 'siempre' ni está prohibido de forma absoluta."},{"id":6365,"bg":"При тази ситуация с предимство е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/142934.png","v":null,"a":[{"t":"водачът на товарния автомобил","ok":true,"i":null,"es":"el conductor del camión"},{"t":"водачът на лекия автомобил","ok":false,"i":null,"es":"el conductor del turismo"}],"f":7,"es":"En esta situación tiene prioridad:","explain":"EL CONDUCTOR DEL CAMIÓN. Una sola correcta.\n\nQUÉ VES. Una carretera con mediana. En una abertura de la mediana hay una señal azul que PERMITE el CAMBIO DE SENTIDO. El coche AZUL lleva el intermitente izquierdo y va a dar la vuelta por ahí. Por el otro lado viene un CAMIÓN rojo.\n\nLA SEÑAL PERMITE LA MANIOBRA, NO DA PRIORIDAD. Puedes dar la vuelta en ese punto, pero cediendo a los que circulan por la calzada a la que entras, como el camión.\n\n«EL TURISMO» es el cebo de quien confunde «está permitido» con «tengo preferencia».\n\nCLAVE: señal de cambio de sentido permitido = puedo hacerlo, cediendo el paso. Ver Leyes → «Cambio de sentido o media vuelta»."},{"id":6369,"bg":"Завиването в обратна посока е забранено:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на жп прелез","ok":true,"i":null,"es":"en paso a nivel"},{"t":"когато видимостта е намалена под 50 м","ok":true,"i":null,"es":"con visibilidad inferior a 50 m"},{"t":"в тунел","ok":true,"i":null,"es":"en túnel"},{"t":"на участък от пътя с наклон","ok":false,"i":null,"es":"en tramo de la vía con pendiente"}],"f":7,"es":"El cambio de sentido está PROHIBIDO: (3 correctas)","explain":"Prohibido cambiar de sentido en paso a nivel, en túnel y cuando la visibilidad es inferior a 50 m. Una simple pendiente no lo prohíbe por sí misma (solo si reduce la visibilidad bajo ese umbral)."},{"id":6371,"bg":"Завиването в обратна посока е забранено:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на жп прелез","ok":true,"i":null,"es":"en paso a nivel"},{"t":"на надлез","ok":true,"i":null,"es":"en paso elevado"},{"t":"на пешеходна пътека","ok":true,"i":null,"es":"en paso de peatones"},{"t":"на път с интензивно движение","ok":false,"i":null,"es":"en vía de intenso tráfico"}],"f":7,"es":"El cambio de sentido está PROHIBIDO: (3 correctas)","explain":"Prohibido cambiar de sentido en paso a nivel, en paso elevado y sobre paso de peatones. El 'tráfico intenso' exige esperar el momento, pero no prohíbe la maniobra."},{"id":6403,"bg":"След този пътен знак на водачите на товарни автомобили с допустима максимална маса до 3,5 т е разрешено да изпреварват:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67607.png","v":null,"a":[{"t":"велосипеди","ok":true,"i":null,"es":"bicicletas"},{"t":"каруци","ok":true,"i":null,"es":"carruajes"},{"t":"леки автомобили","ok":false,"i":null,"es":"turismos"},{"t":"товарни автомобили","ok":false,"i":null,"es":"camiones"}],"f":7,"es":"Después de esta señal, los conductores de camiones con MMA ≤3.5t PUEDEN adelantar a: (2 correctas)","explain":"LAS BICICLETAS Y LOS CARROS. Dos correctas.\n\nLA SEÑAL. Círculo de borde ROJO con un coche ROJO y uno NEGRO: PROHIBIDO ADELANTAR (también para los camiones de hasta 3,5 t).\n\nLA SEÑAL DE PROHIBIDO ADELANTAR (círculo de borde rojo con un coche rojo y uno negro) prohíbe adelantar a los vehículos de MOTOR, salvo a las motos sin sidecar y a los ciclomotores. Los vehículos sin motor (bicicletas, carros) tampoco están incluidos.\n\nPOR ESO SE PUEDE ADELANTAR a las bicicletas y a los carros (каруци): no son vehículos de motor.\n\n«TURISMOS» y «CAMIONES» son vehículos de motor: prohibido adelantarlos.\n\nCLAVE: compárala con la 6402 (la misma señal: allí las excepciones con motor, aquí los vehículos sin motor). Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6412,"bg":"Разрешено ли е да предприемете изпреварване на колоната от МПС при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71738.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":7,"es":"¿Está permitido adelantar toda la columna de vehículos en esta situación?","explain":"NO.\n\nQUÉ VES. Carretera de montaña con una pared de roca a la derecha. Delante hay una COLUMNA de vehículos (un coche amarillo, uno rojo, uno azul y un camión). Llevas el intermitente IZQUIERDO y detrás de ti viene otro coche azul.\n\nADELANTAR A TODA LA COLUMNA ES UNA MANIOBRA DEMASIADO LARGA. Para adelantar tienes que poder hacerlo en poco tiempo y tener sitio para volver a tu carril. Con varios vehículos seguidos y poco espacio entre ellos, estarías mucho tiempo en el carril contrario sin saber si podrás volver a tiempo, en una carretera donde no se ve lejos.\n\n«SÍ» es el cebo de la impaciencia.\n\nCLAVE: no se adelanta a una fila entera si no hay sitio seguro para volver entre ellos. Compárala con la 12051 (vídeo). Ver Leyes → «Adelantar y colocarse antes de una maniobra»."},{"id":6427,"bg":"Водачът на изпреварваното ППС е длъжен :","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да не увеличава скоростта","ok":true,"i":null,"es":"no aumentar la velocidad"},{"t":"да не пречи на изпреварването","ok":true,"i":null,"es":"no obstaculizar el adelantamiento"},{"t":"да намали скоростта","ok":false,"i":null,"es":"reducir la velocidad"},{"t":"да премине плътно вдясно","ok":false,"i":null,"es":"desplazarse totalmente a la derecha"}],"f":7,"es":"El conductor del vehículo adelantado está obligado a: (2 correctas)","explain":"El conductor adelantado tiene dos obligaciones: NO aumentar la velocidad y NO obstaculizar la maniobra. No está obligado a frenar ni a apartarse del todo a la derecha."},{"id":6428,"bg":"При изпреварване задължението за осигуряване на достатъчно странично разстояние е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на водача на изпреварващото ППС","ok":true,"i":null,"es":"del conductor del vehículo ADELANTANTE"},{"t":"на водача на изпреварваното ППС","ok":false,"i":null,"es":"del conductor del vehículo ADELANTADO"},{"t":"на двамата водачи","ok":false,"i":null,"es":"de ambos conductores"}],"f":7,"es":"La obligación de garantizar distancia lateral suficiente al adelantar es:","explain":"La distancia lateral de seguridad es responsabilidad del que ADELANTA: quien ejecuta la maniobra responde de todos sus riesgos. El adelantado solo debe no acelerar ni obstaculizar."},{"id":6437,"bg":"Разрешено ли е да предприемете изпреварване при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/124482.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":7,"es":"¿Está permitido adelantar en esta situación?","explain":"SÍ.\n\nQUÉ VES. Carretera fuera de población con línea central discontinua. Delante va un coche AZUL. A la derecha, una señal azul informativa con la palabra «ПОЛИЦИЯ / POLICE». En el retrovisor se ve un coche rojo detrás.\n\nLA SEÑAL DE POLICÍA SOLO INFORMA de que hay un puesto policial cerca. No prohíbe adelantar ni obliga a nada.\n\n«NO» es el cebo de quien se cohíbe al ver la palabra «policía».\n\nCLAVE: señal informativa (rectangular azul) = información, no prohibición. Si la línea es discontinua y hay visibilidad, puedes adelantar con las precauciones normales. Ver Leyes → «Adelantar y colocarse antes de una maniobra»."},{"id":6439,"bg":"Разрешено ли е да продължите изпреварването при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/124449.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":7,"es":"¿Está permitido continuar el adelantamiento en esta situación?","explain":"SÍ.\n\nQUÉ VES. Carretera fuera de población. Estás adelantando a un coche AZUL (intermitente izquierdo). A la derecha, una señal TRIANGULAR de OBRAS (trabajador con pala). Las máquinas están trabajando en el campo, fuera de la calzada.\n\nUN TRIÁNGULO AVISA, NO PROHÍBE. La señal de obras te pide atención, pero no prohíbe adelantar. Las máquinas no ocupan la calzada y la línea es discontinua.\n\n«NO» es el cebo de quien convierte cualquier señal de peligro en una prohibición.\n\nCLAVE: triángulo = aviso; círculo rojo = prohibición. Compárala con la 6436. Ver Leyes → «Adelantar y colocarse antes de una maniobra»."},{"id":6443,"bg":"Разрешено ли е да предприемете изпреварване при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/124548.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":7,"es":"¿Está permitido adelantar en esta situación?","explain":"NO.\n\nQUÉ VES. Un pórtico con semáforos de carril: sobre el carril IZQUIERDO hay un ASPA ROJA y sobre los otros dos, FLECHAS VERDES. Llevas el intermitente IZQUIERDO y la flecha muestra que quieres pasar al carril izquierdo para adelantar a un coche ROJO.\n\nEL CARRIL IZQUIERDO ESTÁ CERRADO. No puedes entrar en un carril con el aspa roja, tampoco para adelantar.\n\n«SÍ» es el cebo de quien solo mira al coche de delante y no al pórtico.\n\nCLAVE: aspa roja = carril cerrado para todo, incluido adelantar. Compárala con la 6432. Ver Leyes → «El semáforo: cada luz tiene un nombre oficial»."},{"id":6702,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70614.png","v":null,"a":[{"t":"да премина преди автомобила и пешеходеца","ok":false,"i":null,"es":"pasar antes que el coche y el peatón"},{"t":"да пропусна автомобила","ok":true,"i":null,"es":"ceder el paso al coche"},{"t":"да пропусна пешеходеца","ok":true,"i":null,"es":"ceder el paso al peatón"}],"f":7,"es":"En esta situación debo: (2 correctas)","explain":"CEDER EL PASO AL COCHE Y CEDER EL PASO AL PEATÓN. Dos correctas.\n\nQUÉ VES. Llevas el intermitente IZQUIERDO y vas a girar a la izquierda. El semáforo da VERDE (flechas). De frente viene un coche ROJO. En la calle a la que vas a entrar, una PEATONA está cruzando.\n\nAL COCHE, POR EL GIRO: el que gira a la izquierda cede al que viene de frente, también con el verde.\n\nAL PEATÓN, POR EL GIRO: al girar cedes a quien cruza la calle a la que entras.\n\n«PASAR ANTES QUE EL COCHE Y EL PEATÓN» es el cebo de quien solo mira el verde.\n\nCLAVE: verde + giro a la izquierda = cedes al de frente y al peatón. Ver Leyes → «Giro a la izquierda» y «Paso de peatones»."},{"id":5938,"bg":"Редът за преминаване на тези автомобили през кръстовището се определя:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/48397.png","v":null,"a":[{"t":"от сигналите на регулировчика","ok":true,"i":null,"es":"las señales del agente regulador"},{"t":"с правилото за „предимството на дясностоящия”","ok":false,"i":null,"es":"la regla de prioridad a la derecha"},{"t":"в зависимост от посоката на движение на автомобилите","ok":false,"i":null,"es":"la dirección de circulación de los vehículos"}],"f":7,"es":"El orden de paso de estos vehículos en la intersección lo determinan:","explain":"LAS SEÑALES DEL AGENTE REGULADOR. Una sola correcta.\n\nQUÉ VES. Un cruce con un AGENTE en el centro. Por la izquierda llega un coche ROJO y desde abajo un coche AMARILLO con el intermitente puesto. No hay semáforo.\n\nSI HAY AGENTE, MANDA EL AGENTE. Está por encima del semáforo, de las señales y de la regla de la derecha. El orden de paso lo deciden sus gestos.\n\n«LA REGLA DE LA DERECHA» es el cebo: solo decide cuando no hay agente, ni semáforo, ni señales.\n\n«LA DIRECCIÓN DE LOS VEHÍCULOS» no decide el orden de paso en ningún caso.\n\nCLAVE: primero busca al agente; si está, la pregunta está resuelta. Ver Leyes → «Quién manda sobre quién»."},{"id":6349,"bg":"На водача е забранено да навлиза на железопътния прелез, когато:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"от другата страна на прелеза няма достатъчно място за продължаване на движението","ok":true,"i":null,"es":"al otro lado no hay espacio suficiente para continuar"},{"t":"на прелеза трябва да се размине с друго ППС","ok":false,"i":null,"es":"en el paso debe cruzarse con otro vehículo"},{"t":"на прелеза няма съоръжения за подаване на звуков и светлинен сигнал","ok":false,"i":null,"es":"el paso no tiene señalización"}],"f":7,"es":"Al conductor le está PROHIBIDO entrar al paso a nivel cuando:","explain":"Prohibido entrar si al otro lado no hay espacio para salir: quedarías atrapado sobre las vías. Cruzarse con otro vehículo o la falta de señalización no prohíben la entrada (esta última solo obliga a parar y comprobar)."},{"id":6353,"bg":"Как ще сигнализирате през деня, за да спрете влака, ако автомобилът, който управлявате, поради повреда остане върху релсите?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"с кръгово движение на ръката, в която се държи лесно забелязващ се предмет","ok":true,"i":null,"es":"con movimiento CIRCULAR del brazo sosteniendo un objeto llamativo"},{"t":"с насочена встрани ръка","ok":false,"i":null,"es":"con el brazo extendido lateralmente"},{"t":"с вдигната ръка, в която може да се държи привличащ вниманието предмет","ok":false,"i":null,"es":"con el brazo levantado sosteniendo algo llamativo"},{"t":"със стоп-палка","ok":false,"i":null,"es":"con una pala reflectante"}],"f":7,"es":"¿Cómo señalizas de día para detener el tren si tu vehículo está averiado en el paso?","explain":"La señal ferroviaria de 'alto' de día es el movimiento CIRCULAR del brazo sosteniendo un objeto bien visible. Un brazo extendido o levantado no significa parada para el maquinista y no detendrá el tren."},{"id":6364,"bg":"В случай на принудително спиране на превозното средство върху релсите на жп прелез, водачът е длъжен:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да изведе пътниците извън превозното средство на безопасно разстояние","ok":true,"i":null,"es":"evacuar a los pasajeros a distancia segura"},{"t":"да вземе мерки за извеждането на превозното средство извън обсега на релсовия път","ok":true,"i":null,"es":"tomar medidas para sacar el vehículo de las vías"},{"t":"да вземе мерки за своевременното предупреждаване на машинистите от двете посоки на релсовия път","ok":true,"i":null,"es":"alertar a los maquinistas de ambos sentidos"},{"t":"да остане в автомобила и да уведоми органите за контрол","ok":false,"i":null,"es":"quedarse en el vehículo y avisar a las autoridades"}],"f":7,"es":"Si el vehículo para forzosamente sobre las vías del paso a nivel, el conductor está obligado a: (3 correctas)","explain":"Vehículo atascado sobre las vías: 1) evacúa a los pasajeros a distancia segura, 2) intenta sacar el vehículo, 3) avisa a los trenes de AMBOS sentidos. Quedarse dentro esperando a las autoridades es la opción mortal."},{"id":6499,"bg":"При принудително спиране в тунел водачът е задължен да изключи двигателя, когато:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"началото на тунела е обозначено с пътен знак","ok":true,"i":null,"es":"el inicio del túnel está señalizado con señal de tráfico"},{"t":"спирането не е кратковременно","ok":true,"i":null,"es":"la parada no es breve"},{"t":"тунелът е осветен","ok":false,"i":null,"es":"el túnel está iluminado"},{"t":"движението в тунела е еднопосочно","ok":false,"i":null,"es":"el tráfico es de un solo sentido"}],"f":7,"es":"Al parar forzosamente en túnel el conductor está obligado a apagar el motor cuando: (2 correctas)","explain":"En parada forzosa en túnel debes apagar el motor cuando el túnel está señalizado con señal de tráfico y cuando la parada no es breve (acumulación de gases). La iluminación o el sentido único no cambian la obligación."},{"id":6502,"bg":"Задължен ли е водачът да изключи двигателя при принудително спиране в тунел, когато началото на тунела е обозначено с пътен знак?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да, когато това спиране не е кратковременно","ok":true,"i":null,"es":"sí, cuando la parada no es breve"},{"t":"да, независимо от продължителността на спирането","ok":false,"i":null,"es":"sí, independientemente de la duración"}],"f":7,"explain":"La clave es la duración: debes apagar el motor cuando la parada NO es breve (los gases se acumulan en el espacio cerrado). Si la detención es momentánea, no existe la obligación: por eso 'independientemente de la duración' es falsa.","es":"¿Está obligado a apagar el motor al parar forzosamente en túnel señalizado?"},{"id":6519,"bg":"При тази ситуация съм с предимство.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/63188.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":7,"es":"En esta situación tengo prioridad. Esto es:","explain":"INCORRECTO.\n\nQUÉ VES. Vas RECTO (flecha). En tu poste hay un CEDA EL PASO con PANEL: el trazo GRUESO baja desde ARRIBA y gira a la DERECHA; los trazos finos son el de la izquierda y el de abajo (el tuyo). Por la DERECHA, sobre la rama gruesa, hay una furgoneta AZUL con el intermitente puesto.\n\nTÚ VIENES POR LA SECUNDARIA Y LA FURGONETA POR LA PREFERENTE. Le cedes el paso.\n\n«CORRECTO» es el cebo de quien ve que vas recto y cree que eso le da prioridad.\n\nCLAVE: con ceda el paso, cedes a todos los que van por la rama gruesa. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). El tranvía, en general, pasa antes que los coches. Ver Leyes → «Cuando la prioritaria cambia de dirección»."},{"id":6532,"bg":"При тази ситуация трябва да пропусна:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57775.png","v":null,"a":[{"t":"мотоциклетиста","ok":true,"i":null,"es":"el motorista"},{"t":"товарния автомобил","ok":true,"i":null,"es":"el camión"},{"t":"лекия автомобил","ok":false,"i":null,"es":"el turismo"}],"f":7,"es":"En esta situación debo ceder el paso a: (2 correctas)","explain":"AL MOTORISTA Y AL CAMIÓN. Dos correctas.\n\nQUÉ VES. En tu poste hay una señal de STOP. Vas RECTO. Por la IZQUIERDA, por la vía principal, viene una MOTO. Por la DERECHA, también por la principal, viene un CAMIÓN. De frente, por la otra vía secundaria, viene un turismo ROJO con el intermitente, que va a girar.\n\nCON STOP CEDES A TODOS LOS DE LA PRINCIPAL: la moto y el camión, vengan por donde vengan.\n\nEL TURISMO NO: viene por la secundaria, como tú, y va a girar cruzando tu trayectoria; entre vosotros no decide la señal.\n\n«EL TURISMO» es el cebo de quien piensa que el STOP obliga a ceder a todo el mundo.\n\nCLAVE: STOP = parar y ceder a los de la principal; entre secundarias, siguen las reglas normales. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). El tranvía, en general, pasa antes que los coches. Ver Leyes → «Vía con prioridad»."},{"id":6533,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/61451.png","v":null,"a":[{"t":"да пропусна трамвая","ok":true,"i":null,"es":"dejar pasar al tranvía"},{"t":"да премина преди лекия автомобил","ok":true,"i":null,"es":"pasar antes que el turismo"},{"t":"да пропусна лекия автомобил","ok":false,"i":null,"es":"dejar pasar al turismo"},{"t":"да премина преди трамвая","ok":false,"i":null,"es":"pasar antes que el tranvía"}],"f":7,"es":"En esta situación debo: (2 correctas)","explain":"CEDER AL TRANVÍA Y PASAR ANTES QUE EL TURISMO. Dos correctas.\n\nQUÉ VES. Un cruce SIN SEÑALES. Vas RECTO. Por la DERECHA viene un TRANVÍA. Por la IZQUIERDA, un turismo ROJO.\n\nAL TRANVÍA LE CEDES: en un cruce sin señales el tranvía pasa antes que los vehículos sin raíles (y además viene por tu derecha).\n\nAL TURISMO LE PASAS TÚ: llega por tu izquierda, así que te cede.\n\n«CEDER AL TURISMO» y «PASAR ANTES QUE EL TRANVÍA» son las respuestas al revés.\n\nCLAVE: tranvía primero; entre coches, la derecha. Compárala con la 6535. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). El tranvía, en general, pasa antes que los coches."},{"id":6535,"bg":"При тази ситуация трябва да пропусна:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/61874.png","v":null,"a":[{"t":"само трамвая","ok":true,"i":null,"es":"solo al tranvía"},{"t":"само лекия автомобил","ok":false,"i":null,"es":"solo al turismo"},{"t":"и двете превозни средства","ok":false,"i":null,"es":"a los dos"}],"f":7,"es":"En esta situación debo ceder el paso:","explain":"SOLO AL TRANVÍA. Una sola correcta.\n\nQUÉ VES. La misma escena que la 6533: un cruce SIN SEÑALES, vas RECTO, por la DERECHA viene un TRANVÍA y por la IZQUIERDA un turismo ROJO.\n\nAL TRANVÍA LE CEDES; AL TURISMO, NO: llega por tu izquierda, así que te cede él.\n\n«SOLO AL TURISMO» y «A LOS DOS» son los cebos: el turismo está a tu izquierda.\n\nCLAVE: tranvía primero; entre coches, la derecha. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). El tranvía, en general, pasa antes que los coches."},{"id":6537,"bg":"При тази ситуация водачът на зеления автомобил трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68558.png","v":null,"a":[{"t":"да пропусне синия автомобил","ok":true,"i":null,"es":"dejar pasar al coche azul"},{"t":"да премине преди червения автомобил","ok":true,"i":null,"es":"pasar antes que el rojo"},{"t":"да пропусне червения автомобил","ok":false,"i":null,"es":"dejar pasar al coche rojo"},{"t":"да премине преди синия автомобил","ok":false,"i":null,"es":"pasar antes que el azul"}],"f":7,"es":"En esta situación el conductor del coche verde debe: (2 correctas)","explain":"CEDER AL AZUL Y PASAR ANTES QUE EL ROJO. Dos correctas.\n\nQUÉ VES. Un cruce SIN SEÑALES. El coche VERDE (en primer plano) lleva el intermitente IZQUIERDO. Por su IZQUIERDA llega un coche ROJO; por su DERECHA, una furgoneta AZUL.\n\nSIN SEÑALES MANDA LA DERECHA. El azul le llega al verde por la derecha: el verde le cede. El rojo le llega por la izquierda: el verde pasa antes.\n\n«CEDER AL ROJO» y «PASAR ANTES QUE EL AZUL» son las respuestas al revés.\n\nCLAVE: el giro a la izquierda solo obliga a ceder a lo que viene de FRENTE; con los laterales decide la derecha. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). El tranvía, en general, pasa antes que los coches. Ver Leyes → «Regla de la derecha»."},{"id":6538,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/58268.png","v":null,"a":[{"t":"да премина преди червения автомобил","ok":true,"i":null,"es":"pasar antes que el coche rojo"},{"t":"да пропусна синия автомобил","ok":true,"i":null,"es":"dejar pasar al azul"},{"t":"да пропусна червения автомобил","ok":false,"i":null,"es":"dejar pasar al rojo"},{"t":"да премина преди синия автомобил","ok":false,"i":null,"es":"pasar antes que el coche azul"}],"f":7,"explain":"PASAR ANTES QUE EL ROJO Y CEDER AL AZUL. Dos correctas.\n\nQUÉ VES. En tu poste hay una señal de STOP. Vas RECTO. Por la DERECHA, por la vía principal, llega un CAMIÓN azul con el intermitente puesto. De frente, por la otra vía secundaria, viene un coche ROJO con el intermitente, que va a girar a SU izquierda cruzando tu trayectoria.\n\nAL CAMIÓN LE CEDES: va por la principal y tú tienes STOP.\n\nAL ROJO LE PASAS TÚ: viene por la secundaria, como tú, así que la señal no os separa; entre vosotros, el que gira a la izquierda (el rojo) cede al que va recto.\n\n«CEDER AL ROJO» y «PASAR ANTES QUE EL AZUL» son las respuestas al revés.\n\nCLAVE: el STOP te obliga ante la principal, no ante el otro de la secundaria. Compárala con la 6532. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). Ver Leyes → «Vía con prioridad».","es":"En esta situación debo: (2 correctas)"},{"id":6542,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/65568.png","v":null,"a":[{"t":"да пропусна синия автомобил","ok":true,"i":null,"es":"dejar pasar al azul"},{"t":"да пропусна червения автомобил","ok":true,"i":null,"es":"dejar pasar al rojo"},{"t":"да премина преди синия автомобил","ok":false,"i":null,"es":"pasar antes que el coche azul"},{"t":"да премина преди червения автомобил","ok":false,"i":null,"es":"pasar antes que el coche rojo"}],"f":7,"es":"En esta situación debo: (2 correctas)","explain":"CEDER AL AZUL Y CEDER AL ROJO. Dos correctas.\n\nQUÉ VES. La misma escena que la 6541: CEDA EL PASO con PANEL cuyo trazo GRUESO baja desde ARRIBA y gira a la IZQUIERDA. De frente, por la rama gruesa, el ROJO; por la DERECHA, por una rama fina, el AZUL. Tú vas recto por la otra rama fina.\n\nAL ROJO, POR LA SEÑAL. AL AZUL, POR LA DERECHA.\n\n«PASAR ANTES QUE EL AZUL» y «PASAR ANTES QUE EL ROJO» son las respuestas al revés.\n\nCLAVE: es la misma regla que la 6541, preguntada en formato de dos casillas. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). Ver Leyes → «Cuando la prioritaria cambia de dirección»."},{"id":6556,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/66950.png","v":null,"a":[{"t":"пропускам червения автомобил","ok":true,"i":null,"es":"cedo el paso al coche rojo"},{"t":"преминавам преди червения автомобил","ok":false,"i":null,"es":"paso antes que el coche rojo"}],"f":7,"es":"En esta situación:","explain":"CEDO EL PASO AL ROJO. Una sola correcta.\n\nQUÉ VES. Un cruce SIN SEÑALES. Vas RECTO. Por la DERECHA llega una furgoneta ROJA con el intermitente puesto.\n\nSIN SEÑALES MANDA LA DERECHA. El rojo te llega por la derecha: pasa él primero, gire hacia donde gire.\n\n«PASO ANTES QUE EL ROJO» es el cebo de quien cree que ir recto da prioridad frente al que gira.\n\nCLAVE: «el que gira cede» solo vale frente a lo que viene de frente; con los laterales, la derecha. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). Ver Leyes → «Regla de la derecha»."},{"id":6564,"bg":"При тази ситуация задължени ли сте да пропуснете синия автомобил?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67198.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":7,"es":"¿Está obligado a ceder el paso al coche azul?","explain":"SÍ.\n\nQUÉ VES. Un cruce SIN SEÑALES. Vas RECTO. Por la DERECHA llega una furgoneta AZUL con el intermitente izquierdo, que va a girar a la izquierda.\n\nSIN SEÑALES MANDA LA DERECHA. El azul te llega por la derecha: le cedes, aunque él gire y tú vayas recto.\n\n«NO» es el cebo de quien aplica «el que gira cede» a un vehículo que llega por un lateral.\n\nCLAVE: compárala con la 6556. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). Ver Leyes → «Regla de la derecha»."},{"id":6565,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68353.png","v":null,"a":[{"t":"да пропусна червения автомобил","ok":true,"i":null,"es":"dejar pasar al rojo"},{"t":"да пропусна синия автомобил","ok":true,"i":null,"es":"dejar pasar al azul"},{"t":"да премина преди синия автомобил","ok":false,"i":null,"es":"pasar antes que el coche azul"},{"t":"да премина преди червения автомобил","ok":false,"i":null,"es":"pasar antes que el coche rojo"}],"f":7,"es":"En esta situación debo: (2 correctas)","explain":"CEDER AL ROJO Y CEDER AL AZUL. Dos correctas.\n\nQUÉ VES. Un cruce SIN SEÑALES. Llevas el intermitente IZQUIERDO: vas a girar a la izquierda. De frente viene un coche AZUL. Por la DERECHA llega un coche ROJO.\n\nAL ROJO, POR LA DERECHA: te llega por la derecha.\n\nAL AZUL, POR EL GIRO: vas a girar a la izquierda y viene de frente.\n\n«PASAR ANTES QUE EL AZUL» y «PASAR ANTES QUE EL ROJO» son las respuestas al revés.\n\nCLAVE: girar a la izquierda sin señales = cedes a la derecha y a lo que viene de frente. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). Ver Leyes → «Giro a la izquierda»."},{"id":6566,"bg":"При тази ситуация съм с предимство защото се движа направо.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67328.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":7,"es":"En esta situación tengo prioridad porque voy recto. Esto es:","explain":"INCORRECTO.\n\nQUÉ VES. Un cruce SIN SEÑALES. Vas RECTO. Por la DERECHA llega una furgoneta AZUL con el intermitente izquierdo.\n\nIR RECTO NO DA PRIORIDAD. Frente a un vehículo que llega por un lateral decide la regla de la derecha, gire él hacia donde gire. El azul te llega por la derecha: pasa él.\n\n«CORRECTO» es el cebo: «porque voy recto» es una razón falsa.\n\nCLAVE: en los enunciados con «porque voy recto», casi siempre es неправилно. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). Ver Leyes → «Regla de la derecha»."},{"id":6568,"bg":"При тази ситуация с предимство е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67378.png","v":null,"a":[{"t":"синият автомобил, защото се намира отдясно","ok":true,"i":null,"es":"el azul porque está a la derecha"},{"t":"червеният автомобил, защото се движи направо","ok":false,"i":null,"es":"el rojo porque va recto"},{"t":"синият автомобил, защото завива надясно","ok":false,"i":null,"es":"el azul porque gira a la derecha"}],"f":7,"es":"En esta situación tiene prioridad:","explain":"EL AZUL, PORQUE ESTÁ A LA DERECHA. Una sola correcta.\n\nQUÉ VES. Un cruce SIN SEÑALES. El coche AZUL (en primer plano) lleva el intermitente DERECHO y va a girar a la derecha. Por su IZQUIERDA llega un coche ROJO que sigue recto.\n\nEL AZUL ESTÁ A LA DERECHA DEL ROJO: el rojo le cede.\n\n«EL ROJO, PORQUE VA RECTO» es una razón falsa: ir recto no da prioridad.\n\n«EL AZUL, PORQUE GIRA A LA DERECHA» acierta el coche pero no la razón: girar a la derecha tampoco da prioridad por sí mismo.\n\nCLAVE: en las preguntas con «porque», la razón tiene que ser la correcta. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). Ver Leyes → «Regla de la derecha»."},{"id":6591,"bg":"При тази ситуация трябва ли да спрете, преди да преминете през кръстовището?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/56497.png","v":null,"a":[{"t":"да, при наличие на този пътен знак съм задължен да спра","ok":true,"i":null,"es":"sí, la señal presente obliga a parar"},{"t":"не, защото червеният автомобил завива надясно","ok":false,"i":null,"es":"no, porque el rojo gira a la derecha"}],"f":7,"es":"En esta situación ¿debe parar antes de cruzar la intersección?","explain":"SÍ, LA SEÑAL PRESENTE OBLIGA A PARAR. Una sola correcta.\n\nQUÉ VES. Vas RECTO. En tu poste hay una señal de STOP. Por la izquierda, un coche ROJO está dando la vuelta en el cruce.\n\nSTOP = PARADA SIEMPRE, haga lo que haga el otro vehículo.\n\n«NO, PORQUE EL ROJO GIRA A LA DERECHA» es el cebo: lo que hagan los demás no anula la obligación de detenerte ante el STOP (y además el rojo no gira a la derecha, está dando la vuelta).\n\nCLAVE: STOP = parar del todo, siempre. Compárala con la 6588.  Ver Leyes → «Vía con prioridad»."},{"id":6593,"bg":"При тази ситуация автомобилът, който се движи направо, е с предимство пред автомобила, който завива надясно.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/62980.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":7,"es":"En esta situación el vehículo que va recto tiene prioridad sobre el que gira a la derecha. Esto es:","explain":"INCORRECTO.\n\nQUÉ VES. Señal de VÍA CON PRIORIDAD con PANEL: el trazo GRUESO une el acceso de ABAJO con el de la IZQUIERDA. Por abajo, un coche AMARILLO con el intermitente DERECHO va a girar a la derecha. Por la izquierda, sobre la rama gruesa, una furgoneta ROJA sigue recto.\n\nLOS DOS ESTÁN EN LA VÍA CON PRIORIDAD, así que entre ellos decide la regla de la derecha. El amarillo está a la derecha del rojo: el amarillo pasa primero, aunque gire.\n\n«CORRECTO» es el cebo de quien cree que el que va recto siempre tiene preferencia sobre el que gira.\n\nCLAVE: ir recto no da prioridad; entre los de la preferente, la derecha. (Corrección: la traducción anterior del enunciado decía «el que gira a la izquierda»; el original búlgaro dice «el que gira a la DERECHA».) MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? 4) si nada separa a los dos, decide la derecha. Ver Leyes → «Cuando la prioritaria cambia de dirección»."},{"id":6599,"bg":"При тази ситуация съм с предимство, защото се движа направо.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/56891.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":7,"es":"En esta situación tengo prioridad porque voy recto. Esto es:","explain":"INCORRECTO.\n\nQUÉ VES. Vas RECTO. En tu poste hay un CEDA EL PASO. Por la IZQUIERDA, por la vía principal, llega un coche AZUL que también sigue recto.\n\nTÚ LLEVAS CEDA EL PASO: el azul va por la principal y le cedes, aunque venga por tu izquierda y aunque vayas recto.\n\n«CORRECTO» es el cebo: «porque voy recto» nunca es una razón válida.\n\nCLAVE: con ceda el paso, cedes a todos los de la principal, vengan por donde vengan.  Ver Leyes → «Vía con prioridad»."},{"id":6602,"bg":"При приближаване към кръстовище водачът трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"своевременно да заеме пътна лента, която е предназначена за неговата посока на движение","ok":true,"i":null,"es":"ocupar a tiempo el carril correspondiente a su dirección"},{"t":"да управлява с готовност за спиране","ok":true,"i":null,"es":"circular listo para frenar"},{"t":"да подаде звуков или светлинен сигнал, когато е с предимство","ok":false,"i":null,"es":"dar señal acústica/luminosa cuando tiene prioridad"},{"t":"да има готовност да пропусне преминаващи през платното за движение пешеходци","ok":true,"i":null,"es":"estar listo para ceder a peatones que cruzan"}],"f":7,"es":"Al aproximarse a una intersección el conductor debe: (3 correctas)","explain":"Al aproximarte a un cruce: ocupa a tiempo el carril de tu dirección, circula preparado para frenar y listo para ceder a los peatones. Pitar o dar luces para 'reclamar' tu prioridad está prohibido."},{"id":6604,"bg":"Разрешено ли е да навлезете в кръстовище, ако преди да преминете ще се наложи да спрете в кръстовището?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"не, ако по този начин ще възпрепятствам преминаването през него","ok":true,"i":null,"es":"no, si obstaculizarías el paso"},{"t":"не, ако изходът на кръстовището е зает и ще остана с превозното средство в кръстовището","ok":true,"i":null,"es":"no, si la salida está ocupada y quedarías dentro"},{"t":"да, когато се намирам на пътя с предимство","ok":false,"i":null,"es":"sí, si estás en vía preferente"},{"t":"да, винаги","ok":false,"i":null,"es":"sí, siempre"}],"f":7,"explain":"No entres si obstaculizarías el paso ni si la salida del cruce está ocupada y quedarías dentro. Da igual que tu vía sea preferente o el semáforo esté verde: bloquear la intersección es infracción por sí misma.","es":"¿Está permitido entrar en la intersección si tendrías que parar dentro? (2 correctas son PROHIBICIONES) (2 correctas)"},{"id":6607,"bg":"Редът за преминаване на тези автомобили през кръстовището се определя:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/48363.png","v":null,"a":[{"t":"с правилото за „предимството на дясностоящия”","ok":true,"i":null,"es":"la regla de prioridad a la derecha"},{"t":"в зависимост от посоката на движение на автомобилите","ok":false,"i":null,"es":"la dirección de circulación de los vehículos"}],"f":7,"es":"El orden de paso de estos vehículos lo determinan:","explain":"CON LA REGLA DE LA DERECHA. Una sola correcta.\n\nQUÉ VES. El coche AMARILLO (en primer plano) tiene un CEDA EL PASO con PANEL: el trazo GRUESO baja desde ARRIBA y gira a la IZQUIERDA. El amarillo llega por la rama fina de abajo. Por la DERECHA, también por una rama fina, llega un coche ROJO.\n\nLOS DOS ESTÁN EN LA SECUNDARIA. La señal no los separa entre sí, así que entre ellos decide la regla de la derecha: el rojo, que está a la derecha del amarillo, pasa primero.\n\n«LA DIRECCIÓN DE LOS VEHÍCULOS» no decide el orden de paso.\n\nCLAVE: el ceda el paso solo ordena frente a la rama gruesa; entre ramas finas, la derecha. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? 4) si nada separa a los dos, decide la derecha. Ver Leyes → «Cuando la prioritaria cambia de dirección»."},{"id":6673,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53658.png","v":null,"a":[{"t":"спирам, за да изчакам разрешаващ сигнал от регулировчика","ok":true,"i":null,"es":"paro para esperar señal de paso del agente"},{"t":"спирам, за да пропусна червения автомобил и преминавам след него","ok":false,"i":null,"es":"paro para dejar al rojo y paso después"},{"t":"преминавам преди червения автомобил, защото съм отдясно и се движа по път с предимство","ok":false,"i":null,"es":"paso antes que el rojo porque estoy a la derecha y en vía preferente"}],"f":7,"es":"En esta situación:","explain":"PARO PARA ESPERAR LA SEÑAL QUE ME PERMITA PASAR DEL AGENTE. Una sola correcta.\n\nQUÉ VES. En el cruce hay un AGENTE de pie, de CARA a ti (te muestra el pecho), con los brazos bajados. A la derecha hay un rombo y una señal azul de dirección obligatoria (recto o derecha). Llevas el intermitente DERECHO. Por la izquierda hay un coche ROJO.\n\nAGENTE DE CARA = PROHIBIDO PASAR. Mientras te muestre el pecho, esperas. El agente manda sobre las señales, así que el rombo no te sirve.\n\n«PARO PARA DEJAR PASAR AL ROJO Y PASO DESPUÉS» es el cebo: no pasas cuando se va el rojo, sino cuando el agente te lo permita.\n\n«PASO ANTES QUE EL ROJO PORQUE ESTOY A LA DERECHA Y EN VÍA PREFERENTE» ignora al agente.\n\nCLAVE: con agente, lo que cuenta es su posición respecto a ti. Ver Leyes → «Quién manda sobre quién»."},{"id":5365,"bg":"При навлизане на автомагистрала водачът е длъжен да пропусне превозните средства, които се движат по нея:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"във всички случаи","ok":true,"i":null,"es":"en todos los casos"},{"t":"само когато е поставен пътен знак за осигуряване на предимство","ok":false,"i":null,"es":"solo cuando hay señal de tráfico que garantiza la prioridad"},{"t":"само, когато те се движат с висока скорост","ok":false,"i":null,"es":"solo cuando circulan a alta velocidad"}],"f":7,"es":"Al incorporarse a la autopista el conductor debe ceder el paso a los vehículos que circulan por ella:","explain":"En todos los casos: quien se incorpora a la autopista cede a los que ya circulan, con o sin señal. El carril de aceleración sirve para igualar la velocidad y entrar en un hueco, no otorga prioridad."},{"id":5377,"bg":"Кой от автомобилите нарушава правилата за движение по автомагистрала?","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/41540.png","v":null,"a":[{"t":"и двата автомобила","ok":true,"i":null,"es":"los dos automóviles"},{"t":"само лекият автомобил","ok":false,"i":null,"es":"solo el turismo"},{"t":"само товарният автомобил","ok":false,"i":null,"es":"solo el camión"}],"f":7,"es":"¿Cuál de los automóviles infringe las normas de circulación en autopista?","explain":"AMBOS cometen infraccion. Tipica pregunta trampa - busca si los dos hacen algo incorrecto antes de elegir solo uno."},{"id":5423,"bg":"Теглене с гъвкава връзка по автомобилен път е:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"разрешено само за изтегляне до най-близкото място за напускане на пътя","ok":true,"i":null,"es":"permitido solo para salir por la salida más cercana"},{"t":"разрешено без ограничения","ok":false,"i":null,"es":"permitido sin restricciones"},{"t":"забранено във всички случаи","ok":false,"i":null,"es":"prohibido en todos los casos"},{"t":"забранено само в тъмната част от денонощието","ok":false,"i":null,"es":"prohibido solo de noche"}],"f":7,"es":"El remolque con cable flexible por carretera de automóviles está:","explain":"El cable flexible en vía rápida solo sirve para salir por la salida más próxima: el remolcado con cable no tiene control suficiente a esas velocidades. No está prohibido del todo ni permitido sin límite."},{"id":5426,"bg":"При тази ситуация, ако лекият автомобил се движи бавно, разрешено ли е да използвате за движение лентата за принудително спиране?","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/41756.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":7,"es":"En esta situación, si el turismo circula lento, ¿está permitido usar el carril de parada de emergencia para circular?","explain":"NO.\n\nQUÉ VES. Una AUTOPISTA (señal verde). Delante, un camión detenido con las luces de emergencia y un TRIÁNGULO de preseñalización en la calzada. Un coche ROJO va despacio delante de ti. Llevas el intermitente DERECHO, como si quisieras meterte en el carril de parada de emergencia para pasar.\n\nEL CARRIL DE PARADA DE EMERGENCIA NO ES UN CARRIL PARA CIRCULAR. Solo se usa para detenerse en caso de avería o emergencia, nunca para adelantar a quien va despacio.\n\n«SÍ» es el cebo de la impaciencia.\n\nCLAVE: lentitud del de delante ≠ emergencia. Esperas o adelantas por la izquierda cuando se pueda. Ver Leyes → «Autopista: incorporación y vehículos lentos»."},{"id":8263,"bg":"Автомагистралата е път:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"който не пресича пътища, железопътни и трамвайни линии и пешеходни пътеки на едно ниво","ok":true,"i":null,"es":"que no cruza a nivel otras vías, líneas ferroviarias o de tranvía ni pasos de peatones"},{"t":"на който началото е обозначено със съответния пътен знак","ok":true,"i":null,"es":"cuyo inicio está señalizado con la señal de tráfico correspondiente"},{"t":"на който краят е обозначен със съответния пътен знак","ok":true,"i":null,"es":"cuyo final está señalizado con la señal de tráfico correspondiente"},{"t":"по който движението се извършва без ограничение на скоростта","ok":false,"i":null,"es":"por la que se circula sin límite de velocidad"}],"f":7,"es":"La autopista es una carretera: (3 correctas)","explain":"La autopista se caracteriza por: no cruzar A NIVEL otras vías, ferrocarriles ni pasos de peatones (todo es a distinto nivel), y por tener inicio y final señalizados con su señal. 'Sin límite de velocidad' es falso: 140 km/h para turismos."},{"id":11443,"bg":"При движение по автомагистрала на водача е забранено:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да завива в обратна посока","ok":true,"i":null,"es":"girar en sentido contrario"},{"t":"да се движи в платното за насрещно движение","ok":true,"i":null,"es":"circular en el carril contrario"},{"t":"да тегли повредено МПС с твърда връзка","ok":false,"i":null,"es":"remolcar un vehículo averiado con barra rígida"}],"f":7,"es":"Al circular por autopista al conductor le está prohibido: (2 correctas)","explain":"En autopista está prohibido girar en sentido contrario y circular por el carril contrario: son las maniobras suicidas contra el flujo. Remolcar con barra rígida está permitido: la trampa de siempre."},{"id":11620,"bg":"Лентата за принудително спиране на автомагистрала е разрешено да се използва:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"при здравословни проблеми на водача или пътниците в превозното средство","ok":true,"i":null,"es":"en caso de problemas de salud del conductor o de los pasajeros del vehículo"},{"t":"при повреда на пътното превозно средство","ok":true,"i":null,"es":"en caso de avería del vehículo"},{"t":"за движение на бавнодвижещи се МПС","ok":false,"i":null,"es":"para la circulación de vehículos lentos"},{"t":"за паркиране","ok":false,"i":null,"es":"para estacionar"}],"f":7,"es":"El carril de parada de emergencia en autopista está permitido usarlo: (2 correctas)","explain":"El carril de emergencia se usa por avería o por problemas de salud de conductor o pasajeros. Ni para que circulen vehículos lentos ni para estacionar: no es un carril más ni un aparcamiento."},{"id":5545,"bg":"Този пътен знак указва:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/38358.png","v":null,"a":[{"t":"начало на автобусна спирка","ok":true,"i":null,"es":"INICIO de parada de autobús"},{"t":"край на автобусна спирка","ok":false,"i":null,"es":"FIN de parada de autobús"},{"t":"пресичане на път, по който се движат автобуси","ok":false,"i":null,"es":"cruce de ruta de autobús"}],"f":7,"es":"Esta señal indica:","explain":"INICIO DE PARADA DE AUTOBÚS. Una sola correcta.\n\nLA SEÑAL. Cuadrado AZUL con un recuadro blanco y un AUTOBÚS.\n\nSE COLOCA AL PRINCIPIO DE LA PARADA; desde ahí empieza la zona donde no puedes detenerte ni aparcar.\n\n«FIN DE PARADA» no se indica con esta señal. «CRUCE DE RUTA DE AUTOBÚS» no existe como señal.\n\nCLAVE: compárala con la 5547 y la 5562. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5550,"bg":"С този знак се обозначава:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334687.png","v":null,"a":[{"t":"автобусна спирка","ok":true,"i":null,"es":"parada de autobús"},{"t":"пътна лента за движение само на автобуси","ok":false,"i":null,"es":"carril reservado a autobuses"},{"t":"пътна лента, забранена за движение на автобуси","ok":false,"i":null,"es":"carril prohibido para autobuses"},{"t":"пресичане на път, по който се движат автобуси","ok":false,"i":null,"es":"cruce de ruta de autobús"}],"f":7,"es":"Con esta señal se indica:","explain":"PARADA DE AUTOBÚS. Una sola correcta.\n\nLA SEÑAL. Cuadrado AZUL con un recuadro blanco y un AUTOBÚS negro.\n\nMARCA EL LUGAR DE LA PARADA del autobús. Cerca de ella no se puede parar ni aparcar, y hay que prever peatones que suben o bajan.\n\n«CARRIL SOLO PARA AUTOBUSES» se indica con «BUS» y una flecha de carril. «CARRIL PROHIBIDO A AUTOBUSES» sería un círculo rojo. «CRUCE DE RUTA DE AUTOBÚS» no existe como señal.\n\nCLAVE: autobús en recuadro blanco = parada. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5588,"bg":"При тази ситуация:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/39220.png","v":null,"a":[{"t":"трябва да спра, ако преча на пешеходците да преминават през платното за движение","ok":true,"i":null,"es":"debo detenerme si impido a los peatones cruzar la calzada"},{"t":"мога да премина без да спирам, защото на платното за движение има очертан остров","ok":true,"i":null,"es":"puedo pasar sin detenerme, porque en la calzada hay una isleta marcada"},{"t":"задължен съм да спра на 1 м зад трамвая","ok":false,"i":null,"es":"estoy obligado a detenerme a 1 m detrás del tranvía"},{"t":"заобикалям трамвая отляво","ok":false,"i":null,"es":"rodear el tranvía por la izquierda"}],"f":7,"es":"En esta situación: (2 correctas)","explain":"DEBO DETENERME SI IMPIDO CRUZAR A LOS PEATONES, Y PUEDO PASAR SIN DETENERME PORQUE HAY UNA ISLETA MARCADA. Dos correctas.\n\nQUÉ VES. Calle urbana con un TRANVÍA detenido en su parada (señal azul a la derecha). Entre las vías y tu carril hay una ISLETA pintada con rayas, y en la acera derecha esperan peatones.\n\nLA ISLETA SEPARA A LOS PASAJEROS DEL TRANVÍA DE TU CARRIL, así que puedes seguir sin detenerte detrás del tranvía. Pero si algún peatón tiene que cruzar tu carril, paras para no impedírselo.\n\n«ESTOY OBLIGADO A PARAR A 1 m DETRÁS DEL TRANVÍA» es la obligación cuando NO hay isleta (compárala con la 5598); aquí la hay. «RODEARLO POR LA IZQUIERDA» te mete en las vías del sentido contrario.\n\nCLAVE: con isleta, pasas con cuidado; sin isleta, paras detrás del tranvía."},{"id":5601,"bg":"При тази ситуация преминавам, без да спирам покрай спрелия на спирката трамвай, защото той е със затворени врати.","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/39534.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":7,"es":"En esta situación paso sin detenerme junto al tranvía parado en la parada, porque tiene las puertas cerradas. Esto es:","explain":"INCORRECTO.\n\nQUÉ VES. Calle urbana con un TRANVÍA detenido junto a una parada (señal azul a la derecha), donde esperan varias personas en la acera.\n\nQUE LAS PUERTAS ESTÉN CERRADAS NO GARANTIZA NADA: el tranvía puede abrirlas en cualquier momento, y los que esperan en la parada pueden cruzar tu carril para subir. Pasas despacio y preparado para detenerte.\n\n«CORRECTO» es el cebo de quien da por terminada la subida y bajada de pasajeros solo porque ve las puertas cerradas.\n\nCLAVE: compárala con la 5588 (tranvía con isleta)."},{"id":5619,"bg":"Правилата за движение в жилищна зона, обозначена с този пътен знак, са валидни:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/39733.png","v":null,"a":[{"t":"до пътен знак „Край на жилищната зона”","ok":true,"i":null,"es":"hasta la señal \"Fin de la zona residencial\""},{"t":"до следващото кръстовище","ok":false,"i":null,"es":"hasta la próxima intersección"},{"t":"до края на населеното място","ok":false,"i":null,"es":"hasta el final del poblado"},{"t":"до пътен знак „Край на забраните въведени с пътни знаци”","ok":false,"i":null,"es":"hasta la señal \"Fin de las prohibiciones impuestas por señales\""}],"f":7,"es":"Las normas de circulación en una zona residencial, señalizada con esta señal, son válidas:","explain":"HASTA LA SEÑAL «FIN DE LA ZONA RESIDENCIAL». Una sola correcta.\n\nLA SEÑAL. Cuadrado AZUL con una persona, un niño jugando con una pelota, un coche y una casa: ZONA RESIDENCIAL.\n\nES UNA SEÑAL DE ZONA: sus normas (peatones con preferencia, velocidad muy baja, niños jugando en la calzada) rigen en toda la zona, también después de los cruces, hasta la señal de fin (la misma tachada).\n\n«HASTA LA PRÓXIMA INTERSECCIÓN» es la regla de las prohibiciones normales. «HASTA EL FINAL DEL POBLADO» y «FIN DE LAS PROHIBICIONES» no la cancelan.\n\nCLAVE: señal de zona = vale hasta su señal de fin. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5624,"bg":"В жилищна зона, обозначена със съответния пътен знак, движението на пешеходци върху платното за движение е:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"разрешено","ok":true,"i":null,"es":"permitido"},{"t":"забранено във всички случаи","ok":false,"i":null,"es":"prohibido en todos los casos"},{"t":"забранено, винаги когато пречат на движението на МПС","ok":false,"i":null,"es":"prohibido, siempre que obstaculicen la circulación de los vehículos"}],"f":7,"es":"En una zona residencial señalizada con la señal correspondiente, la circulación de peatones por la calzada es:","explain":"Permitido: en zona residencial señalizada los peatones pueden usar TODA la calzada (y los niños jugar en ella). Por eso el límite es 20 km/h: el espacio es compartido y el peatón tiene prioridad."},{"id":11621,"bg":"В района на спирка, обозначена с този знак, е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123801926.png","v":null,"a":[{"t":"престоя на таксиметрови автомобили с цел очакване на пътници","ok":true,"i":null,"es":"la parada de taxis para esperar pasajeros"},{"t":"спирането за товарно-разтоварни работи","ok":true,"i":null,"es":"la detención para operaciones de carga y descarga"},{"t":"спирането за слизане на пътници","ok":false,"i":null,"es":"la detención para la bajada de pasajeros"}],"f":7,"es":"En la zona de una parada señalizada con esta señal está prohibido: (2 correctas)","explain":"LA PARADA DE TAXIS PARA ESPERAR PASAJEROS Y LA DETENCIÓN PARA CARGA Y DESCARGA. Dos correctas.\n\nLA SEÑAL. Cuadrado AZUL con un recuadro blanco y un TRANVÍA: parada de tranvía.\n\nEN LA ZONA DE LA PARADA, el sitio es para el transporte público. Un taxi no puede quedarse ahí esperando clientes, ni un vehículo pararse a cargar o descargar.\n\n«LA DETENCIÓN PARA QUE BAJEN PASAJEROS» es el cebo: dejar bajar a alguien, sin quedarse, no está entre las prohibiciones que marca el banco.\n\nCLAVE: compárala con la 5547 y la 5550. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5711,"bg":"При теглене на повредено МПС дължината на гъвкавата връзка може да бъде:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"4 м","ok":true,"i":null,"es":"4 m"},{"t":"5 м","ok":true,"i":null,"es":"5 m"},{"t":"6 м","ok":true,"i":null,"es":"6 m"},{"t":"3 м","ok":false,"i":null,"es":"3 m"}],"f":7,"es":"Al remolcar un vehículo averiado, la longitud del enganche flexible puede ser: (3 correctas)","explain":"El enganche flexible mide entre 4 y 6 m: 4, 5 y 6 valen; 3 m es demasiado corto (el remolcado no tendría distancia para frenar sin embestir). El rango existe para que la conexión sea visible y manejable."},{"id":5776,"bg":"При теглене на повреден автомобил разрешено ли е теглещият автомобил да бъде с ремарке?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":7,"es":"Al remolcar un automóvil averiado, ¿está permitido que el automóvil que remolca lleve un remolque?","explain":"No: el vehículo que remolca a un averiado no puede llevar además un remolque. Tres elementos enganchados serían ingobernables en frenada y en curva."},{"id":5783,"bg":"Разрешено ли е теглене на повреден автомобил с гъвкава връзка, когато пътят е хлъзгав?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да, без ограничение","ok":false,"i":null,"es":"sí, sin restricciones"},{"t":"да, ако теглещия автомобил е с антиблокираща система на спирачната уредба","ok":false,"i":null,"es":"sí, si el automóvil que remolca tiene sistema antibloqueo de frenos (ABS)"}],"f":7,"es":"¿Está permitido remolcar un automóvil averiado con enganche flexible cuando la vía está deslizante?","explain":"No: con la vía deslizante el remolcado con enganche FLEXIBLE está prohibido: el remolcado no puede mantener el cable tenso al frenar y embestiría al que remolca. El ABS del primero no resuelve la física del segundo."},{"id":5554,"bg":"Разрешено ли е след този знак да спрете върху платното за движение за слизане на пътник от автомобила?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42299.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":7,"es":"¿Está permitido, después de esta señal, detenerse en la calzada para que baje un pasajero del automóvil?","explain":"NO.\n\nQUÉ VES. Calle urbana. A la derecha, la señal de DOS BARRAS EN ASPA (prohibida la parada y el estacionamiento). Llevas el intermitente DERECHO y la flecha dibuja que vas a arrimarte a la acera.\n\nEL ASPA PROHÍBE TAMBIÉN LA PARADA BREVE: ni para que baje un pasajero. Con una sola barra sí se podría.\n\n«SÍ» es el cebo de quien cree que una parada de segundos no cuenta.\n\nCLAVE: compárala con la 5546 y la 5549. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5590,"bg":"Кой автомобил е паркиран правилно?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43384.png","v":null,"a":[{"t":"само червеният автомобил","ok":false,"i":null,"es":"solo el rojo"},{"t":"само синият автомобил","ok":false,"i":null,"es":"solo el azul"},{"t":"и двата автомобила","ok":true,"i":null,"es":"ambos automóviles"}],"f":7,"es":"¿Qué automóvil está estacionado correctamente?","explain":"AMBOS AUTOMÓVILES. Una sola correcta.\n\nQUÉ VES. Calle urbana. A la derecha, la señal de PROHIBIDA LA PARADA Y EL ESTACIONAMIENTO con una placa con una flecha hacia ABAJO, y un triángulo de «otros peligros» detrás. Los coches ROJO y AZUL están aparcados junto a la acera, pasada la señal.\n\nLA FLECHA HACIA ABAJO = AQUÍ TERMINA la zona prohibida. Los dos coches están después del final, así que están bien aparcados.\n\n«SOLO EL ROJO» y «SOLO EL AZUL» son los cebos de quien lee la señal como el inicio de la prohibición.\n\nCLAVE: compárala con la 6258 (la misma placa). Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5594,"bg":"Къде по пътищата извън населените места е разрешен престоят?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"извън платното за движение","ok":true,"i":null,"es":"fuera de la calzada"},{"t":"допуска се престой най-вдясно на пътното платно, когато пътният банкет е с недостатъчна широчина","ok":true,"i":null,"es":"se permite la parada lo más a la derecha de la plataforma vial cuando el arcén no es suficientemente ancho"},{"t":"само на специално определените за това места","ok":false,"i":null,"es":"solo en los lugares especialmente destinados a ello"}],"f":7,"es":"¿Dónde está permitida la parada en las vías fuera de poblado? (2 correctas)","explain":"Fuera de poblado se para FUERA de la calzada (arcén, apartadero); si el arcén no es bastante ancho, lo más a la derecha de la plataforma vial. No hace falta 'lugar especialmente destinado': eso es en vías rápidas."},{"id":5613,"bg":"Спирането за престой е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"в тунел","ok":true,"i":null,"es":"en túnel"},{"t":"в подлез","ok":true,"i":null,"es":"en un paso subterráneo"},{"t":"на участък от пътя, който е в ремонт","ok":false,"i":null,"es":"en un tramo de la vía en obras"},{"t":"на надлез","ok":true,"i":null,"es":"en paso elevado"}],"f":7,"es":"La detención (parada) está prohibida: (3 correctas)","explain":"Parada prohibida en túnel, paso subterráneo y paso elevado: espacios estrechos donde un vehículo detenido bloquea y no se ve a tiempo. El tramo en obras no la prohíbe por sí mismo."},{"id":5618,"bg":"Спирането за престой е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на платното за движение, където с пътен знак е забранено изпреварването","ok":true,"i":null,"es":"en calzada donde hay señal que prohíbe el adelantamiento"},{"t":"върху пътна лента, предназначена за движение на бавнодвижещи се ППС, обозначена с пътен знак","ok":true,"i":null,"es":"sobre carril destinado a vehículos lentos señalizado"},{"t":"на място, където ППС закрива от другите участници в движението пътен знак","ok":true,"i":null,"es":"en un lugar donde el vehículo oculta a los demás usuarios una señal de tráfico"},{"t":"на участък от пътя с интензивно движение","ok":false,"i":null,"es":"en tramo de intenso tráfico"}],"f":7,"es":"La detención (parada) está prohibida: (3 correctas)","explain":"Parada prohibida: donde una señal prohíbe adelantar (pararte obligaría a los demás a un adelantamiento prohibido), sobre el carril señalizado de vehículos lentos y donde tapas una señal a los demás. El 'tráfico intenso' no es causa legal de prohibición."},{"id":5632,"bg":"Забранено е паркирането пред пешеходни пътеки, на разстояние по-малко от:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"5 м","ok":true,"i":null,"es":"5 m"},{"t":"10 м","ok":false,"i":null,"es":"10 m"},{"t":"15 м","ok":false,"i":null,"es":"15 m"},{"t":"20 м","ok":false,"i":null,"es":"20 m"}],"f":7,"es":"Está prohibido estacionar delante de los pasos de peatones a una distancia inferior a:","explain":"5 m: misma distancia que para la parada breve. Estacionar más cerca del paso convierte tu coche en una pantalla que oculta al peatón justo donde va a cruzar."},{"id":5646,"bg":"Паркирането е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на спирките на превозните средства от редовните линии за обществен превоз на пътници","ok":true,"i":null,"es":"en las paradas de los vehículos de las líneas regulares de transporte público"},{"t":"в близост до трамвайна линия, което може да затрудни движението на трамвая","ok":true,"i":null,"es":"cerca de una línea de tranvía, si puede dificultar la circulación del tranvía"},{"t":"на улици, по които се движат трамваи","ok":false,"i":null,"es":"en calles por las que circulan tranvías"},{"t":"върху трамвайна линия","ok":true,"i":null,"es":"sobre vía de tranvía"}],"f":7,"es":"El estacionamiento está prohibido: (3 correctas)","explain":"Prohibido estacionar en paradas de transporte público, sobre la vía del tranvía y cerca de ella si dificulta su paso. Pero en calles CON tranvía sí se puede estacionar mientras no estorbes la vía: por eso esa opción general es falsa."},{"id":5665,"bg":"През нощта на осветен участък от пътя движението се извършва:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"с включени къси светлини","ok":true,"i":null,"es":"con luces CORTAS encendidas"},{"t":"с включени дълги светлини","ok":false,"i":null,"es":"con las luces largas encendidas"},{"t":"с включени само габаритни светлини","ok":false,"i":null,"es":"con solo las luces de posición"},{"t":"без включени светлини","ok":false,"i":null,"es":"sin luces encendidas"}],"f":7,"es":"De noche en un tramo iluminado artificialmente, se circula:","explain":"Con luces CORTAS: de noche, aunque el tramo esté iluminado, las cortas te hacen visible sin deslumbrar. Las largas deslumbran, y solo posición o nada te vuelven invisible en cuanto falle la iluminación."},{"id":5692,"bg":"Кое от изброените действия е най-опасно при навлизане в заледен пътен участък?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"навлизането с висока скорост","ok":true,"i":null,"es":"entrar a alta velocidad"},{"t":"задържане натиснат педала на съединителя","ok":false,"i":null,"es":"mantener el pedal del embrague pisado"},{"t":"изключването на скоростния механизъм","ok":false,"i":null,"es":"desacoplar la marcha (dejar en punto muerto)"}],"f":7,"es":"¿Cuál de las acciones indicadas es la más peligrosa al entrar en un tramo de vía helado?","explain":"Lo más peligroso es ENTRAR RÁPIDO en el hielo: sin adherencia, cualquier corrección a alta velocidad es imposible. Pisar el embrague o el punto muerto son menos graves: pierdes freno motor, pero no el control de golpe."},{"id":6684,"bg":"При движение при намалена видимост МПС трябва да бъде:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"с включени къси или дълги светлини","ok":true,"i":null,"es":"con las luces de cruce o de carretera encendidas"},{"t":"с включени габаритни светлини","ok":true,"i":null,"es":"con las luces de posición encendidas"},{"t":"с включена светлина за осветяване на задната табела с регистрационния номер","ok":true,"i":null,"es":"con la luz de la placa de matrícula trasera encendida"},{"t":"с включен авариен сигнал","ok":false,"i":null,"es":"con la señal de avería activada (luces de emergencia)"}],"f":7,"es":"Al circular con visibilidad reducida, el vehículo debe ir: (3 correctas)","explain":"Con visibilidad reducida el vehículo circula con: luces de cruce o carretera, luces de posición y la luz de la placa trasera: todo el alumbrado de marcha. Las luces de emergencia NO son para circular: señalizan un vehículo averiado o peligro."},{"id":5715,"bg":"Неправилното положение на тялото на водача по време на управление води до по-бърза умора.","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcto"},{"t":"неправилно","ok":false,"i":null,"es":"INCORRECTO"}],"f":7,"es":"La postura incorrecta del cuerpo del conductor durante la conducción provoca una fatiga más rápida.","explain":"Correcto: la mala postura fatiga antes: tensión muscular constante, apoyo incorrecto de la espalda y peor circulación. Es la misma regla que su gemela sobre el asiento mal regulado."},{"id":5724,"bg":"При движение на превозното средство разходът на гориво:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"се увеличава при превозване на предмети върху покрива на автомобила","ok":true,"i":null,"es":"aumenta al transportar objetos sobre el techo del automóvil"},{"t":"се увеличава при понижено налягане на въздуха в автомобилните гуми","ok":true,"i":null,"es":"aumenta con la presión de los neumáticos baja"},{"t":"намалява при често използване на спирачките","ok":false,"i":null,"es":"disminuye con el uso frecuente de los frenos"},{"t":"намялява при рязко увеличаване на скоростта","ok":false,"i":null,"es":"disminuye al aumentar bruscamente la velocidad"}],"f":7,"es":"Durante la marcha del vehículo, el consumo de combustible: (2 correctas)","explain":"El consumo aumenta con carga en el techo (aerodinámica) y con presión de neumáticos baja (resistencia a la rodadura). Frenar a menudo y acelerar bruscamente también lo AUMENTAN, no lo reducen: por eso esas opciones son falsas."},{"id":5727,"bg":"При зареждане на автомобила с гориво пушенето е:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"забранено","ok":true,"i":null,"es":"prohibido"},{"t":"разрешено само извън автомобила","ok":false,"i":null,"es":"permitido solo fuera del automóvil"},{"t":"разрешено само в автомобила","ok":false,"i":null,"es":"permitido solo dentro del automóvil"}],"f":7,"es":"Al repostar combustible, fumar está:","explain":"Prohibido fumar al repostar, dentro o fuera del coche: los vapores de gasolina se inflaman con cualquier brasa. No hay versión 'segura' de fumar en la gasolinera."},{"id":5744,"bg":"Трябва ли да се управлява МПС при влошено здравословно състояние?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"не трябва да се управлява","ok":true,"i":null,"es":"no se debe conducir"},{"t":"да, но след това трябва да се отдели повече време за почивка","ok":false,"i":null,"es":"sí, pero después hay que dedicar más tiempo al descanso"},{"t":"да, но трябва да се вземе подходящо лекарство преди управлението","ok":false,"i":null,"es":"sí, pero hay que tomar un medicamento adecuado antes de conducir"}],"f":7,"es":"¿Se debe conducir un vehículo con el estado de salud deteriorado?","explain":"No se debe conducir con la salud deteriorada: los reflejos, la atención y el juicio están mermados. Ni el descanso posterior ni un medicamento lo compensan (muchos fármacos además reducen la capacidad de conducir)."},{"id":6133,"bg":"Възможни причини за отклоняване на вниманието на водача по време на управление са:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"четенето на крайпътни надписи","ok":true,"i":null,"es":"leer los carteles junto a la vía"},{"t":"извършването на действия, които не са във връзка с управлението","ok":true,"i":null,"es":"realizar acciones que no tienen relación con la conducción"},{"t":"говоренето по мобилен телефон","ok":true,"i":null,"es":"hablar por el teléfono móvil"},{"t":"бързо преминаващите автомобили","ok":false,"i":null,"es":"los automóviles que pasan a gran velocidad"}],"f":7,"es":"Posibles causas de distracción del conductor durante la conducción son: (3 correctas)","explain":"Distraen: leer carteles, hacer cosas ajenas a la conducción y hablar por el móvil: todas apartan la vista o la mente de la vía. Los coches que pasan rápido son parte del tráfico que precisamente hay que vigilar."},{"id":6136,"bg":"В коя част от денонощието остротата на зрението на човека намалява значително?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"в светлата част","ok":false,"i":null,"es":"en la parte luminosa (día)"},{"t":"в тъмната част","ok":true,"i":null,"es":"en la parte oscura (noche)"},{"t":"остротата на зрението не се променя през денонощието","ok":false,"i":null,"es":"la agudeza visual no varía"}],"f":7,"es":"¿En qué parte del día la agudeza visual del ser humano disminuye significativamente?","explain":"De NOCHE (la parte oscura): la agudeza visual humana cae drásticamente sin luz: se pierde detalle, color y percepción de distancias. Por eso de noche se reduce la velocidad aunque la vía parezca despejada."},{"id":6145,"bg":"Предупреждаващите признаци за умора у водача са:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"разсейването","ok":true,"i":null,"es":"la distracción"},{"t":"намаляването на обема на възприеманите обекти от пътната обстановка","ok":true,"i":null,"es":"la reducción de la cantidad de objetos percibidos de la situación vial"},{"t":"намаляването на точността на възприеманите обекти от пътната обстановка","ok":true,"i":null,"es":"la reducción de la precisión con que se perciben los objetos de la situación vial"},{"t":"точните реакции","ok":false,"i":null,"es":"las reacciones precisas"}],"f":7,"es":"Los signos de advertencia de fatiga en el conductor son: (3 correctas)","explain":"La fatiga avisa con: distracción, percepción de MENOS objetos de la situación vial y MENOS precisión al percibirlos. Las 'reacciones precisas' son lo contrario: señal de conductor descansado."},{"id":5506,"bg":"При спиране за проверка от контролен орган, ако няма други указания, водачът трябва:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да спре плавно","ok":true,"i":null,"es":"detenerse suavemente"},{"t":"да спре в най-дясната част на платното за движение","ok":true,"i":null,"es":"detenerse en la parte más a la derecha de la calzada"},{"t":"да спре незабавно пред контролния орган","ok":false,"i":null,"es":"detenerse inmediatamente ante el agente de control"},{"t":"да спре в средата на заеманата лента","ok":false,"i":null,"es":"detenerse en el centro del carril que ocupa"}],"f":7,"es":"Al detenerse para un control de un agente, si no hay otras indicaciones, el conductor debe: (2 correctas)","explain":"Ante la señal de stop del agente: detente con suavidad y en la parte más a la derecha de la calzada. Ni frenazo justo ante el agente ni parado en medio del carril: la detención tampoco debe crear peligro."},{"id":11362,"bg":"Намаляване на прозрачността на стъклата на задните странични врати на леките автомобили е:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"забранено във всичси случаи","ok":false,"i":null,"es":"prohibido en todos los casos"},{"t":"разрешено без ограничение","ok":false,"i":null,"es":"permitido sin restricción"},{"t":"се допуска само при наличие на огледала за виждане назад от двете страни на автомобила","ok":true,"i":null,"es":"se permite solo si hay espejos retrovisores a ambos lados del automóvil"}],"f":7,"es":"Reducir la transparencia de los cristales de las puertas laterales traseras de los turismos está:","explain":"Los cristales traseros laterales pueden oscurecerse SOLO si el coche tiene retrovisores exteriores a ambos lados: la visión trasera queda garantizada por los espejos. Ni prohibición total ni barra libre."},{"id":11367,"bg":"Разрешено ли е водачът на МПС да oрганизира или участва в нерегламентирани състезания по пътищата, отворени за обществено ползване?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"не, забранено е във всички случаи","ok":true,"i":null,"es":"no, está prohibido en todos los casos"},{"t":"не, освен по пътища извън населените места","ok":false,"i":null,"es":"no, salvo en vías fuera de poblado"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":7,"es":"¿Está permitido que el conductor organice o participe en carreras ilegales en vías abiertas al uso público?","explain":"Prohibido en todos los casos: organizar o participar en carreras ilegales en vías públicas es una de las infracciones más graves del código, dentro o fuera de poblado."},{"id":5455,"bg":"Извършва ли нарушение водач, който управлява МПС без табели с регистрационен номер?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":7,"es":"¿Comete infracción el conductor que conduce un vehículo sin placas de matrícula?","explain":"Sí: circular sin placas de matrícula es infracción: el vehículo debe estar identificado en todo momento. No hay supuesto que lo excuse."},{"id":5497,"bg":"Контролните органи преместват паркирано пътно превозно средство без знанието на неговия собственик, когато превозното средство:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"е паркирано правилно, но обстоятелствата налагат неговото преместване","ok":true,"i":null,"es":"está estacionado correctamente, pero las circunstancias exigen su traslado"},{"t":"е паркирано в нарушение на места, обозначени с неподвижен пътен знак, предупреждаващ за принудително преместване","ok":true,"i":null,"es":"está estacionado infringiendo en lugares señalizados con una señal fija que advierte de la retirada forzosa"},{"t":"създава опасност за другите участници в движението","ok":true,"i":null,"es":"crea peligro para los demás usuarios de la vía"},{"t":"винаги, когато е паркирано в нарушение на правилата за движение","ok":false,"i":null,"es":"siempre que esté estacionado infringiendo las normas de circulación"}],"f":7,"es":"Las autoridades de control retiran un vehículo estacionado sin conocimiento de su propietario cuando el vehículo: (3 correctas)","explain":"Retiran el vehículo: cuando aun bien estacionado las circunstancias exigen moverlo (obras, evento), cuando infringe en zona con señal fija que advierte de retirada, y cuando crea peligro. No 'siempre que infrinja': sin esas condiciones se sanciona pero no se retira."},{"id":11409,"bg":"При служебно прекратяване на регистрацията на ППС със съставянето на акта за установяване на административното нарушение се отнемат:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"табелите с регистрационен номер","ok":true,"i":null,"es":"las placas de matrícula"},{"t":"част 2 на свидетелството за регистрация на ППС","ok":true,"i":null,"es":"la parte 2 del permiso de circulación"},{"t":"част 1 на свидетелството за регистрация ППС","ok":false,"i":null,"es":"la parte 1 del permiso de circulación"}],"f":7,"es":"Al cancelar de oficio el registro de un vehículo, se retiran: (2 correctas)","explain":"Al cancelar de oficio el registro se retiran las placas de matrícula y la parte 2 del permiso de circulación (el documento pequeño que se lleva a bordo). La parte 1 queda con el propietario."},{"id":5340,"bg":"В кой от случаите при ПТП водачът е длъжен да вземе мерки за безопасността на движението?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"винаги, независимо дали е участник в произшествието или не","ok":true,"i":null,"es":"siempre, esté o no implicado en el accidente"},{"t":"само когато е участник в произшествието","ok":false,"i":null,"es":"solo cuando está implicado en el accidente"}],"f":7,"es":"¿En qué caso, en un accidente, el conductor está obligado a tomar medidas para la seguridad del tráfico?","explain":"Siempre: todo conductor que llega a un accidente debe tomar medidas de seguridad del tráfico (señalizar, proteger), esté o no implicado. Es un deber general de auxilio y prevención."},{"id":5349,"bg":"В кой от изброените случаи водачът е длъжен да се върне на мястото на ПТП, след като е превозил пострадал до болнично заведение?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"когато е участник в произшествието","ok":true,"i":null,"es":"cuando es parte implicada en el accidente"},{"t":"винаги, независимо от това дали е участник в произшествието","ok":false,"i":null,"es":"siempre, independientemente de si está implicado en el accidente"},{"t":"когато превозването е било разпоредено от органите за контрол","ok":false,"i":null,"es":"cuando el transporte haya sido ordenado por las autoridades de control"}],"f":7,"es":"¿En cuál de los casos indicados el conductor está obligado a volver al lugar del accidente después de trasladar a un herido a un hospital?","explain":"Debe volver al lugar cuando es PARTE IMPLICADA en el accidente: su presencia es necesaria para el atestado. Quien solo ayudó trasladando a un herido sin estar implicado no tiene esa obligación."},{"id":11431,"bg":"Водач, участник в ПТП, при което няма пострадали хора, длъжен ли е да уведоми контролните органи на МВР за произшествието?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да, ако между участниците в произшествието няма съгласие относно обстоятелствата, свързани с него","ok":true,"i":null,"es":"sí, si los implicados en el accidente no están de acuerdo sobre sus circunstancias"},{"t":"да, но само ако по превозното средство има значителни повреди","ok":false,"i":null,"es":"sí, pero solo si el vehículo tiene daños significativos"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":7,"es":"Un conductor implicado en un accidente sin heridos, ¿está obligado a avisar del accidente a las autoridades del MVR?","explain":"Debe avisarse al MVR cuando los implicados NO están de acuerdo sobre las circunstancias: sin acuerdo no cabe parte amistoso y hace falta atestado. Con acuerdo y solo daños materiales, basta el parte bilateral."},{"id":11650,"bg":"Кога водачът на МПС е задължен да окаже помощ на пострадали при пътнотранспортни произшествия, ако това не представлява опасност за него?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"когато е участник в произшествието","ok":true,"i":null,"es":"cuando es parte implicada en el accidente"},{"t":"когато не е участник в произшествието, но има хора, които се нуждаят от помощ","ok":true,"i":null,"es":"cuando no está implicado en el accidente, pero hay personas que necesitan ayuda"},{"t":"само, когато за това се разпореди контролен орган","ok":false,"i":null,"es":"solo cuando lo ordene un agente de control"}],"f":7,"es":"¿Cuándo está obligado el conductor a prestar ayuda a los heridos en accidentes de tráfico, si no supone un peligro para él? (2 correctas)","explain":"Debe prestar ayuda: cuando está implicado en el accidente y también cuando NO está implicado pero hay personas que la necesitan (deber general de auxilio, si no supone peligro para él). No hace falta orden de ningún agente."},{"id":6587,"bg":"След кой от тези знаци, при преминаване през кръстовището, превозното средство от другия път трябва да ви пропусне?","p":3,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/55265.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/55266.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334693.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/55247.png","es":""}],"f":7,"es":"¿Después de cuál de estas señales, al cruzar la intersección, el vehículo del otro camino debe cederte el paso? (2 correctas)","explain":"LA PRIMERA Y LA SEGUNDA SEÑAL. Dos correctas.\n\nQUÉ VES. Cuatro señales triangulares de advertencia o prioridad:\n1) Triángulo con un trazo GRUESO vertical cruzado por uno fino a ambos lados: cruce con una vía sin prioridad.\n2) Triángulo con un trazo GRUESO vertical y uno fino a un lado: cruce con una vía secundaria por ese lado.\n3) Triángulo INVERTIDO (con el vértice hacia abajo): CEDA EL PASO.\n4) Triángulo con flechas en círculo: aproximación a una ROTONDA.\n\nLAS DOS PRIMERAS TE DICEN QUE TÚ VAS POR LA PRINCIPAL. El trazo grueso es tu vía; los finos son las secundarias, cuyos vehículos te tienen que ceder el paso.\n\n«EL CEDA EL PASO» es el cebo opuesto: con él eres TÚ quien cede.\n\n«LA ROTONDA» solo te avisa de que se acerca una rotonda; no te da preferencia (al entrar, normalmente cederás tú).\n\nCLAVE: en las señales de cruce, el trazo grueso es el tuyo y el fino es el del que te cede.\n\nMÉTODO: 1) ¿la señal tiene trazos de distinto grosor? 2) ¿el grueso es el que va hacia arriba (mi vía)? 3) si es así, los de las ramas finas me ceden. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5260,"bg":"Кой от пътните знаци предупреждава за кръстовище с път без предимство?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/23809.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/23810.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/23811.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334675.png","es":""}],"f":7,"es":"¿Cuál de las señales advierte de una intersección con vía sin prioridad? (3 correctas)","explain":"LA PRIMERA, LA SEGUNDA Y LA TERCERA. Tres correctas.\n\nQUÉ VES. Cuatro triángulos: 1) trazo grueso vertical con trazos finos a ambos lados; 2) trazo grueso con un trazo fino a la derecha; 3) trazo grueso con un trazo fino a la izquierda; 4) una X.\n\nCÓMO SE LEEN LAS SEÑALES DE CRUCE (triángulos con trazos):\n• trazo GRUESO = tu vía, la que tiene prioridad;\n• trazo FINO = la vía sin prioridad que llega al cruce (por un lado, por el otro o por ambos);\n• una X (dos trazos iguales cruzados) = cruce de vías iguales, sin prioridad para nadie.\n\nLAS TRES PRIMERAS TIENEN TRAZO GRUESO: avisan de un cruce con una vía sin prioridad (por ambos lados, por la derecha o por la izquierda).\n\n«LA X» es el cebo: avisa de un cruce de vías iguales, donde se aplica la regla de la derecha.\n\nCLAVE: grueso + fino = vía sin prioridad; X = vías iguales. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6046,"bg":"Когато подава сигнал с ръка, при потегляне и включване в движението от дясната част на пътя, водачът на двуколесното ППС сигнализира чрез:","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/27812.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/27813.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/27814.png","es":""}],"f":7,"es":"Cuando da señal con el brazo al arrancar e incorporarse desde la parte derecha de la carretera, el conductor de un vehículo de dos ruedas señaliza con:","explain":"LA PRIMERA: BRAZO IZQUIERDO EXTENDIDO EN HORIZONTAL. Una sola correcta.\n\nQUÉ VES. Tres fotos de un motorista visto desde atrás: 1) brazo IZQUIERDO extendido en horizontal; 2) brazo levantado hacia arriba; 3) brazo DERECHO extendido en horizontal.\n\nSALIR DESDE EL BORDE DERECHO ES DESPLAZARSE A LA IZQUIERDA. El conductor de dos ruedas lo indica con el brazo izquierdo extendido en horizontal, igual que haría con el intermitente izquierdo.\n\n«EL BRAZO LEVANTADO» indica que va a detenerse o reducir.\n\n«EL BRAZO DERECHO EXTENDIDO» indica desplazamiento a la DERECHA.\n\nCLAVE: el brazo extendido señala el lado hacia el que te mueves; incorporarte desde la derecha = hacia la izquierda."},{"id":5253,"bg":"Кой от пътните знаци предупреждава за стеснение на платното за движение?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"es":"","i":"334669"},{"t":"","ok":true,"es":"","i":"334668"},{"t":"","ok":false,"es":"","i":"21263"},{"t":"","ok":false,"es":"","i":"334749"}],"f":7,"es":"¿Cuál de las señales advierte de estrechamiento de la calzada? (2 correctas)","explain":"LA PRIMERA Y LA SEGUNDA: LOS TRIÁNGULOS CON LA CALZADA QUE SE ESTRECHA. Dos correctas.\n\nQUÉ VES. Cuatro señales: 1) triángulo con estrechamiento por la DERECHA; 2) triángulo con estrechamiento por la IZQUIERDA; 3) cuadrado azul de un carril que se acaba; 4) señal amarilla de obras.\n\nLAS DOS PRIMERAS SON ESTRECHAMIENTOS: triángulos de peligro donde las líneas de la calzada se juntan.\n\n«EL CUADRADO AZUL» es el cebo fino: informa de que se acaba un carril, no de que la calzada se estreche, y es azul (información), no triangular.\n\n«LAS OBRAS» avisan de trabajos en la vía, no de un estrechamiento.\n\nCLAVE: compárala con la 5249 (solo el estrechamiento por la derecha). Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5261,"bg":"Кой от пътните знаци предупреждава за кръстовище с път без предимство?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":false,"es":"","i":"334675"},{"t":"","ok":true,"es":"","i":"23811"},{"t":"","ok":true,"es":"","i":"23810"},{"t":"","ok":false,"es":"","i":"24605"}],"f":7,"es":"¿Cuál de las señales advierte de intersección con vía sin prioridad? (2 correctas)","explain":"LA DE TRAZO FINO A LA IZQUIERDA Y LA DE TRAZO FINO A LA DERECHA. Dos correctas.\n\nQUÉ VES. Cuatro señales: una X en un triángulo, un triángulo con trazo grueso y fino a la izquierda, otro con trazo grueso y fino a la derecha, y un triángulo invertido.\n\nCÓMO SE LEEN LAS SEÑALES DE CRUCE (triángulos con trazos):\n• trazo GRUESO = tu vía, la que tiene prioridad;\n• trazo FINO = la vía sin prioridad que llega al cruce (por un lado, por el otro o por ambos);\n• una X (dos trazos iguales cruzados) = cruce de vías iguales, sin prioridad para nadie.\n\n«LA X» avisa de un cruce de vías iguales. «EL TRIÁNGULO INVERTIDO» es el ceda el paso: ahí el que no tiene prioridad eres tú.\n\nCLAVE: compárala con la 5260. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5381,"bg":"Този знак:","p":2,"s":"Раздел 4","i":"22272","v":null,"a":[{"t":"обозначава автомобил, който превозва организирана група деца","ok":true,"es":"identifica un automóvil que transporta un grupo organizado de niños"},{"t":"указва на децата място за преминаване през платното за движение","ok":false,"es":"indica a los niños un lugar para cruzar la calzada"},{"t":"предупреждава за деца на пътя","ok":false,"es":"advierte de niños en la vía"},{"t":"сигнализира място за спиране на училищен автобус","ok":false,"es":"señaliza un lugar de parada de autobús escolar"}],"f":7,"es":"Esta señal:","explain":"IDENTIFICA UN AUTOMÓVIL QUE TRANSPORTA UN GRUPO ORGANIZADO DE NIÑOS. Una sola correcta.\n\nLA SEÑAL. Cuadrado NARANJA con borde negro y dos NIÑOS caminando con mochila.\n\nNO ES UNA SEÑAL DE LA CARRETERA: es el distintivo que lleva el vehículo que transporta a un grupo organizado de niños. Al verlo, extremas la precaución: los niños pueden subir, bajar o cruzar cerca de él.\n\n«ADVIERTE DE NIÑOS EN LA VÍA» es el cebo: esa es una señal triangular de peligro, no un cuadrado naranja.\n\n«LUGAR DE CRUCE PARA NIÑOS» y «PARADA DE AUTOBÚS ESCOLAR» son otras señales distintas.\n\nCLAVE: cuadrado naranja con niños = va en un vehículo. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5222,"bg":"Кой от пътните знаци предупреждава за стръмен наклон при изкачване?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/21389.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/21390.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334664.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/21392.png","es":""}],"f":7,"es":"¿Cuál de las señales advierte de pendiente pronunciada en subida?","explain":"LA PRIMERA: TRIÁNGULO CON LA PENDIENTE QUE SUBE Y «10 %». Una sola correcta.\n\nQUÉ VES. Cuatro señales de peligro: 1) pendiente que SUBE de izquierda a derecha con «10 %»; 2) pendiente que BAJA de izquierda a derecha con «10 %»; 3) curva peligrosa a la derecha; 4) resalto (badén) en la calzada.\n\nSE LEE COMO SI CONDUJERAS DE IZQUIERDA A DERECHA: si la rampa sube, es subida; si baja, es bajada.\n\n«LA SEGUNDA» es el cebo directo: es la bajada pronunciada.\n\nCLAVE: compárala con la 6384, donde esta misma señal decide quién cede en un puente estrecho (cede el que baja). Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":11816,"bg":"С кой от опознавателните знаци се обозначават товарните автомобили с допустима максимална маса над 3500 kg и дължина над 7 метра?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/23016.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/23017.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334747.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334746.png","es":""}],"f":7,"es":"¿Con cuál de los signos distintivos se identifican los camiones con masa máxima admisible superior a 3500 kg y longitud superior a 7 metros? (2 correctas)","explain":"LA PRIMERA Y LA SEGUNDA: LAS PLACAS DE FRANJAS ROJAS Y AMARILLAS EN DIAGONAL. Dos correctas.\n\nQUÉ VES. La parte trasera de cuatro camiones con distintas placas reflectantes: 1) dos placas verticales con franjas rojas y amarillas en diagonal; 2) placas con franjas diagonales en forma de L; 3) y 4) placas amarillas lisas con borde ROJO.\n\nLAS FRANJAS DIAGONALES ROJAS Y AMARILLAS identifican a los camiones de más de 3,5 t y más de 7 m de longitud (en cualquiera de las dos disposiciones mostradas).\n\nLAS AMARILLAS CON BORDE ROJO son las de los REMOLQUES (compárala con la 11820).\n\nCLAVE: franjas diagonales = camión largo y pesado; amarillo con borde rojo = remolque."},{"id":5433,"bg":"Разликата между късите и дългите светлини на МПС е:","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"в дължината на осветявания участък от пътя","ok":true,"i":null,"es":"en la longitud del tramo de vía iluminado"},{"t":"в разположението на източника на светлината","ok":false,"i":null,"es":"en la posición de la fuente de luz"},{"t":"в цвета на светлината","ok":false,"i":null,"es":"en el color de la luz"},{"t":"в големината на светлинния източник","ok":false,"i":null,"es":"en el tamaño de la fuente de luz"}],"f":6,"es":"La diferencia entre las luces cortas y largas del vehículo está:","explain":"Cortas y largas se diferencian en la LONGITUD del tramo iluminado (unos 40-50 m frente a 100+ m). No cambia el color ni la posición de la fuente: cambia el alcance y la geometría del haz."},{"id":11881,"bg":"Минималната дълбочина на протектора на гумите (които не са за зимни условия) на автомобилите през периода от 15 ноември до 1 март е:","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"4,0 mm","ok":true,"i":null,"es":"4,0 mm"},{"t":"0,5 mm","ok":false,"i":null,"es":"0,5 mm"},{"t":"1,0 mm","ok":false,"i":null,"es":"1,0 mm"},{"t":"3,0 mm","ok":false,"i":null,"es":"3,0 mm"}],"f":6,"es":"La profundidad mínima de la banda de rodadura de los neumáticos (que no son de invierno) de los automóviles en el período del 15 de noviembre al 1 de marzo es:","explain":"4,0 mm: profundidad mínima del dibujo entre el 15 de noviembre y el 1 de marzo para neumáticos que no son de invierno. El resto del año el mínimo general es menor: la exigencia invernal es específica."},{"id":5440,"bg":"Количеството на течността в охладителната уредба е отчетено правилно, когато проверката на нивото на течността е извършена:","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"при студен двигател","ok":true,"i":null,"es":"con el motor FRÍO"},{"t":"без съобразяване с температурата на двигателя","ok":false,"i":null,"es":"sin importar la temperatura"},{"t":"при подгрят двигател","ok":false,"i":null,"es":"con el motor caliente"}],"f":6,"es":"El nivel de líquido refrigerante se mide correctamente cuando:","explain":"Con el motor FRÍO: en caliente el líquido está expandido y presurizado (riesgo de quemadura al abrir y lectura falsa). Las marcas MIN/MAX del depósito de expansión están calibradas en frío."},{"id":5479,"bg":"Светването на този символ върху арматурното табло означава, че:","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334685.png","v":null,"a":[{"t":"е задействана спирачката за паркиране","ok":true,"i":null,"es":"está accionado el freno de estacionamiento"},{"t":"са включени светлините за паркиране","ok":false,"i":null,"es":"están encendidas las luces de estacionamiento"},{"t":"налягането на маслото в двигателя е ниско","ok":false,"i":null,"es":"la presión del aceite del motor es baja"},{"t":"има повреда в спирачната система","ok":false,"i":null,"es":"hay una avería en el sistema de frenos"}],"f":6,"es":"El encendido de este símbolo en el cuadro de instrumentos significa que:","explain":"ESTÁ ACCIONADO EL FRENO DE ESTACIONAMIENTO. Una sola correcta.\n\nQUÉ VES. Un testigo ROJO con una «P» dentro de un círculo, entre dos paréntesis.\n\nLA «P» EN EL CÍRCULO es el freno de mano (de estacionamiento): se enciende mientras está puesto.\n\n«LUCES DE ESTACIONAMIENTO» tienen un testigo verde con dos lámparas. «PRESIÓN DE ACEITE» es la aceitera. «AVERÍA DE FRENOS» suele llevar un «!».\n\nCLAVE: compárala con la 5483."},{"id":11655,"bg":"Светването по време на движение на този символ върху арматурното табло на автомобила означава, че:","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123801958.png","v":null,"a":[{"t":"има неизправност в антиблокиращата система","ok":true,"i":null,"es":"hay un fallo en el sistema antibloqueo (ABS)"},{"t":"задействана е антиблокиращата система на спирачната уредба","ok":false,"i":null,"es":"se ha activado el sistema antibloqueo (ABS) de los frenos"},{"t":"спирачните накладки са износени","ok":false,"i":null,"es":"las pastillas de freno están desgastadas"},{"t":"системата е готова за използване","ok":false,"i":null,"es":"el sistema está listo para su uso"}],"f":6,"es":"El encendido durante la marcha de este símbolo en el cuadro de instrumentos del automóvil significa que:","explain":"HAY UN FALLO EN EL SISTEMA ANTIBLOQUEO (ABS). Una sola correcta.\n\nQUÉ VES. Un testigo AMARILLO con «ABS» dentro de un círculo entre paréntesis.\n\nENCENDIDO DURANTE LA MARCHA = EL ABS NO FUNCIONA. Los frenos siguen funcionando, pero las ruedas se pueden bloquear en una frenada fuerte. Llevas el coche a revisar.\n\n«SE HA ACTIVADO EL ABS» es el cebo: cuando el ABS actúa no se enciende ningún testigo (se nota en el pedal). «PASTILLAS GASTADAS» tiene otro testigo. «LISTO PARA USAR» sería que se apague tras arrancar.\n\nCLAVE: compárala con la 5483 (amarillo = revisa pronto)."},{"id":5450,"bg":"Пониженото ниво на коя от изброените течности може да причини пътнотранспортно произшествие?","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"на течността в спирачната система","ok":true,"i":null,"es":"el líquido del sistema de FRENOS"},{"t":"на течността в охладителната система","ok":false,"i":null,"es":"el líquido del sistema de refrigeración"},{"t":"на маслото в трансмисията","ok":false,"i":null,"es":"el aceite de la transmisión"}],"f":6,"es":"¿El nivel bajo de qué líquido puede causar un accidente?","explain":"El nivel bajo del líquido de FRENOS puede causar directamente un accidente: sin presión hidráulica no hay frenada. El refrigerante o el aceite de transmisión bajos dañan el vehículo, pero no te dejan sin frenos de golpe."},{"id":5199,"bg":"Състав от пътни превозни средства са:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"механично свързани ППС, които участват в движението като едно цяло","ok":true,"i":null,"es":"vehículos unidos mecánicamente que participan en el tráfico como un conjunto"},{"t":"МПС с полуремарке","ok":true,"i":null,"es":"vehículo de motor con semirremolque"},{"t":"МПС теглещо ремарке","ok":true,"i":null,"es":"vehículo de motor que remolca un remolque"},{"t":"автомобилите с допълнително монтирани съоръжения","ok":false,"i":null,"es":"los automóviles con equipos adicionales instalados"}],"f":6,"es":"Un tren de vehículos de carretera está formado por: (3 correctas)","explain":"Un tren de carretera son vehículos unidos MECÁNICAMENTE circulando como conjunto: motor + remolque o motor + semirremolque. Un automóvil con equipos adicionales instalados sigue siendo un solo vehículo, no un tren."},{"id":5223,"bg":"Кои от изброените правила се прилагат при движение в населено място?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"допуска се паркиране на платното за движение","ok":true,"i":null,"es":"se permite estacionar en la calzada"},{"t":"може да се паркира на обозначени места върху тротоарите","ok":true,"i":null,"es":"se puede estacionar en lugares señalizados sobre las aceras"},{"t":"забранено е паркирането на платното за движение","ok":false,"i":null,"es":"está prohibido estacionar en la calzada"},{"t":"няма ограничение за паркиране върху тротоарите","ok":false,"i":null,"es":"no hay restricción para estacionar sobre las aceras"}],"f":6,"es":"¿Cuáles de las normas se aplican al circular en población? (2 correctas)","explain":"En población se permite estacionar en la calzada y sobre las aceras en los lugares señalizados para ello. Las opciones que lo prohíben todo o lo permiten sin restricción alguna deforman la norma en ambos extremos."},{"id":5314,"bg":"Видимостта е ограничена при:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"стръмни наклони","ok":true,"i":null,"es":"pendientes pronunciadas"},{"t":"завои","ok":true,"i":null,"es":"curvas"},{"t":"здрач","ok":false,"i":null,"es":"el crepúsculo"},{"t":"мъгла","ok":false,"i":null,"es":"niebla"}],"f":6,"es":"La visibilidad esta limitada en: (2 correctas)","explain":"Visibilidad LIMITADA es la restringida por la geometría de la vía: curvas y cambios de rasante (pendientes). El crepúsculo y la niebla producen visibilidad REDUCIDA (condiciones atmosféricas/luz). El examen explota esta distinción constantemente."},{"id":5167,"bg":"Този пътен знак предупреждава за:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/20360.png","v":null,"a":[{"t":"опасeн завой наляво","ok":true,"i":null,"es":"curva peligrosa a la izquierda"},{"t":"опасност ППС да излезе от пътя наляво","ok":false,"i":null,"es":"peligro de que el vehículo se salga de la vía por la izquierda"},{"t":"кръстовище, на което задължително трябва да се завие наляво","ok":false,"i":null,"es":"intersección donde es obligatorio girar a la izquierda"},{"t":"опасен наклон на пътя","ok":false,"i":null,"es":"pendiente peligrosa de la vía"}],"f":6,"es":"Esta señal advierte de:","explain":"CURVA PELIGROSA A LA IZQUIERDA. Una sola correcta.\n\nLA SEÑAL. Triángulo de peligro con una línea que sube y se dobla hacia la IZQUIERDA.\n\nES EL TRAZADO DE LA CARRETERA: más adelante hay una curva peligrosa hacia la izquierda.\n\n«PELIGRO DE SALIRSE POR LA IZQUIERDA» es el cebo de quien lee el dibujo como una advertencia sobre el vehículo.\n\n«CRUCE DONDE ES OBLIGATORIO GIRAR A LA IZQUIERDA» sería una señal azul circular (obligación), no un triángulo.\n\n«PENDIENTE PELIGROSA» es la señal con la rampa y el porcentaje.\n\nCLAVE: triángulo = aviso; la línea dibuja la carretera. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5197,"bg":"Този пътен знак предупреждава за:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334668.png","v":null,"a":[{"t":"стесняване на платното за движение отляво","ok":true,"i":null,"es":"estrechamiento de la calzada por la izquierda"},{"t":"промяна в наклона на пътя","ok":false,"i":null,"es":"cambio de la pendiente de la vía"},{"t":"вливане на пътна лента отляво","ok":false,"i":null,"es":"incorporación de un carril por la izquierda"},{"t":"опасен пътен банкет отляво","ok":false,"i":null,"es":"arcén peligroso a la izquierda"}],"f":6,"es":"Esta señal advierte de:","explain":"ESTRECHAMIENTO DE LA CALZADA POR LA IZQUIERDA. Una sola correcta.\n\nLA SEÑAL. Triángulo de peligro con dos líneas verticales: la de la IZQUIERDA se dobla hacia dentro y la de la derecha sigue recta.\n\nEL LADO QUE SE DOBLA ES EL LADO POR EL QUE SE ESTRECHA LA CALZADA.\n\n«INCORPORACIÓN DE UN CARRIL POR LA IZQUIERDA» es el cebo: un carril que se une se indica con una señal azul de flechas, no con un triángulo.\n\n«CAMBIO DE PENDIENTE» y «ARCÉN PELIGROSO» son otras señales.\n\nCLAVE: compárala con la 5249 (estrechamiento por la derecha). Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5217,"bg":"След този пътен знак:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334749.png","v":null,"a":[{"t":"на платното за движение може да има работещи хора","ok":true,"i":null,"es":"en la calzada puede haber personas trabajando"},{"t":"може да има препятствия по платното за движение","ok":true,"i":null,"es":"puede haber obstáculos en la calzada"},{"t":"пътят е затворен за движение","ok":false,"i":null,"es":"la vía está cerrada al tráfico"},{"t":"паркирането е забранено","ok":false,"i":null,"es":"el estacionamiento está prohibido"}],"f":6,"es":"Después de esta señal: (2 correctas)","explain":"EN LA CALZADA PUEDE HABER PERSONAS TRABAJANDO Y PUEDE HABER OBSTÁCULOS. Dos correctas.\n\nLA SEÑAL. Triángulo de peligro con fondo AMARILLO (temporal) y un trabajador con pala: OBRAS.\n\nQUÉ ANUNCIA: trabajadores en la vía y obstáculos propios de una obra (material, máquinas, zanjas).\n\n«LA VÍA ESTÁ CERRADA» es falso: el triángulo avisa; un cierre se indica con una señal de prohibición.\n\n«EL ESTACIONAMIENTO ESTÁ PROHIBIDO» tampoco: eso sería otra señal circular.\n\nCLAVE: triángulo de obras = precaución, no prohibición. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5266,"bg":"Този пътен знак предупреждава за:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334676.png","v":null,"a":[{"t":"кръстовище с кръгово движение","ok":true,"i":null,"es":"intersección con circulación giratoria (glorieta)"},{"t":"място, на което задължително се завива в обратна посока","ok":false,"i":null,"es":"lugar donde es obligatorio dar la vuelta (cambio de sentido)"},{"t":"участък от пътя, по който е забранено да се завива в обратна посока","ok":false,"i":null,"es":"tramo de vía donde está prohibido el cambio de sentido"},{"t":"остров на платното за движение","ok":false,"i":null,"es":"isleta en la calzada"}],"f":6,"es":"Esta señal advierte de:","explain":"CRUCE CON CIRCULACIÓN GIRATORIA (ROTONDA). Una sola correcta.\n\nLA SEÑAL. Triángulo de peligro con tres flechas formando un círculo.\n\nAVISA DE QUE SE ACERCA UNA ROTONDA. Es un triángulo: avisa; no da ni quita preferencia.\n\n«LUGAR DE CAMBIO DE SENTIDO OBLIGATORIO», «PROHIBIDO CAMBIAR DE SENTIDO» e «ISLETA EN LA CALZADA» son cebos que leen las flechas como una vuelta en U.\n\nCLAVE: flechas en círculo dentro de un triángulo = rotonda próxima. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5283,"bg":"Този пътен знак:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334678.png","v":null,"a":[{"t":"обозначава точното място на пешеходна пътека","ok":true,"i":null,"es":"indica el lugar exacto de un paso de peatones"},{"t":"предупреждава водачите, че приближават пешеходна пътека","ok":false,"i":null,"es":"advierte a los conductores de que se acercan a un paso de peatones"},{"t":"сигнализира началото на задължителен път само за пешеходци","ok":false,"i":null,"es":"señaliza el inicio de una vía obligatoria solo para peatones"},{"t":"указва начало на пешеходен маршрут","ok":false,"i":null,"es":"indica el inicio de una ruta peatonal"}],"f":6,"es":"Esta señal:","explain":"INDICA EL LUGAR EXACTO DE UN PASO DE PEATONES. Una sola correcta.\n\nLA SEÑAL. CUADRADO AZUL con un triángulo blanco dentro, y en él un peatón sobre las franjas de un paso.\n\nLA CUADRADA AZUL ESTÁ JUSTO EN EL PASO. La que avisa de que te ACERCAS a un paso de peatones es la TRIANGULAR roja (de peligro), colocada antes.\n\n«ADVIERTE DE QUE SE ACERCAN A UN PASO» es el cebo: esa es la triangular.\n\n«VÍA SOLO PARA PEATONES» y «RUTA PEATONAL» son señales distintas (circular azul con peatón y otras informativas).\n\nCLAVE: triangular = se acerca el paso; cuadrada azul = aquí está el paso. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":11601,"bg":"Този пътен знак сигнализира:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123565575.png","v":null,"a":[{"t":"за използването на пътя се изисква платена винетна или ТОЛ такса","ok":true,"i":null,"es":"para usar la vía se exige el pago de viñeta o peaje (TOL)"},{"t":"двупосочно движение след знака","ok":false,"i":null,"es":"circulación en ambos sentidos después de la señal"},{"t":"автомобилен път","ok":false,"i":null,"es":"vía rápida"},{"t":"броя на пътните ленти за движение в една посока","ok":false,"i":null,"es":"el número de carriles de circulación en un sentido"}],"f":6,"es":"Esta señal señaliza:","explain":"PARA USAR LA VÍA SE EXIGE EL PAGO DE VIÑETA O PEAJE (TOL). Una sola correcta.\n\nLA SEÑAL. Cuadrado AZUL con una autopista dibujada arriba y, debajo, «ВИНЕТКА / VIGNETTE» (con un turismo hasta 3,5 t) y «ТОЛ / TOLL» (con vehículos de más de 3,5 t y autobuses).\n\nQUÉ INDICA. Que esa vía es de pago: viñeta para los vehículos ligeros y peaje (TOL) para los pesados.\n\n«DOBLE SENTIDO», «VÍA RÁPIDA» y «NÚMERO DE CARRILES» son cebos que se fijan solo en el dibujo de la carretera.\n\nCLAVE: si la señal pone «ВИНЕТКА» o «ТОЛ», trata del pago. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5539,"bg":"Пътното превозно средство е извънгабаритно когато:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"височината му, включително товара, е 4,5 м","ok":true,"i":null,"es":"4.5 m"},{"t":"височината му, включително товара, е 4,8 м","ok":true,"i":null,"es":"4.8 m"},{"t":"височината му, включително товара, е 2,5 м","ok":false,"i":null,"es":"2.5 m"},{"t":"височината му, включително товара, е 3,5 м","ok":false,"i":null,"es":"3.5 m"}],"f":6,"es":"Un vehículo es 'fuera de gálibo' cuando su altura, incluyendo carga, es: (2 correctas)","explain":"El límite de altura es 4 m: cualquier altura superior es fuera de gálibo, por eso tanto 4,5 m como 4,8 m son correctas. 2,5 m y 3,5 m quedan por debajo del límite."},{"id":5552,"bg":"При тази ситуация:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/23978.png","v":null,"a":[{"t":"трябва да бъда внимателен и предпазлив","ok":true,"i":null,"es":"debo ser atento y prudente"},{"t":"няма опасност защото велосипедистите са в съседната пътна лента и ме виждат","ok":false,"i":null,"es":"no hay peligro porque los ciclistas están en el carril contiguo y me ven"}],"f":6,"es":"En esta situación:","explain":"DEBO SER ATENTO Y PRUDENTE. Una sola correcta.\n\nQUÉ VES. Calle urbana. Por el carril contrario vienen dos CICLISTAS jóvenes, uno de ellos hacia el centro de la calzada.\n\nLOS CICLISTAS PUEDEN DESVIARSE O CAERSE en cualquier momento, y uno ya va hacia el centro. Que estén en el otro carril no garantiza que sigan ahí.\n\n«NO HAY PELIGRO PORQUE ESTÁN EN EL CARRIL CONTIGUO Y ME VEN» es el cebo: da por hecho dos cosas que no puedes saber.\n\nCLAVE: compárala con la 5899 y la 5901 (la misma escena). Ver Leyes → «Carril: dónde debes circular»."},{"id":6027,"bg":"При тази ситуация няма опасност, защото детето се качва на тротоара и освобождава платното за движение.","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/25918.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":6,"es":"En esta situación no hay peligro porque el niño sube a la acera y libera la calzada. Esto es:","explain":"INCORRECTO.\n\nQUÉ VES. Calle urbana. En la acera derecha hay varios NIÑOS; uno, con gorra roja, acaba de subir a la acera desde la calzada.\n\nQUE SUBA A LA ACERA NO ELIMINA EL PELIGRO. Los niños pueden volver a bajar de golpe, y hay más en la acera. Tienes que seguir atento y moderar la velocidad.\n\n«CORRECTO» es el cebo de quien da el peligro por terminado en cuanto el niño sale de la calzada.\n\nCLAVE: donde hay niños, el peligro dura hasta que los dejas atrás. Ver Leyes → «Niños en la vía»."},{"id":6052,"bg":"Как водачът трябва сигнализира за намерението си да се включи в движението, когато автомобилът е с повреден пътепоказател?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"подава сигнал с ръка","ok":true,"i":null,"es":"hace una señal con la mano"},{"t":"подава звуков сигнал","ok":false,"i":null,"es":"da una señal acústica"},{"t":"не е задължен да сигнализира","ok":false,"i":null,"es":"no está obligado a señalizar"},{"t":"достатъчно е превключването на светлините","ok":false,"i":null,"es":"basta con cambiar las luces"}],"f":6,"es":"¿Cómo debe señalizar el conductor su intención de incorporarse al tráfico cuando el intermitente esta averiado?","explain":"Con el intermitente averiado, la intención se señaliza CON LA MANO (brazo extendido): es el sustituto legal. El claxon no indica dirección, no señalizar es infracción y el juego de luces no es señal de incorporación."},{"id":6064,"bg":"Водачът на МПС може да подава сигнал към другите участници в движението, чрез кратковременно включване на дългите светлини (светлинния клаксон):","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"за да ги предупреди за евентуална опасност при извършване на маневра","ok":true,"i":null,"es":"para advertirles de un posible peligro al realizar una maniobra"},{"t":"за да привлече тяхното внимание при извършване на маневра","ok":true,"i":null,"es":"para llamar su atención al realizar una maniobra"},{"t":"за да укаже, че ще завива в обратна посока","ok":false,"i":null,"es":"para indicar que va a hacer un cambio de sentido"},{"t":"за да им покаже, че е с предимство","ok":false,"i":null,"es":"para mostrarles que tiene prioridad"}],"f":6,"es":"El conductor de un vehículo puede dar señal a otros participantes mediante el encendido breve de las luces largas: (2 correctas)","explain":"El destello breve de largas sirve para advertir de un peligro o llamar la atención al maniobrar (típico aviso de adelantamiento). No indica cambio de sentido ni sirve para 'reclamar' prioridad: la prioridad no se exige con luces."},{"id":6691,"bg":"При коя от изброените широчини, автомобилът е извънгабаритен:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"широчина 2,9 м","ok":true,"i":null,"es":"2.9 m"},{"t":"широчина 2,7 м","ok":true,"i":null,"es":"2.7 m"},{"t":"широчина 2,5 м","ok":false,"i":null,"es":"2.5 m"},{"t":"широчина 2,3 м","ok":false,"i":null,"es":"2.3 m"}],"f":6,"es":"¿A qué anchura es un vehículo fuera de gálibo? (2 correctas)","explain":"El límite de anchura es 2,55 m: cualquier valor superior es fuera de gálibo, por eso 2,7 m y 2,9 m son correctas. 2,3 m y 2,5 m quedan dentro del límite."},{"id":9854,"bg":"В кои от посочените случаи водачът на нерелсово ППС е длъжен да пропусне преминаващите по пешеходна пътека пешеходци:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/270044468.png","v":null,"a":[{"t":"когато пътеката е очертана с прекъснати линии","ok":true,"i":null,"es":"cuando el paso está marcado con líneas discontinuas"},{"t":"само когато пътеката е тип „Зебра”","ok":false,"i":null,"es":"solo cuando el paso es de tipo \"cebra\""},{"t":"когато пътеката не е очертана с пътна маркировка","ok":true,"i":null,"es":"cuando el paso no está marcado con marcas viales"},{"t":"само когато пътеката е обозначена с пътен знак","ok":false,"i":null,"es":"solo cuando el paso está indicado con una señal de tráfico"}],"f":6,"es":"¿En cuáles de los casos el conductor de un vehículo no ferroviario está obligado a ceder el paso a los peatones que cruzan por el paso de peatones? (2 correctas)","explain":"CUANDO EL PASO ESTÁ MARCADO CON LÍNEAS DISCONTINUAS Y CUANDO NO ESTÁ MARCADO CON MARCAS VIALES. Dos correctas.\n\nQUÉ VES. Un cruce con señal de vía con prioridad. Un coche ROJO se acerca y una PEATONA cruza la calzada delante de él. Al fondo se ve un paso pintado tipo cebra.\n\nLA OBLIGACIÓN DE CEDER NO DEPENDE DE LA PINTURA. Un paso de peatones puede estar marcado con líneas discontinuas o no tener marca en el suelo (por ejemplo, en la prolongación de la acera en un cruce), y el peatón tiene preferencia igual.\n\n«SOLO CUANDO ES DE TIPO CEBRA» y «SOLO CUANDO ESTÁ INDICADO CON SEÑAL» son los cebos: los dos llevan la palabra «solo», que convierte una verdad parcial en falsa.\n\nCLAVE: en este banco, «solo» y «siempre» suelen delatar la opción falsa. Ver Leyes → «Paso de peatones»."},{"id":11813,"bg":"С този опознавателен знак се обозначават:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123823629.png","v":null,"a":[{"t":"товарните автомобили с допустима максимална маса над 3500 kg и дължина над 7 метра","ok":true,"i":null,"es":"camiones con masa máxima autorizada superior a 3500 kg y longitud superior a 7 metros"},{"t":"всички товарни автомобили","ok":false,"i":null,"es":"todos los camiones"},{"t":"товарните автомобили с допустима максимална маса над 3500 kg, като дължината на МПС е без значение","ok":false,"i":null,"es":"los camiones de masa máxima autorizada superior a 3500 kg, sin importar la longitud del vehículo"}],"f":6,"es":"Con este signo distintivo se identifican:","explain":"CAMIONES DE MÁS DE 3500 kg Y DE MÁS DE 7 m DE LONGITUD. Una sola correcta.\n\nQUÉ VES. La parte trasera de un camión con dos placas verticales de FRANJAS DIAGONALES ROJAS Y AMARILLAS.\n\nLAS FRANJAS DIAGONALES las llevan los camiones que cumplen LAS DOS condiciones: masa máxima autorizada superior a 3500 kg Y longitud superior a 7 m.\n\n«TODOS LOS CAMIONES» es el cebo: un camión corto o ligero no la lleva.\n\n«MÁS DE 3500 kg SIN IMPORTAR LA LONGITUD» es el cebo fino: olvida la segunda condición.\n\nCLAVE: franjas diagonales = pesado Y largo; amarillo liso con borde rojo = remolque. Compárala con la 11816 y la 11820."},{"id":11814,"bg":"С този опознавателен знак се обозначават:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123828334.png","v":null,"a":[{"t":"товарните автомобили с допустима максимална маса над 3500 kg и дължина над 7 метра","ok":true,"i":null,"es":"camiones con masa máxima autorizada superior a 3500 kg y longitud superior a 7 metros"},{"t":"товарните автомобили с допустима максимална маса над 2500 kg и дължина над 5 метра","ok":false,"i":null,"es":"camiones con masa superior a 2500 kg y longitud superior a 5 metros"},{"t":"всички товарни автомобили","ok":false,"i":null,"es":"todos los camiones"}],"f":6,"es":"Con esta señal de identificación se marcan:","explain":"CAMIONES DE MÁS DE 3500 kg Y DE MÁS DE 7 m DE LONGITUD. Una sola correcta.\n\nQUÉ VES. La parte trasera de un camión con dos placas verticales de FRANJAS DIAGONALES ROJAS Y AMARILLAS.\n\nLAS FRANJAS DIAGONALES las llevan los camiones que cumplen LAS DOS condiciones: más de 3500 kg y más de 7 m.\n\n«MÁS DE 2500 kg Y MÁS DE 5 m» inventa otras cifras. «TODOS LOS CAMIONES» olvida las dos condiciones.\n\nCLAVE: compárala con la 11813 y la 11815."},{"id":12075,"bg":"С жълта мигаща или проблясваща светлина се обозначава:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"МПС, което е препятствие за другите превозни средства","ok":true,"i":null,"es":"un vehículo de motor que es un obstáculo para los demás vehículos"},{"t":"МПС, което създава опасност за движението","ok":true,"i":null,"es":"un vehículo de motor que crea peligro para el tráfico"},{"t":"МПС със специален режим на движение","ok":false,"i":null,"es":"un vehículo de motor con régimen especial de circulación"},{"t":"всички автомобили със специално предназначение","ok":false,"i":null,"es":"todos los automóviles de uso especial"}],"f":6,"es":"Con luz amarilla intermitente o destellante se identifica: (2 correctas)","explain":"La luz amarilla intermitente identifica al vehículo que es un OBSTÁCULO o crea peligro para el tráfico (grúas, quitanieves, transportes especiales). El régimen especial de circulación usa luces azules/rojas: esa es la diferencia clave."},{"id":5984,"bg":"Този пътен знак:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/51835.png","v":null,"a":[{"t":"забранява влизането на МПС с ремаркета с две и повече оси","ok":true,"i":null,"es":"prohíbe la entrada de vehículos con remolques de dos o más ejes"},{"t":"не забранява влизането на МПС с полуремаркета","ok":false,"i":null,"es":"NO prohíbe la entrada de vehículos con semirremolques"},{"t":"забранява влизането на МПС с единични едноосни ремаркета","ok":true,"i":null,"es":"prohíbe la entrada de vehículos con remolques simples de un eje"}],"f":6,"es":"Esta señal: (2 correctas)","explain":"PROHÍBE LA ENTRADA DE VEHÍCULOS CON REMOLQUES DE DOS O MÁS EJES Y CON REMOLQUES SIMPLES DE UN EJE. Dos correctas.\n\nLA SEÑAL. Círculo con borde ROJO con un REMOLQUE DE UN EJE dibujado solo (la misma de la 5983).\n\nLAS DOS SEÑALES DE REMOLQUE, QUE SE CONFUNDEN:\n• REMOLQUE DE UN EJE dibujado solo (sin vehículo tractor) = prohibido a TODOS los vehículos con remolque (de uno o más ejes, y semirremolques);\n• vehículo con REMOLQUE DE DOS EJES = prohibido a los que llevan remolque, EXCEPTO semirremolques y remolques simples de un eje.\n\n«NO PROHÍBE LOS SEMIRREMOLQUES» es el cebo: esa excepción es de la otra señal; esta prohíbe todos los remolques.\n\nCLAVE: compárala con la 5983. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6192,"bg":"Този пътен знак:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334696.png","v":null,"a":[{"t":"задължава водачите да се движат само наляво пред знака","ok":true,"i":null,"es":"obliga a circular solo a la izquierda ANTES de la señal"},{"t":"задължава водачите да се движат само наляво след знака","ok":false,"i":null,"es":"obliga a circular solo a la izquierda DESPUÉS de la señal"},{"t":"задължава водачите да преминат отляво на знака","ok":false,"i":null,"es":"obliga a pasar por la izquierda de la señal"}],"f":6,"es":"Esta señal:","explain":"OBLIGA A CIRCULAR SOLO A LA IZQUIERDA ANTES DE LA SEÑAL. Una sola correcta.\n\nLA SEÑAL. Círculo AZUL con una flecha blanca HORIZONTAL hacia la izquierda.\n\nLA FLECHA HORIZONTAL obliga a girar ANTES de llegar a la señal, que suele estar al fondo de un cruce en T.\n\n«DESPUÉS DE LA SEÑAL» es la flecha que sube y GIRA. «PASAR POR LA IZQUIERDA DE LA SEÑAL» es la flecha OBLICUA hacia abajo.\n\nCLAVE: compárala con la 6191 (la misma pregunta en otra forma). Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6239,"bg":"Допълнителната табела указва, че в посоченото време паркирането е:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/54088.png","v":null,"a":[{"t":"забранено","ok":true,"i":null,"es":"prohibido"},{"t":"разрешено","ok":false,"i":null,"es":"permitido"}],"f":6,"es":"La tablilla adicional indica que en el horario señalado el aparcamiento está:","explain":"PROHIBIDO. Una sola correcta.\n\nQUÉ VES. La señal de PROHIBIDO ESTACIONAR (círculo azul con borde rojo y una barra roja) con una placa debajo: «6.00-17.00».\n\nLA PLACA CON HORARIO LIMITA CUÁNDO SE APLICA LA PROHIBICIÓN: entre las 6:00 y las 17:00 no se puede aparcar. Fuera de ese horario, sí.\n\n«PERMITIDO» es el cebo de quien lee el horario como el tiempo en que se permite aparcar.\n\nCLAVE: la placa dice cuándo vale la señal principal, no lo contrario. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":11869,"bg":"При тази ситуация, движението на товарни автомобили по лентата, над която е поставен пътният знак, е:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57279.png","v":null,"a":[{"t":"забранено","ok":true,"i":null,"es":"prohibido"},{"t":"разрешено без ограничения","ok":false,"i":null,"es":"permitido sin restricciones"},{"t":"разрешено, но само със скорост не по-висока от означената","ok":false,"i":null,"es":"permitido, pero solo a una velocidad no superior a la indicada"},{"t":"разрешено, ако масата им с товар е не по-голяма от 3.5 t","ok":false,"i":null,"es":"permitido, si su masa con carga no supera las 3,5 t"}],"f":6,"es":"En esta situación, la circulación de camiones por el carril sobre el que está colocada la señal está:","explain":"PROHIBIDO. Una sola correcta.\n\nQUÉ VES. Sobre un carril hay una señal circular de PROHIBIDA LA ENTRADA A CAMIONES, con una placa con una flecha que apunta hacia abajo, hacia ese carril. A un lado hay una señal de velocidad máxima de 50.\n\nLA FLECHA HACIA ABAJO DICE A QUÉ CARRIL SE APLICA LA SEÑAL: por ese carril los camiones no pueden circular.\n\n«PERMITIDO A NO MÁS DE LA VELOCIDAD INDICADA» es el cebo que mezcla la señal de 50 (que es para todos) con la prohibición.\n\n«PERMITIDO SI NO SUPERA 3,5 t» es otro cebo: la señal no lleva ninguna placa de masa que lo diga.\n\n«SIN RESTRICCIONES» contradice la señal.\n\nCLAVE: señal sobre un carril con flecha hacia abajo = vale para ese carril. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":11889,"bg":"По този път извън населено място, участъкът с опасни завои започва на разстояние:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/56122.png","v":null,"a":[{"t":"от 100 до 150 метра след знака","ok":true,"i":null,"es":"entre 100 y 150 metros después de la señal"},{"t":"от 50 до 100 метра след знака","ok":false,"i":null,"es":"entre 50 y 100 metros después"},{"t":"на 250 метра след знака","ok":false,"i":null,"es":"a 250 metros"},{"t":"не повече от 250 метра","ok":false,"i":null,"es":"no más de 250 metros"}],"f":6,"es":"Por esta carretera fuera de población, el tramo con curvas peligrosas empieza a:","explain":"ENTRE 100 Y 150 m DESPUÉS DE LA SEÑAL. Una sola correcta.\n\nQUÉ VES. Carretera fuera de población con curvas balizadas. A la derecha, el triángulo de CURVAS SUCESIVAS con una placa «↑ 250 m ↑» (ampliada en la imagen).\n\nLA PLACA CON FLECHAS DA LA LONGITUD del tramo (250 m), no dónde empieza. Dónde empieza lo marca la regla general: fuera de población, las señales de peligro se ponen de 100 a 150 m antes.\n\n«A 250 m» y «NO MÁS DE 250 m» son los cebos: leen la longitud como una distancia.\n\n«50-100 m» es la distancia en población.\n\nCLAVE: compárala con la 6238 y la 6287. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5915,"bg":"Жълтата мигаща светлина:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43915.png","v":null,"a":[{"t":"означава „Внимание”","ok":true,"i":null,"es":"significa '¡Atención!'"},{"t":"предупреждава водачите да бъдат внимателни и предпазливи","ok":true,"i":null,"es":"advierte a los conductores que sean atentos y precavidos"},{"t":"означава, че преминаването без спиране е забранено","ok":false,"i":null,"es":"significa que pasar sin detenerse está prohibido"},{"t":"указва, че движението се регулира от регулировчик","ok":false,"i":null,"es":"indica que el tráfico lo regula un agente"}],"f":6,"es":"La luz amarilla parpadeante: (2 correctas)","explain":"SIGNIFICA «¡ATENCIÓN!» Y ADVIERTE A LOS CONDUCTORES QUE SEAN ATENTOS Y PRECAVIDOS. Dos correctas.\n\nQUÉ VES. Un semáforo con la luz ÁMBAR encendida (la pregunta indica que es INTERMITENTE).\n\nÁMBAR INTERMITENTE = «¡ATENCIÓN!». El cruce no está regulado por el semáforo en ese momento: pasas con precaución, aplicando las señales de prioridad o la regla de la derecha.\n\n«PASAR SIN DETENERSE ESTÁ PROHIBIDO» es el cebo: confunde el intermitente con un STOP.\n\n«EL TRÁFICO LO REGULA UN AGENTE» no tiene relación con esta luz.\n\nCLAVE: ámbar intermitente = atención; ámbar fijo = atención, para. Ver Leyes → «El semáforo: cada luz tiene un nombre oficial»."},{"id":6072,"bg":"На двупосочен път, с по една пътна лента за движение във всяка посока, превозните средства трябва да се движат:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/123692.png","v":null,"a":[{"t":"в дясната пътна лента","ok":true,"i":null,"es":"en el carril derecho"},{"t":"в средната част на пътя","ok":false,"i":null,"es":"por el centro del camino"},{"t":"в лявата пътна лента","ok":false,"i":null,"es":"en el carril izquierdo"}],"f":6,"es":"En vía de doble sentido con un carril por sentido, los vehículos deben circular:","explain":"EN EL CARRIL DERECHO. Una sola correcta.\n\nQUÉ VES. Una carretera de DOBLE SENTIDO con un carril para cada sentido, separados por la línea central.\n\nCADA UNO POR SU DERECHA. En una vía de doble sentido con un carril por sentido, tu carril es el de la derecha; el izquierdo es el de los vehículos que vienen de frente.\n\n«POR EL CENTRO DEL CAMINO» es el cebo de quien se separa del borde por comodidad: invades parcialmente el carril contrario.\n\n«EN EL CARRIL IZQUIERDO» es circular en sentido contrario.\n\nCLAVE: doble sentido + un carril por sentido = siempre el derecho. Ver Leyes → «Carril: dónde debes circular»."},{"id":6098,"bg":"Кой от автомобилите се движи прaвилно по този път в населено място?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/63723.png","v":null,"a":[{"t":"само синият автомобил","ok":false,"i":null,"es":"solo el azul"},{"t":"само червеният автомобил","ok":false,"i":null,"es":"solo el rojo"},{"t":"и двата автомобила","ok":true,"i":null,"es":"ambos coches"}],"f":6,"explain":"LOS DOS. Una sola correcta.\n\nQUÉ VES. Una calle EN POBLACIÓN con dos carriles en tu sentido, marcados con flechas en el suelo, y una señal de máxima 60. El coche ROJO va por el carril IZQUIERDO y el AZUL por el DERECHO.\n\nEN POBLACIÓN, CON VARIOS CARRILES MARCADOS EN TU SENTIDO, PUEDES ELEGIR CARRIL. Ninguno de los dos tiene que ir obligatoriamente por la derecha: cada uno circula por un carril de su sentido.\n\n«SOLO EL AZUL» es el cebo de quien aplica la regla de fuera de población (siempre a la derecha).\n\n«SOLO EL ROJO» no tiene ninguna base.\n\nLAS DOS CONDICIONES DE ESTA EXCEPCIÓN: dos o más carriles en tu sentido y velocidad máxima permitida no superior a 80 km/h (aquí se cumplen; compárala con la 11686).\n\nCLAVE: población + varios carriles en tu sentido = libertad de carril. Compárala con la 6097 y la 6095. Ver Leyes → «Carril: dónde debes circular».","es":"¿Qué vehículo circula correctamente por esta vía en zona urbana?"},{"id":11686,"bg":"Кои от посочените условия е необходимо да бъдат налице за да може при движение в населено място водачът да използва най-удобната за него пътна лента?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/62875.png","v":null,"a":[{"t":"пътното платно да е с две и повече пътни ленти за движение в една посока","ok":true,"i":null,"es":"la calzada tiene dos o más carriles en una dirección"},{"t":"разрешената скорост за движение да е не по-голяма от 80 km/h","ok":true,"i":null,"es":"la velocidad máxima permitida es no superior a 80 km/h"},{"t":"пътното платно да е с не по-малко от три пътни ленти за движение в една посока","ok":false,"i":null,"es":"la calzada tiene no menos de tres carriles en una dirección"},{"t":"разрешената скорост за движение да е не по-голяма от 50 km/h","ok":false,"i":null,"es":"la velocidad máxima es no superior a 50 km/h"}],"f":6,"es":"¿Qué condiciones deben cumplirse para que, circulando en poblado, el conductor pueda usar el carril más cómodo para él? (2 correctas)","explain":"QUE LA CALZADA TENGA DOS O MÁS CARRILES EN UN SENTIDO Y QUE LA VELOCIDAD MÁXIMA PERMITIDA NO SUPERE 80 km/h. Dos correctas.\n\nQUÉ VES. Calle urbana con señales de máxima 60 y placas que indican TRES carriles en tu sentido.\n\nLA EXCEPCIÓN DE LA POBLACIÓN TIENE DOS CONDICIONES. En población puedes usar el carril que te resulte más cómodo (no solo el derecho) si: hay dos o más carriles en tu sentido y la velocidad máxima permitida no pasa de 80 km/h. Aquí se cumplen las dos.\n\n«NO MENOS DE TRES CARRILES» exige de más: bastan dos.\n\n«VELOCIDAD MÁXIMA NO SUPERIOR A 50 km/h» también exige de más: el límite de la condición es 80.\n\nCLAVE: población + 2 carriles o más en tu sentido + máximo ≤ 80 km/h = libertad de carril. Ver Leyes → «Carril: dónde debes circular»."},{"id":5808,"bg":"При тази ситуация водачът на червения автомобил може да се движи с разрешената максимална скорост:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/54069.png","v":null,"a":[{"t":"само при наличието на необходимите условия за безопасност","ok":true,"i":null,"es":"solo si hay condiciones de seguridad suficientes"},{"t":"във всички случаи","ok":false,"i":null,"es":"en todos los casos"},{"t":"само, ако има стаж като водач над 2 години","ok":false,"i":null,"es":"solo si lleva más de 2 años de permiso"}],"f":6,"es":"En esta situación el conductor del coche rojo puede circular a la velocidad máxima permitida:","explain":"SOLO SI HAY LAS CONDICIONES NECESARIAS DE SEGURIDAD. Una sola correcta.\n\nQUÉ VES. Carretera con árboles a ambos lados. A la derecha, señal de FIN DE LA LIMITACIÓN de 40 km/h. Delante, el coche ROJO.\n\nDESPUÉS DE LA SEÑAL, el rojo puede volver al límite general de la vía, pero:\n\nLA VELOCIDAD MÁXIMA ES UN TECHO, NO UN DERECHO. Puedes ir hasta ese límite solo si las condiciones (visibilidad, estado de la calzada, tráfico, peatones) lo permiten con seguridad. Si no, tienes que ir más despacio.\n\n«EN TODOS LOS CASOS» es el cebo: el máximo nunca es incondicional.\n\n«SOLO SI LLEVA MÁS DE 2 AÑOS DE PERMISO» es el cebo: aunque tengas mucha experiencia, el máximo solo se usa si las condiciones lo permiten. La antigüedad del permiso no convierte el máximo en un derecho.\n\nCLAVE: igual que la 5806: máximo = techo condicionado a la seguridad. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5836,"bg":"Коефициентът на сцепление на автомобилните гуми с пътя е показател за:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"взаимодействието между автомобилната гума и пътната настилка","ok":true,"i":null,"es":"la interacción entre el neumático y el pavimento"},{"t":"аеродинамичните качества на автомобила","ok":false,"i":null,"es":"las cualidades aerodinámicas del vehículo"},{"t":"ефективността на спирачната система на автомобила","ok":false,"i":null,"es":"la eficacia del sistema de frenos"}],"f":6,"es":"El coeficiente de rozamiento entre neumáticos y calzada es un indicador de:","explain":"El coeficiente de rozamiento mide la interacción neumático-pavimento (la adherencia disponible). No dice nada de la aerodinámica ni de la eficacia del sistema de frenos: unos frenos perfectos no frenan sin adherencia."},{"id":5846,"bg":"Как се изменя сцеплението на автомобилните гуми с пътя при мокра настилка в сравнение със суха?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"намалява","ok":true,"i":null,"es":"disminuye"},{"t":"увеличава се","ok":false,"i":null,"es":"aumenta"},{"t":"не се променя","ok":false,"i":null,"es":"no cambia"},{"t":"зависи от вида на автомобилната гума","ok":false,"i":null,"es":"depende del tipo de neumático"}],"f":6,"es":"¿Cómo varía el rozamiento de los neumáticos en pavimento mojado respecto al seco?","explain":"En mojado el rozamiento DISMINUYE siempre: el agua actúa como lubricante entre neumático y asfalto. Ocurre con cualquier tipo de neumático; por eso la distancia de frenado crece con lluvia."},{"id":5860,"bg":"Преди да намали значително скоростта на движение, водачът на МПС е задължен:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да се убеди, че няма да застраши останалите участници в движението","ok":true,"i":null,"es":"asegurarse de no poner en peligro a los demás participantes"},{"t":"да сигнализира с десен пътепоказател","ok":false,"i":null,"es":"señalizar con el intermitente derecho"},{"t":"да премине в най-дясната пътна лента","ok":false,"i":null,"es":"pasar al carril más a la derecha"},{"t":"да напусне платното за движение","ok":false,"i":null,"es":"abandonar la calzada"}],"f":6,"es":"Antes de reducir significativamente la velocidad, el conductor está obligado a:","explain":"Antes de reducir bruscamente la velocidad debes asegurarte de no crear peligro, sobre todo para el que te sigue. El intermitente derecho indica giro (no frenada) y no hay obligación de cambiar de carril ni salir de la calzada."},{"id":5886,"bg":"При тази ситуация няма ограничения и мога да увелича скоростта на движение.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57858.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":6,"es":"En esta situación no hay restricciones y puedo aumentar la velocidad. Esto es:","explain":"INCORRECTO.\n\nQUÉ VES. Carretera con señal de VÍA CON PRIORIDAD (rombo). A la DERECHA, un coche AMARILLO detenido junto al borde y, alrededor, varias PERSONAS, entre ellas un NIÑO junto a la señal. Más adelante, un coche rojo parado.\n\nHAY UNA RESTRICCIÓN, AUNQUE NO SEA UNA SEÑAL. Las personas junto a la calzada, y en especial el niño, pueden cruzar o bajar de la acera en cualquier momento. Eso obliga a moderar la velocidad, no a aumentarla.\n\n«CORRECTO» es el cebo: el rombo te da prioridad en los cruces, pero no te autoriza a acelerar junto a peatones.\n\nCLAVE: la prioridad no te exime de la prudencia. Compárala con la 5889 (la misma escena).\n\nMÉTODO: 1) ¿hay peatones, sobre todo niños, junto a la calzada? 2) si los hay, reduzco y voy listo para frenar. Ver Leyes → «Niños en la vía»."},{"id":5901,"bg":"Кое от изброените действия трябва да предприемете при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/58182.png","v":null,"a":[{"t":"да осигуря достатъчна странична дистанция","ok":true,"i":null,"es":"garantizar distancia lateral suficiente"},{"t":"да бъда внимателен и предпазлив","ok":true,"i":null,"es":"ser atento y precavido"},{"t":"да подам звуков сигнал","ok":false,"i":null,"es":"tocar el claxon"},{"t":"незабавно да спра","ok":false,"i":null,"es":"frenar de inmediato"}],"f":6,"es":"¿Qué acciones debes tomar en esta situación? (2 correctas)","explain":"GARANTIZAR UNA DISTANCIA LATERAL SUFICIENTE Y SER ATENTO Y PRECAVIDO. Dos correctas.\n\nQUÉ VES. La misma escena que la 5899: dos CICLISTAS jóvenes por el lado izquierdo de la calzada, uno de ellos hacia el centro.\n\nAL CRUZARTE CON CICLISTAS, ESPACIO Y ATENCIÓN. Les dejas una distancia lateral suficiente para que un pequeño desvío no termine en choque, y vas atento a lo que hagan.\n\n«TOCAR EL CLAXON» puede asustarlos.\n\n«FRENAR DE INMEDIATO» es el cebo exagerado: no hay nada que obligue a detenerse en seco, y una frenada brusca sin motivo puede provocar un alcance.\n\nCLAVE: con ciclistas, la distancia lateral es la medida clave. Ver Leyes → «Carril: dónde debes circular»."},{"id":6700,"bg":"Когато поради вида на превозвания товар, центърът на тежестта на автомобила е по-висок от конструктивния, водачът трябва да намали скоростта:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"преди навлизане в завой","ok":true,"i":null,"es":"antes de entrar en una curva"},{"t":"при неравности на платното за движение","ok":true,"i":null,"es":"con irregularidades en el pavimento"},{"t":"при силен страничен вятър","ok":true,"i":null,"es":"con viento lateral fuerte"},{"t":"при движение по стръмен наклон при изкачване","ok":false,"i":null,"es":"en subida pronunciada"}],"f":6,"es":"Con el centro de gravedad más alto de lo normal, mayor riesgo de vuelco hay: (3 correctas)","explain":"Con el centro de gravedad alto, el vuelco amenaza donde hay fuerzas LATERALES: al entrar en curva, sobre irregularidades del pavimento y con viento lateral fuerte. Una subida pronunciada recta no genera fuerza lateral."},{"id":11701,"bg":"Когато няма други ограничения, водачът на състав от ППС от категория ВЕ при движение в населено място не трябва да превишава:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"50 km/h","ok":true,"i":null,"es":"50 km/h"},{"t":"60 km/h","ok":false,"i":null,"es":"60 km/h"},{"t":"40 km/h","ok":false,"i":null,"es":"40 km/h"},{"t":"55 km/h","ok":false,"i":null,"es":"55 km/h"}],"f":6,"es":"Sin otras restricciones, el conductor de convoy categoría BE en zona urbana no debe superar:","explain":"50 km/h: el límite urbano general no cambia por llevar remolque. Para un conjunto categoría BE en población rige el mismo máximo que para el resto de vehículos de motor."},{"id":11704,"bg":"Когато няма други ограничения, водачът на товарен автомобил с допустима максимална маса 3 t., при движение в населено място, не трябва да превишава:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"50 km/h","ok":true,"i":null,"es":"50 km/h"},{"t":"40 km/h","ok":false,"i":null,"es":"40 km/h"},{"t":"55 km/h","ok":false,"i":null,"es":"55 km/h"},{"t":"60 km/h","ok":false,"i":null,"es":"60 km/h"}],"f":6,"es":"Sin otras restricciones, el conductor de camión de 3 t en zona urbana no debe superar:","explain":"50 km/h: en población el límite general es 50 km/h para todos los vehículos de motor, incluido un camión de 3 t, salvo señalización distinta."},{"id":12026,"bg":"Какво трябва да направите при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":11,"a":[{"t":"да увелича скоростта","ok":false,"i":null,"es":"acelerar"},{"t":"да спра аварийно/рязко","ok":true,"i":null,"es":"freno de emergencia"},{"t":"да продължа движението си, като подам звуков сигнал","ok":false,"i":null,"es":"continúo tocando el claxon"}],"f":6,"es":"¿Qué debes hacer en esta situación?"},{"id":6227,"bg":"Преди да се включи в движението, водачът на ППС е длъжен:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да се убеди, че няма да създаде опасност за другите участници в движението","ok":true,"i":null,"es":"asegurarse de no crear peligro para los demás"},{"t":"да подаде сигнал със съответния пътепоказател","ok":true,"i":null,"es":"activar el intermitente"},{"t":"да подаде звуков или светлинен сигнал с фаровете, с което да си осигури предимство","ok":false,"i":null,"es":"dar señal acústica o de luces para asegurarse prioridad"},{"t":"да изчака сигнал от другите водачи, че може да потегли","ok":false,"i":null,"es":"esperar señal de los demás conductores"}],"f":6,"es":"Antes de incorporarse al tráfico, el conductor está obligado a: (2 correctas)","explain":"Para incorporarte al tráfico: comprueba que no creas peligro para nadie y señaliza con el intermitente. La prioridad no se pide con el claxon o las luces: los que circulan no están obligados a cederte el paso."},{"id":6236,"bg":"Кой от водачите е с предимство при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/69768.png","v":null,"a":[{"t":"водачът на товарния автомобил","ok":true,"i":null,"es":"el conductor del camión"},{"t":"водачът на лекия автомобил","ok":false,"i":null,"es":"el conductor del turismo"},{"t":"водачът на автомобила, който пръв достигне до препятствието","ok":false,"i":null,"es":"el conductor que llegue primero al obstáculo"}],"f":6,"es":"¿Qué conductor tiene prioridad en esta situación?","explain":"EL CONDUCTOR DEL CAMIÓN. Una sola correcta.\n\nQUÉ VES. La misma escena que la 6235: un OBSTÁCULO en el carril del turismo AZUL, que lleva el intermitente izquierdo para rodearlo, y un CAMIÓN rojo que viene de frente por su carril.\n\nEL CAMIÓN TIENE PREFERENCIA porque circula por su carril, que está libre. El azul tiene el obstáculo en su lado y, para rodearlo, invadiría el carril del camión.\n\n«EL TURISMO» es el cebo de quien piensa que el que señaliza o el más pequeño tiene preferencia.\n\n«EL QUE LLEGUE PRIMERO AL OBSTÁCULO» es una regla inventada: aquí no hay carrera.\n\nCLAVE: el obstáculo decide: quien lo tiene en su carril, cede. Ver Leyes → «Carril: dónde debes circular»."},{"id":6240,"bg":"Когато на кръстовище пътните ленти не са обозначени с пътна маркировка за движение в съответна посока, завиването надясно е разрешено да се извършва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"от най-дясната част на платното за движение","ok":true,"i":null,"es":"desde la parte más a la derecha de la calzada"},{"t":"от която и да е част на платното за движение, ако радиусът на завиване на автомобила е по-голям от радиуса на завоя","ok":true,"i":null,"es":"desde cualquier posición si el radio de giro lo requiere"},{"t":"във всички случаи от най-удобната за водача пътна лента","ok":false,"i":null,"es":"desde el carril más cómodo en todos los casos"}],"f":6,"es":"Cuando no hay marcas de carril en intersección, girar a la derecha se hace: (2 correctas)","explain":"Sin marcas viales, el giro a la derecha se hace desde la parte más a la derecha de la calzada; se admite otra posición solo cuando el radio de giro del vehículo lo exige (vehículos largos). Nunca 'desde donde sea cómodo'."},{"id":6242,"bg":"Когато на кръстовище пътните ленти са обозначени за движение в съответна посока, завиването надясно може да се извърши:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"от пътна лента обозначена за завиване надясно","ok":true,"i":null,"es":"desde carril marcado para girar a la derecha"},{"t":"от която и да е пътна лента, ако радиусът на завиване на автомобила е по-голям от радиуса на завоя","ok":true,"i":null,"es":"desde cualquier carril si el radio de giro lo requiere"},{"t":"от най-дясната пътна лента по посока на движението","ok":true,"i":null,"es":"desde el carril más a la derecha en el sentido de marcha"},{"t":"във всички случаи от най-удобната за водача пътна лента","ok":false,"i":null,"es":"desde el carril más cómodo en todos los casos"}],"f":6,"es":"Cuando los carriles están marcados, girar a la derecha puede hacerse: (3 correctas)","explain":"Con carriles marcados puedes girar a la derecha desde: el carril con flecha a la derecha, el carril más a la derecha, u otro carril si el radio de giro del vehículo lo exige. La comodidad del conductor no es criterio legal."},{"id":6259,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/69985.png","v":null,"a":[{"t":"трябва да пропусна пешеходеца","ok":true,"i":null,"es":"debo dejar pasar al peatón"},{"t":"мога да премина преди пешеходеца, ако той се движи бавно","ok":false,"i":null,"es":"puedo pasar antes si camina despacio"},{"t":"не съм задължен да пропусна пешеходеца, защото пешеходната пътека не е маркирана","ok":false,"i":null,"es":"no estoy obligado porque el paso no está marcado"}],"f":6,"es":"En esta situación:","explain":"DEBO DEJAR PASAR AL PEATÓN. Una sola correcta.\n\nQUÉ VES. Llevas el intermitente IZQUIERDO y vas a girar a la izquierda (flecha). En la calle a la que vas a entrar, un PEATÓN está cruzando. No hay paso de peatones pintado.\n\nAL GIRAR, CEDES A LOS PEATONES QUE CRUZAN LA CALLE A LA QUE ENTRAS, haya o no paso pintado.\n\n«PUEDO PASAR ANTES SI CAMINA DESPACIO» es el cebo del cálculo: no se decide por la velocidad del peatón.\n\n«NO ESTOY OBLIGADO PORQUE EL PASO NO ESTÁ MARCADO» es el cebo principal: la obligación al girar no depende de la pintura.\n\nCLAVE: giro (a cualquier lado) + peatón cruzando la calle de destino = cedo. Compárala con la 6254 (giro a la derecha). Ver Leyes → «Paso de peatones»."},{"id":6348,"bg":"Когато е разрешено едновременното им преминаване, водачът на нерелсово ППС е длъжен да пропусне релсовото:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"винаги, независимо от местоположението му","ok":true,"i":null,"es":"siempre, independientemente de su posición"},{"t":"винаги, независимо от посоката му на движение","ok":true,"i":null,"es":"siempre, independientemente de su dirección"},{"t":"само когато релсовото ППС се намира от дясната му страна","ok":false,"i":null,"es":"solo cuando está a su derecha"},{"t":"само в случаите, когато релсовото превозно средство не завива","ok":false,"i":null,"es":"solo cuando no gira"}],"f":6,"es":"Cuando está permitido el paso simultáneo, el conductor no ferroviario debe ceder al ferroviario: (2 correctas)","explain":"Cuando el paso simultáneo está permitido, el vehículo no ferroviario cede SIEMPRE al ferroviario: da igual su posición (derecha/izquierda) y da igual su dirección. El tren y el tranvía no pueden esquivar."},{"id":6368,"bg":"Завиването в обратна посока е забранено, когато видимостта е намалена под:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"50 м","ok":true,"i":null,"es":"50 m"},{"t":"250 м","ok":false,"i":null,"es":"250 m"},{"t":"150 м","ok":false,"i":null,"es":"150 m"},{"t":"100 м","ok":false,"i":null,"es":"100 m"}],"f":6,"es":"El cambio de sentido está prohibido cuando la visibilidad es inferior a:","explain":"50 m: es el umbral legal. Con visibilidad inferior a 50 metros el cambio de sentido está prohibido, porque el tráfico que aparezca no tendría distancia para reaccionar."},{"id":6375,"bg":"При тази ситуация разрешено ли е да завиете в обратна посока?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71210.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":6,"es":"¿Está permitido dar la vuelta en esta situación?","explain":"NO.\n\nQUÉ VES. Llevas el intermitente IZQUIERDO y la flecha dibuja un cambio de sentido. El semáforo está en VERDE y encima hay una señal circular AZUL con flecha de giro a la IZQUIERDA: DIRECCIÓN OBLIGATORIA A LA IZQUIERDA.\n\nLA SEÑAL OBLIGATORIA SOLO PERMITE LO QUE DIBUJA. Te obliga a girar a la izquierda; dar la vuelta (cambio de sentido) es otra maniobra, y en el examen búlgaro esta señal no la autoriza.\n\n«SÍ» es el cebo de quien piensa que, si se puede girar a la izquierda, también se puede dar la vuelta.\n\nCLAVE (regla del banco que conviene memorizar): señal AZUL de giro obligatorio a la izquierda = NO se puede dar la vuelta; señal ROJA de prohibido girar a la izquierda = SÍ se puede dar la vuelta (compárala con la 6377). Ver Leyes → «Dónde está prohibido cambiar de sentido»."},{"id":6376,"bg":"При тази ситуация разрешено ли е да завиете в обратна посока?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71243.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":6,"es":"¿Está permitido dar la vuelta en esta situación?","explain":"NO.\n\nQUÉ VES. El coche ROJO lleva el intermitente IZQUIERDO y la flecha dibuja un cambio de sentido. A la derecha hay una señal circular AZUL con flecha de giro a la IZQUIERDA: DIRECCIÓN OBLIGATORIA A LA IZQUIERDA.\n\nLA SEÑAL OBLIGATORIA SOLO PERMITE GIRAR A LA IZQUIERDA. Dar la vuelta no está incluido.\n\n«SÍ» es el cebo de quien confunde «girar a la izquierda» con «dar la vuelta».\n\nCLAVE: es la misma regla que la 6375. Azul obligatoria a la izquierda = sin cambio de sentido. Ver Leyes → «Dónde está prohibido cambiar de sentido»."},{"id":6386,"bg":"При тази ситуация червеният автомобил е с предимство за преминаване през стеснения участък от пътя.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71375.png","v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcto"},{"t":"неправилно","ok":false,"i":null,"es":"INCORRECTO"}],"f":6,"es":"En esta situación el coche rojo tiene prioridad para pasar por el tramo estrecho. Esto es:","explain":"CORRECTO.\n\nQUÉ VES. Un puente ESTRECHO donde no caben dos vehículos. A la derecha hay una señal circular de borde ROJO con una flecha NEGRA hacia abajo y una ROJA hacia arriba: PREFERENCIA PARA LOS QUE VIENEN DE FRENTE. Al otro lado del puente viene un coche ROJO.\n\nLA SEÑAL TE DICE QUE CEDES TÚ. La flecha roja (la tuya) es la que cede; la negra (la del que viene de frente) tiene preferencia. El rojo pasa primero.\n\n«INCORRECTO» es el cebo de quien confunde esta señal (círculo de borde rojo, cedes tú) con la cuadrada azul (preferencia tuya).\n\nCLAVE: círculo rojo con flechas = cedo; cuadrado azul con flechas = tengo preferencia. Compárala con la 6387. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6401,"bg":"След този пътен знак на водачите на товарни автомобили с допустима максимална маса над 3,5 т е разрешено да изпреварват:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67956.png","v":null,"a":[{"t":"мотоциклети без кош","ok":true,"i":null,"es":"motos sin sidecar"},{"t":"мотопеди","ok":true,"i":null,"es":"ciclomotores"},{"t":"леки автомобили","ok":false,"i":null,"es":"turismos"},{"t":"автобуси","ok":false,"i":null,"es":"autobuses"}],"f":6,"es":"Después de esta señal, los conductores de camiones con MMA >3.5t PUEDEN adelantar a: (2 correctas)","explain":"LAS MOTOS SIN SIDECAR Y LOS CICLOMOTORES. Dos correctas.\n\nLA SEÑAL. Círculo de borde ROJO con un CAMIÓN rojo y un coche negro: PROHIBIDO ADELANTAR PARA LOS CAMIONES de más de 3,5 t.\n\nQUÉ PROHÍBE. A los camiones de más de 3,5 t, adelantar a vehículos de motor. Igual que en la señal general, las motos sin sidecar y los ciclomotores quedan fuera: a ellos sí pueden adelantarlos.\n\n«TURISMOS» y «AUTOBUSES» son vehículos de motor: el camión no puede adelantarlos bajo esta señal.\n\nCLAVE: esta señal solo afecta a los camiones pesados; a un turismo como el tuyo no le prohíbe nada. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6405,"bg":"След този пътен знак разрешено ли е на водачите на товарни автомобили да изпреварват други автомобили?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68072.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":6,"es":"¿Está permitido a los conductores de camiones adelantar otros vehículos después de esta señal?","explain":"SÍ.\n\nLA SEÑAL. Círculo blanco con borde negro, con los dos coches dibujados en gris/negro y TACHADOS por barras diagonales: FIN DE LA PROHIBICIÓN DE ADELANTAR.\n\nLAS BARRAS SIGNIFICAN «FIN». Se acaba la prohibición general de adelantar, que afectaba a todos los conductores, también a los de camiones. A partir de aquí pueden adelantar respetando las normas generales.\n\n«NO» es el cebo de quien confunde esta señal con la de prohibido adelantar (borde rojo, sin barras).\n\nCLAVE: blanco y negro con barras = fin de la restricción. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6416,"bg":"Изпреварването на МПС, с изключение на мотопеди и мотоциклети без кош, е забранено:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"при намалена видимост, когато разстоянието е по-малко от необходимото за изпреварване","ok":true,"i":null,"es":"con visibilidad reducida y distancia insuficiente"},{"t":"пред и върху сигнализирана пешеходна пътека","ok":true,"i":null,"es":"la visibilidad es limitada"},{"t":"на надлез","ok":false,"i":null,"es":"en paso elevado"},{"t":"при движение през нощта","ok":false,"i":null,"es":"de noche"}],"f":6,"es":"El adelantamiento está PROHIBIDO: (2 correctas)","explain":"Prohibido adelantar cuando la visibilidad es reducida (niebla, lluvia) o limitada (curva, cambio de rasante) y la distancia visible no basta para completar la maniobra. Ni el paso elevado ni la noche lo prohíben por sí mismos."},{"id":6420,"bg":"Разрешено ли е при изпреварване да използвате превключването на светлините като допълнителен сигнал?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":6,"es":"¿Está permitido usar el parpadeo de luces como señal adicional al adelantar?","explain":"Sí: el parpadeo de las luces de carretera es una señal adicional válida para avisar del adelantamiento (especialmente útil de día y fuera de población), junto con el intermitente."},{"id":6425,"bg":"При изпреварване се преминава от лявата страна на изпреварваното ППС:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcto"},{"t":"неправилно","ok":false,"i":null,"es":"INCORRECTO"}],"f":6,"es":"Al adelantar se pasa por el lado IZQUIERDO del vehículo adelantado. Esto es:","explain":"Correcto: la regla general es adelantar por el lado IZQUIERDO del vehículo adelantado. Por la derecha solo se rebasa a quien ha señalizado y se ha posicionado para girar a la izquierda."},{"id":6447,"bg":"При тази ситуация разрешено ли е да преминете по трамвайните линии, за да изпреварите товарния автомобил?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/128523.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":6,"es":"En esta situación ¿está permitido circular por las vías del tranvía para adelantar al camión?"},{"id":9829,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/270041864.png","v":null,"a":[{"t":"да пропусна пешеходеца","ok":true,"i":null,"es":"ceder el paso al peatón"},{"t":"да премина преди пешеходеца","ok":false,"i":null,"es":"pasar antes que el peatón"}],"f":6,"es":"En esta situación debo:","explain":"CEDER EL PASO AL PEATÓN. Una sola correcta.\n\nQUÉ VES. Llevas el intermitente DERECHO y vas a girar a la derecha (flecha). En la calle a la que vas a entrar, un PEATÓN está cruzando.\n\nAL GIRAR, CEDES A LOS PEATONES QUE CRUZAN LA CALLE A LA QUE ENTRAS, haya o no paso pintado.\n\n«PASAR ANTES QUE EL PEATÓN» es el cebo de quien calcula que le da tiempo.\n\nCLAVE: es la misma regla que la 6254. Ver Leyes → «Paso de peatones»."},{"id":12038,"bg":"Какъв е правилният начин на действие при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":27,"a":[{"t":"да остана в средата на заеманата лента","ok":false,"i":null,"es":"me quedo en el centro del carril"},{"t":"да намаля скоростта","ok":true,"i":null,"es":"reducir la velocidad"},{"t":"да премина възможно най-вдясно","ok":true,"i":null,"es":"me desplazo todo lo posible a la derecha"}],"f":6,"es":"¿Cuál es la actuación correcta en esta situación? (2 correctas)"},{"id":12041,"bg":"Какво трябва да направите при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":33,"a":[{"t":"да увелича скоростта","ok":false,"i":null,"es":"acelerar"},{"t":"да се движа възможно най-вдясно","ok":true,"i":null,"es":"circulo todo lo posible a la derecha"},{"t":"да намаля скоростта","ok":true,"i":null,"es":"reducir la velocidad"}],"f":6,"es":"¿Qué debes hacer en esta situación? (2 correctas)"},{"id":5916,"bg":"При тази ситуация разрешено ли е да завиете надясно?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/48258.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":6,"es":"En esta situación ¿está permitido girar a la derecha?","explain":"NO.\n\nQUÉ VES. Llevas el intermitente DERECHO y quieres girar a la derecha (flecha). El semáforo está en VERDE, pero encima hay una señal circular AZUL con una flecha HACIA ARRIBA: DIRECCIÓN OBLIGATORIA RECTO.\n\nEL VERDE NO ANULA LA SEÑAL DE DIRECCIÓN OBLIGATORIA. El semáforo te deja pasar, pero solo en la dirección que permite la señal: recto. Girar a la derecha está prohibido.\n\n«SÍ» es el cebo de quien solo mira el verde.\n\nCLAVE: el semáforo decide CUÁNDO pasas; las señales de dirección obligatoria deciden HACIA DÓNDE.\n\nMÉTODO: 1) ¿qué dice el semáforo? 2) ¿hay señal de dirección obligatoria o de prohibición de giro? 3) solo puedo ir hacia donde lo permitan los dos. Ver Leyes → «Quién manda sobre quién»."},{"id":6342,"bg":"На водача е забранено да навлиза на железопътния прелез:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"когато бариерите са спуснати и започват да се вдигат","ok":true,"i":null,"es":"cuando las barreras están bajadas y empiezan a subir"},{"t":"когато е включена звуковата сигнализация","ok":true,"i":null,"es":"cuando está activa la señal acústica"},{"t":"при мигаща червена светлина на светофара","ok":true,"i":null,"es":"con luz roja parpadeante del semáforo"},{"t":"когато светофарната уредба подава сигнал от бавно мигащата светлина с луннобял цвят","ok":false,"i":null,"es":"cuando el semáforo emite luz blanca lenta parpadeante"}],"f":6,"explain":"Prohibido entrar: con las barreras bajadas incluso cuando ya empiezan a SUBIR (espera a que estén arriba del todo), con la señal acústica activa y con luz roja parpadeante. La luz BLANCA lenta parpadeante significa lo contrario: paso permitido.","es":"Al conductor le está PROHIBIDO entrar al paso a nivel: (3 correctas)"},{"id":6347,"bg":"На водача е забранено да навлиза на железопътния прелез:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"преди да се е убедил, че към прелеза не се приближава влак","ok":true,"i":null,"es":"antes de asegurarse de que no se aproxima ningún tren"},{"t":"когато е включена звуковата сигнализация","ok":true,"i":null,"es":"cuando está activa la señal acústica"},{"t":"когато светофарната уредба подава сигнал от бавно мигащата светлина с луннобял цвят","ok":false,"i":null,"es":"cuando el semáforo emite luz blanca lenta parpadeante"},{"t":"когато от другата страна на прелеза няма достатъчно място за продължаване на движението","ok":true,"i":null,"es":"cuando al otro lado no hay espacio suficiente para continuar"}],"f":6,"es":"Al conductor le está PROHIBIDO entrar al paso a nivel: (3 correctas)","explain":"Prohibido entrar: sin haber comprobado que no viene tren, con la señal acústica activa, y sin espacio libre al otro lado. La luz BLANCA lenta intermitente del semáforo ferroviario significa paso PERMITIDO, por eso esa opción es falsa."},{"id":6467,"bg":"Как трябва да постъпите при тази ситуация, ако водачът на червения автомобил, който трябва да ви пропусне, не показва с действията си, че ще спре?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53360.png","v":null,"a":[{"t":"трябва да намаля скоростта","ok":true,"i":null,"es":"debo reducir velocidad"},{"t":"трябва да се движа с готовност за спиране","ok":true,"i":null,"es":"debo circular listo para frenar"},{"t":"не съм длъжен да се съобразявам с него, защото съм с предимство","ok":false,"i":null,"es":"no tengo que considerarlo porque tengo prioridad"}],"f":6,"es":"¿Cómo debes actuar en esta situación si el conductor del coche rojo, que debe cederte el paso, no muestra con sus acciones que vaya a parar? (2 correctas)","explain":"DEBO REDUCIR LA VELOCIDAD Y DEBO CIRCULAR LISTO PARA FRENAR. Dos correctas.\n\nQUÉ VES. Un cruce. Vas RECTO. Un coche ROJO, con el intermitente puesto, va a girar y cruzar tu trayectoria; la pregunta dice que debe cederte el paso, pero no da señales de detenerse.\n\nTENER PREFERENCIA NO TE PROTEGE DEL CHOQUE. Si el que debe cederte no da señales de ir a detenerse, reduces y vas listo para frenar. Es la obligación de evitar el accidente aunque la culpa fuera del otro.\n\n«NO TENGO QUE CONSIDERARLO PORQUE TENGO PRIORIDAD / VOY RECTO» es el cebo: tener razón no sirve de nada después de un choque.\n\nCLAVE: si el otro no frena, frenas tú. Compárala con la 6465 y la 6471. Ver Leyes → «Adelantar y colocarse antes de una maniobra»."},{"id":6478,"bg":"В тунел този знак с допълнителна табела сигнализира:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/84174.png","v":null,"a":[{"t":"място за принудително спиране","ok":true,"i":null,"es":"lugar de parada forzosa"},{"t":"място за паркиране с телефон и пожарогасител","ok":false,"i":null,"es":"lugar de aparcamiento con teléfono y extintor"}],"f":6,"es":"En un túnel esta señal con tablilla indica:","explain":"LUGAR DE PARADA FORZOSA. Una sola correcta.\n\nLA SEÑAL. Cuadrado AZUL que dibuja un ENSANCHAMIENTO lateral de la calzada, con una placa debajo: EXTINTOR y TELÉFONO S.O.S.\n\nEN UN TÚNEL, ESE ENSANCHAMIENTO ES PARA EMERGENCIAS. Sirve para detener el vehículo si se avería o en caso de incidente, y tiene a mano extintor y teléfono de emergencia.\n\n«APARCAMIENTO CON TELÉFONO Y EXTINTOR» es el cebo: no se puede aparcar en un túnel; ese hueco es solo para paradas forzosas.\n\nCLAVE: en un túnel, ensanchamiento + S.O.S. = parada de emergencia, nunca aparcamiento. Compárala con la 6481 y el vídeo 12060. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6481,"bg":"В тунел този знак сигнализира:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/84141.png","v":null,"a":[{"t":"уширение на пътното платно с аварийна станция","ok":true,"i":null,"es":"ensanchamiento de la calzada con estación de emergencia"},{"t":"допълнителна пътна лента за принудително спиране","ok":false,"i":null,"es":"carril adicional de parada forzosa"},{"t":"място за паркиране","ok":false,"i":null,"es":"zona de aparcamiento"}],"f":6,"es":"En un túnel esta señal indica:","explain":"ENSANCHAMIENTO DE LA CALZADA CON ESTACIÓN DE EMERGENCIA. Una sola correcta.\n\nLA SEÑAL. Cuadrado AZUL con la calzada, una línea discontinua y un ENSANCHAMIENTO lateral con las letras «S O S».\n\nQUÉ INDICA. Un ensanchamiento donde hay una estación de emergencia (teléfono S.O.S.). Es un espacio puntual para emergencias.\n\n«CARRIL ADICIONAL DE PARADA FORZOSA» es el cebo: no es un carril continuo, es un ensanchamiento en un punto.\n\n«ZONA DE APARCAMIENTO» es el otro cebo: en un túnel no se aparca.\n\nCLAVE: S.O.S. en la señal = emergencia, no aparcamiento. Compárala con la 6478. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6485,"bg":"При тази ситуация трябва задължително да завия наляво.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/54487.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":6,"explain":"INCORRECTO.\n\nQUÉ VES. En el cruce hay un AGENTE que te muestra su COSTADO con el brazo extendido. A la derecha hay un semáforo en verde y una señal de vía con prioridad. No llevas ningún intermitente.\n\nEL AGENTE DE COSTADO TE PERMITE SEGUIR RECTO O GIRAR A LA DERECHA. No te obliga a girar a la izquierda; de hecho, con esta posición el giro a la izquierda no está permitido.\n\n«CORRECTO» es el cebo de quien interpreta el brazo extendido como una flecha que indica hacia dónde ir.\n\nCLAVE: el brazo del agente no es una flecha; lo que cuenta es qué parte de su cuerpo te muestra. Ver Leyes → «Quién manda sobre quién».","es":"En esta situación estoy obligado a girar a la izquierda. Esto es:"},{"id":6498,"bg":"Извършването на коя от изброените маневри е забранено в тунел?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"движение назад","ok":true,"i":null,"es":"marcha atrás"},{"t":"завиване в обратна посока","ok":true,"i":null,"es":"cambio de sentido"},{"t":"заобикаляне","ok":false,"i":null,"es":"rodear un obstáculo"},{"t":"изпреварване","ok":false,"i":null,"es":"adelantar"}],"f":6,"es":"¿Qué maniobras están PROHIBIDAS en un túnel? (2 correctas)","explain":"En túnel están prohibidas la marcha atrás y el cambio de sentido (maniobras contra el flujo en espacio cerrado). Adelantar o rodear un obstáculo no están prohibidos con carácter general en túneles."},{"id":6530,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57673.png","v":null,"a":[{"t":"да пропусна червения автомобил","ok":true,"i":null,"es":"dejar pasar al rojo"},{"t":"да премина преди синия автомобил","ok":true,"i":null,"es":"pasar antes que el coche azul"},{"t":"да премина преди червения автомобил","ok":false,"i":null,"es":"pasar antes que el coche rojo"},{"t":"да пропусна синия автомобил","ok":false,"i":null,"es":"dejar pasar al azul"}],"f":6,"es":"En esta situación debo: (2 correctas)","explain":"CEDER AL COCHE ROJO Y PASAR ANTES QUE EL AZUL. Dos correctas.\n\nQUÉ VES. En tu poste hay un CEDA EL PASO. Vas RECTO. Por la IZQUIERDA, por la vía principal, llega un coche ROJO. De frente, por la otra vía secundaria, viene un coche AZUL con el intermitente, que va a girar a SU izquierda cruzando tu trayectoria.\n\nAL ROJO LE CEDES: va por la vía principal y tú llevas ceda el paso, aunque venga por tu izquierda.\n\nAL AZUL LE PASAS TÚ: también viene por una vía secundaria, así que la señal no os separa; entre vosotros, el que gira a la izquierda (el azul) cede al que va recto (tú).\n\n«CEDER AL AZUL» y «PASAR ANTES QUE EL ROJO» son las respuestas al revés.\n\nCLAVE: primero la señal (cedo a los de la principal); entre secundarias, las reglas de giro y de la derecha. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). El tranvía, en general, pasa antes que los coches. Ver Leyes → «Vía con prioridad»."},{"id":6534,"bg":"Задължени ли сте при тази ситуация да пропуснете синия автомобил?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57946.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":6,"es":"¿Está obligado a ceder el paso al coche azul?","explain":"SÍ.\n\nQUÉ VES. En tu poste hay una señal de VÍA CON PRIORIDAD (sin panel) y, debajo, una señal azul de DIRECCIÓN OBLIGATORIA A LA IZQUIERDA. Llevas el intermitente izquierdo. De frente viene un coche AZUL. Por la derecha, una furgoneta roja.\n\nEL AZUL VIENE DE FRENTE POR TU MISMA VÍA PREFERENTE, así que el rombo no os separa. Entre vosotros, el que gira a la izquierda (tú) cede al que viene de frente.\n\n«NO» es el cebo de quien cree que el rombo, o la señal que le obliga a girar, le da preferencia sobre todos.\n\nCLAVE: la señal azul te obliga a girar a la izquierda, pero no te da preferencia para hacerlo. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). El tranvía, en general, pasa antes que los coches. Ver Leyes → «Vía con prioridad»."},{"id":6541,"bg":"При тази ситуация трябва да пропусна:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/66300.png","v":null,"a":[{"t":"само синия автомобил","ok":false,"i":null,"es":"solo al coche azul"},{"t":"само червения автомобил","ok":false,"i":null,"es":"solo al coche rojo"},{"t":"и двата автомобила","ok":true,"i":null,"es":"a los dos coches"}],"f":6,"es":"En esta situación debo ceder el paso:","explain":"A LOS DOS. Una sola correcta.\n\nQUÉ VES. Vas RECTO. En tu poste hay un CEDA EL PASO con PANEL: el trazo GRUESO baja desde ARRIBA y gira a la IZQUIERDA; los finos son el de la derecha y el de abajo (el tuyo). De frente, por la rama gruesa, viene un coche ROJO con el intermitente. Por la DERECHA, por la rama fina, llega un coche AZUL con el intermitente.\n\nAL ROJO, POR LA SEÑAL: va por la preferente y tú llevas ceda el paso.\n\nAL AZUL, POR LA DERECHA: también viene por una secundaria, así que la señal no os separa, y te llega por la derecha.\n\n«SOLO AL AZUL» y «SOLO AL ROJO» olvidan una de las dos reglas.\n\nCLAVE: primero separa ramas gruesas y finas; entre los de la fina, la derecha. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). Ver Leyes → «Cuando la prioritaria cambia de dirección»."},{"id":6575,"bg":"При тази ситуация преминавам с предимство, защото се движа направо.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68039.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":6,"explain":"INCORRECTO.\n\nQUÉ VES. Un cruce SIN SEÑALES. Vas RECTO. Por la DERECHA llega un CAMIÓN con el intermitente izquierdo. De frente viene un coche rojo que gira.\n\nIR RECTO NO DA PRIORIDAD. Frente a un vehículo que llega por un lateral decide la regla de la derecha, gire él hacia donde gire. El camión te llega por la derecha: pasa antes que tú.\n\n«CORRECTO» es el cebo: «porque voy recto» es una razón falsa.\n\nCLAVE: compárala con la 6566. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). Ver Leyes → «Regla de la derecha».","es":"En esta situación tengo prioridad porque voy recto. Esto es:"},{"id":11588,"bg":"Задължен ли е водачът да изключи двигателя при принудително спиране в тунел?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да, когато началото на тунела е обозначено с пътен знак","ok":true,"i":null,"es":"sí, cuando el inicio del túnel está señalizado"},{"t":"да, когато спирането не е кратковременно","ok":true,"i":null,"es":"sí, cuando la parada no es breve"},{"t":"да, независимо от причината за спирането и продължителността на спирането","ok":false,"i":null,"es":"sí, independientemente de la causa y duración"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":6,"es":"¿Está obligado a apagar el motor al parar forzosamente en túnel señalizado? (2 correctas)","explain":"Sí, en dos supuestos: cuando el inicio del túnel está señalizado con señal de tráfico y cuando la parada no va a ser breve. No es 'siempre' (parada breve en túnel no señalizado) ni 'nunca'."},{"id":5356,"bg":"Автомобилният път е предназначен за движение на:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"автомобили","ok":true,"i":null,"es":"automóviles"},{"t":"мотоциклети","ok":true,"i":null,"es":"motocicletas"},{"t":"МПС с изключение на самоходните машини","ok":false,"i":null,"es":"vehículos de motor, excepto las máquinas autopropulsadas"},{"t":"МПС с изключение на мотопедите","ok":false,"i":null,"es":"vehículos de motor, excepto los ciclomotores"}],"f":6,"es":"El camino de automóviles está destinado a la circulación de: (2 correctas)","explain":"La vía rápida (camino de automóviles) admite automóviles y motocicletas: vehículos capaces de mantener velocidad alta. Las opciones con 'excepto' están mal formuladas respecto a la definición legal, que se enuncia en positivo."},{"id":5390,"bg":"На автомагистрала е забранено движението на:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"мотопеди","ok":true,"i":null,"es":"ciclomotores"},{"t":"трактори","ok":true,"i":null,"es":"tractores"},{"t":"леки автомобили с ремаркета","ok":false,"i":null,"es":"turismos con remolque"},{"t":"велосипеди","ok":true,"i":null,"es":"bicicletas"}],"f":6,"es":"En autopista esta prohibida la circulación de: (3 correctas)","explain":"En autopista no circulan ciclomotores, tractores ni bicicletas: no alcanzan la velocidad mínima de seguridad. Los turismos con remolque sí están admitidos (límite 100 km/h)."},{"id":5403,"bg":"На автомагистрала е забранено:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"движението назад","ok":true,"i":null,"es":"ir marcha atrás"},{"t":"завиването в обратна посока","ok":true,"i":null,"es":"dar la vuelta"},{"t":"движението на мотоциклети без кош","ok":false,"i":null,"es":"la circulación de motocicletas sin sidecar"},{"t":"отстраняване на повреда на МПС в лентата за принудително спиране","ok":false,"i":null,"es":"reparar una avería del vehículo en el carril de parada de emergencia"}],"f":6,"es":"En autopista está prohibido: (2 correctas)","explain":"En autopista están prohibidos la marcha atrás y el cambio de sentido. Las motos sin sidecar circulan legalmente, y reparar una avería en el carril de emergencia es precisamente su uso legítimo."},{"id":5413,"bg":"На автомобилен път паркирането е разрешено:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"само на специално обозначените за това места","ok":true,"i":null,"es":"solo en los lugares especialmente señalizados para ello"},{"t":"най-вдясно на платното за движение","ok":false,"i":null,"es":"lo más a la derecha de la calzada de circulación"},{"t":"само извън платното за движение","ok":false,"i":null,"es":"solo fuera de la calzada"},{"t":"най-вдясно на пътното платно","ok":false,"i":null,"es":"lo más a la derecha de la calzada"}],"f":6,"es":"En carretera de automóviles el aparcamiento está permitido:","explain":"En vía rápida solo se aparca en los lugares especialmente señalizados. No existe el 'a la derecha de la calzada' ni el 'fuera de la calzada' libre: fuera de zona habilitada solo cabe la emergencia."},{"id":5427,"bg":"В кои случаи автомобилът, спрян в лентата за принудително спиране на автомагистрала, задължително се сигнализира?","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"през нощта","ok":true,"i":null,"es":"de noche"},{"t":"при намалена видимост","ok":true,"i":null,"es":"con visibilidad reducida"},{"t":"винаги","ok":false,"i":null,"es":"siempre"},{"t":"при ограничена видимост","ok":false,"i":null,"es":"con visibilidad limitada"}],"f":6,"explain":"Debe señalizarse de NOCHE y con visibilidad REDUCIDA (niebla, lluvia intensa): cuando el ojo no lo detecta a tiempo. 'Siempre' sobra de día despejado, y 'limitada' es el término de curvas y rasantes, no el de esta norma.","es":"¿En qué casos el vehículo parado en el carril de emergencia de autopista debe señalizarse? (2 correctas)"},{"id":11711,"bg":"Когато няма други ограничения, на водача на лек автомобил, при движение извън населено място, по автомобилен път, е забранено да се движи със скорост по-висока от:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"90 km/h","ok":true,"i":null,"es":"90 km/h"},{"t":"130 km/h","ok":false,"i":null,"es":"130 km/h"},{"t":"120 km/h","ok":false,"i":null,"es":"120 km/h"},{"t":"100 km/h","ok":false,"i":null,"es":"100 km/h"}],"f":6,"es":"Cuando no hay otras restricciones, al conductor de turismo circulando fuera de población por carretera de automóviles le está prohibido superar:","explain":"90 km/h... ojo a la trampa: la pregunta dice 'fuera de población POR carretera de automóviles' con la respuesta verificada en 90. Aprende el número que da el banco oficial para esta formulación exacta; en el examen la literalidad manda."},{"id":11719,"bg":"При тази ситуация водачът на товарния автомобил не извършва нарушение ако:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/41606.png","v":null,"a":[{"t":"е спрял поради повреда","ok":true,"i":null,"es":"se ha detenido por avería"},{"t":"е спрял за престой","ok":false,"i":null,"es":"se ha detenido para una parada (престой)"},{"t":"се движи със скорост не по- висока от 30 km/h","ok":false,"i":null,"es":"circula a una velocidad no superior a 30 km/h"},{"t":"е паркирал","ok":false,"i":null,"es":"está estacionado"}],"f":6,"es":"En esta situación el conductor del camión no comete infracción si:","explain":"SI SE HA DETENIDO POR AVERÍA. Una sola correcta.\n\nQUÉ VES. Una AUTOPISTA (señal verde). Un CAMIÓN está detenido en el carril de parada de emergencia (arcén), a la derecha.\n\nEN AUTOPISTA, EL ARCÉN SOLO ES PARA EMERGENCIAS. Detenerse ahí es correcto únicamente si es por avería o por otra causa de fuerza mayor.\n\n«PARADA (ПРЕСТОЙ)» y «ESTACIONADO» son los cebos: en autopista están prohibidos fuera de los lugares habilitados.\n\n«CIRCULA A NO MÁS DE 30 km/h» es otro cebo: el arcén no es un carril de circulación.\n\nCLAVE: arcén de autopista = solo avería o emergencia. Compárala con la 5426. Ver Leyes → «Autopista: incorporación y vehículos lentos»."},{"id":5547,"bg":"Този пътен знак:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334687.png","v":null,"a":[{"t":"указва начало на автобусна спирка","ok":true,"i":null,"es":"indica el inicio de una parada de autobús"},{"t":"обозначава края на автобусна спирка","ok":false,"i":null,"es":"indica el final de una parada de autobús"},{"t":"предупреждава за пресичане на път, по който се движат автобуси","ok":false,"i":null,"es":"advierte del cruce con una vía por la que circulan autobuses"},{"t":"указва пътна лента за движение само на автобуси","ok":false,"i":null,"es":"indica un carril reservado a autobuses"}],"f":6,"es":"Esta señal de tráfico:","explain":"INDICA EL INICIO DE UNA PARADA DE AUTOBÚS. Una sola correcta.\n\nLA SEÑAL. Cuadrado AZUL con un recuadro blanco y un AUTOBÚS.\n\nSE COLOCA AL PRINCIPIO DE LA PARADA: desde ahí empieza la zona donde el autobús se detiene.\n\n«FINAL DE LA PARADA» no se indica con esta señal. «CRUCE DE VÍA DE AUTOBUSES» y «CARRIL SOLO PARA AUTOBUSES» son cebos sin relación.\n\nCLAVE: compárala con la 5550. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5555,"bg":"С този знак се обозначава:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/38854.png","v":null,"a":[{"t":"трамвайна спирка","ok":true,"i":null,"es":"parada de tranvía"},{"t":"пресичане на трамвайна линия","ok":false,"i":null,"es":"cruce con una línea de tranvía"},{"t":"трамваен път","ok":false,"i":null,"es":"vía de tranvía"},{"t":"вход/изход на трамваен път","ok":false,"i":null,"es":"entrada/salida de una vía de tranvía"}],"f":6,"es":"Con esta señal se indica:","explain":"PARADA DE TRANVÍA. Una sola correcta.\n\nLA SEÑAL. Cuadrado AZUL con un recuadro blanco y un TRANVÍA.\n\nMARCA EL LUGAR DE LA PARADA del tranvía: cerca de ella habrá pasajeros subiendo y bajando, y a menudo cruzando la calzada.\n\n«CRUCE CON UNA LÍNEA DE TRANVÍA» es un triángulo de peligro con un tranvía. «VÍA DE TRANVÍA» y «ENTRADA O SALIDA» no son esta señal.\n\nCLAVE: vehículo en recuadro blanco sobre azul = parada (compárala con la 5550, la del autobús). Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5586,"bg":"Кое от изброените действия ще предприемете в тази ситуация при разминаване с потеглящия от спирката автобус?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/39121.png","v":null,"a":[{"t":"намалявам скоростта","ok":true,"i":null,"es":"reduzco la velocidad"},{"t":"управлявам с готовност за спиране","ok":true,"i":null,"es":"circulo listo para frenar"},{"t":"подавам звуков сигнал","ok":false,"i":null,"es":"doy una señal acústica"},{"t":"увеличавам скоростта за по-бързо разминаване","ok":false,"i":null,"es":"aumento la velocidad para cruzarnos más rápido"}],"f":6,"es":"¿Cuál de las acciones indicadas realizará en esta situación al cruzarse con el autobús que arranca de la parada? (2 correctas)","explain":"REDUZCO LA VELOCIDAD Y CIRCULO LISTO PARA FRENAR. Dos correctas.\n\nQUÉ VES. Calle urbana. A la izquierda, un AUTOBÚS articulado sale de su parada con el intermitente puesto, en sentido contrario. En la acera derecha camina una peatona.\n\nUN AUTOBÚS QUE ARRANCA puede ocupar parte de tu carril al incorporarse, y por detrás de él pueden salir peatones que acaban de bajar. Reduces y vas preparado.\n\n«TOCAR EL CLAXON» y «ACELERAR PARA CRUZARNOS ANTES» son los cebos.\n\nCLAVE: autobús que sale de la parada = espacio y freno preparado."},{"id":5589,"bg":"При тази ситуация, преминавайки покрай спрелия на спирката трамвай:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/39270.png","v":null,"a":[{"t":"трябва своевременно да намаля скоростта","ok":true,"i":null,"es":"debo reducir la velocidad a tiempo"},{"t":"трябва да управлявам с готовност за спиране","ok":true,"i":null,"es":"debo circular listo para frenar"},{"t":"трябва да внимавам за поведението на пешеходците преминаващи през платното за движение","ok":true,"i":null,"es":"debo estar atento al comportamiento de los peatones que cruzan la calzada"},{"t":"няма опасност от пресичащи пешеходци, защото няма пешеходна пътека","ok":false,"i":null,"es":"no hay peligro de peatones cruzando, porque no hay paso de peatones"}],"f":6,"es":"En esta situación, al pasar junto al tranvía parado en la parada: (3 correctas)","explain":"REDUCIR LA VELOCIDAD A TIEMPO, CIRCULAR LISTO PARA FRENAR Y ESTAR ATENTO A LOS PEATONES QUE CRUZAN. Tres correctas.\n\nQUÉ VES. Calle con un TRANVÍA detenido en su parada. Entre el tranvía y tu carril hay una pequeña ISLETA con una señal azul; una mujer está en ella y en la acera derecha hay más gente junto a la señal de parada.\n\nLA ISLETA TE PERMITE PASAR SIN DETENERTE, pero los pasajeros cruzan tu carril para llegar a ella o salir de ella. Vas despacio y vigilando.\n\n«NO HAY PELIGRO PORQUE NO HAY PASO DE PEATONES» es el cebo: en una parada los peatones cruzan haya o no paso pintado.\n\nCLAVE: compárala con la 5588."},{"id":5597,"bg":"При тази ситуация при приближаване към трамвайната спирка:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/39435.png","v":null,"a":[{"t":"трябва да спра, когато трамваят е спрял на спирката","ok":true,"i":null,"es":"debo detenerme cuando el tranvía está detenido en la parada"},{"t":"трябва да спра, когато трамваят спира на спирката","ok":true,"i":null,"es":"debo detenerme cuando el tranvía se está deteniendo en la parada"},{"t":"не съм задължен да намаля скоростта, когато трамваят потегля от спирката","ok":false,"i":null,"es":"no estoy obligado a reducir la velocidad cuando el tranvía arranca de la parada"}],"f":6,"es":"En esta situación, al acercarse a la parada de tranvía: (2 correctas)","explain":"DEBO DETENERME CUANDO EL TRANVÍA ESTÁ DETENIDO EN LA PARADA Y CUANDO SE ESTÁ DETENIENDO. Dos correctas.\n\nQUÉ VES. Calle con un TRANVÍA que llega a su parada (señal azul a la derecha), donde esperan varias personas en la acera. NO hay isleta: para subir, los pasajeros tienen que cruzar tu carril.\n\nSIN ISLETA, LOS PASAJEROS CRUZAN LA CALZADA para subir o bajar. Te detienes detrás del tranvía mientras se detiene y mientras está parado.\n\n«NO ESTOY OBLIGADO A REDUCIR CUANDO ARRANCA» es el cebo: aún puede haber peatones rezagados cruzando.\n\nCLAVE: compárala con la 5588 y la 5589 (con isleta)."},{"id":11622,"bg":"В района на спирка на превозните средства от редовните линии за обществен превоз на пътници, на други превозни средства е разрешено да спират за:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"слизане на пътници, само ако не пречат на превозните средства, за които е предназначена спирката","ok":true,"i":null,"es":"bajada de pasajeros, solo si no interfieren con los vehículos de línea"},{"t":"качване на пътници, ако не пречат на превозните средства, за които е предназначена спирката","ok":false,"i":null,"es":"subida de pasajeros, si no interfieren con los de línea"},{"t":"извършване на товаро-разтоварна дейност","ok":false,"i":null,"es":"carga y descarga de mercancías"}],"f":6,"es":"En la zona de parada del transporte público, otros vehículos solo pueden realizar:","explain":"En la zona de parada del transporte público, otros vehículos solo pueden BAJAR pasajeros, y solo sin estorbar a los de línea. Ni subir pasajeros ni cargar mercancías: la parada es de los autobuses."},{"id":11731,"bg":"В жилищна зона, обозначена със съответния пътен знак, е разрешено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"движение на пешеходците по платното за движение","ok":true,"i":null,"es":"la circulación de peatones por la calzada"},{"t":"на децата да играят на платното за движение","ok":true,"i":null,"es":"que los niños jueguen en la calzada"},{"t":"паркиране извън специално обозначените за това места","ok":false,"i":null,"es":"estacionar fuera de los lugares especialmente señalizados"},{"t":"движение със скорост 40 km/h","ok":false,"i":null,"es":"circular a 40 km/h"}],"f":6,"es":"En una zona residencial señalizada con la señal correspondiente está permitido: (2 correctas)","explain":"En zona residencial señalizada: peatones por la calzada y niños jugando en ella: es espacio compartido (por eso el límite es 20 km/h, nunca 40). Estacionar solo se permite en los lugares señalizados."},{"id":5813,"bg":"При тази ситуация водачът на жълтия автомобил задължен ли е да пропусне автомобила със специален режим на движение?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/29294.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":6,"es":"En esta situación, ¿está obligado el conductor del automóvil amarillo a ceder el paso al automóvil con régimen especial de circulación?","explain":""},{"id":5818,"bg":"При приближаване на МПС със специален режим на движение, водачите на останалите превозни средства са длъжни да осигурят безпрепятственото им преминаване, като:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"освободят достатъчно място на пътното платно","ok":true,"i":null,"es":"dejar espacio suficiente en la plataforma vial"},{"t":"при необходимост трябва да спрат","ok":true,"i":null,"es":"si es necesario, deben detenerse"},{"t":"задължително трябва да спрат възможно най-вдясно на пътното платно","ok":false,"i":null,"es":"obligatoriamente deben detenerse lo más a la derecha posible de la plataforma vial"},{"t":"незабавно да спрат в пътната лента, в която се намират","ok":false,"i":null,"es":"detenerse inmediatamente en el carril en el que se encuentran"}],"f":6,"es":"Al acercarse vehículos con régimen especial de circulación, los conductores de los demás vehículos están obligados a facilitar su paso sin obstáculos: (2 correctas)","explain":"Ante un vehículo con régimen especial: deja espacio suficiente y, si hace falta, detente. No hay obligación automática de parar pegado a la derecha ni de frenar en seco en tu carril: la ley pide facilitar el paso con criterio, no pánico."},{"id":6682,"bg":"В кой от изброените случаи е забранено тегленето на повреден автомобил с гъвкава връзка?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"когато дължината на връзката е по-малка от 4 метра","ok":true,"i":null,"es":"cuando la longitud del enganche es inferior a 4 metros"},{"t":"през нощта","ok":false,"i":null,"es":"de noche"},{"t":"когато водачът му е със стаж до 2 години","ok":false,"i":null,"es":"cuando su conductor tiene menos de 2 años de experiencia"},{"t":"когато масата на теглещото ППС е по-голяма от масата на тегленото ППС","ok":false,"i":null,"es":"cuando la masa del vehículo que remolca es mayor que la del remolcado"}],"f":6,"es":"¿En cuál de los casos indicados está prohibido remolcar un automóvil averiado con enganche flexible?","explain":"Prohibido remolcar con enganche flexible cuando mide menos de 4 m: el remolcado no tendría distancia de reacción y embestiría al que remolca. La noche, la experiencia del conductor o la relación de masas no prohíben la maniobra."},{"id":5551,"bg":"Кой автомобил е спрян правилно за престой?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42266.png","v":null,"a":[{"t":"само червеният автомобил","ok":false,"i":null,"es":"solo el rojo"},{"t":"само синият автомобил","ok":false,"i":null,"es":"solo el azul"},{"t":"и двата автомобила","ok":true,"i":null,"es":"ambos automóviles"}],"f":6,"es":"¿Qué automóvil está correctamente detenido (parada)?","explain":"AMBOS AUTOMÓVILES. Una sola correcta.\n\nQUÉ VES. La misma escena que la 5590: la señal de DOS BARRAS EN ASPA con una placa con una flecha hacia ABAJO, y los coches ROJO y AZUL detenidos junto a la acera, pasada la señal.\n\nLA FLECHA HACIA ABAJO = AQUÍ TERMINA la zona prohibida. Los dos están después del final.\n\n«SOLO EL ROJO» y «SOLO EL AZUL» son los cebos de quien lee la señal como el inicio.\n\nCLAVE: compárala con la 5590 y la 6258. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5577,"bg":"При тази ситуация на еднопосочния път, когато и двата автомобила са спрени за престой:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/160614.png","v":null,"a":[{"t":"синият автомобил е спрян правилно, ако това не пречи на движението","ok":true,"i":null,"es":"el automóvil azul está detenido correctamente si no obstaculiza el tráfico"},{"t":"червеният автомобил е спрян правилно, защото за престой се спира от дясната страна на пътя","ok":true,"i":null,"es":"el automóvil rojo está detenido correctamente, porque la parada se hace en el lado derecho de la vía"},{"t":"синият автомобил е спрян неправилно, защото престоят от лявата страна е забранен във всички случаи","ok":false,"i":null,"es":"el automóvil azul está detenido incorrectamente, porque la parada en el lado izquierdo está prohibida en todos los casos"}],"f":6,"es":"En esta situación, en la vía de sentido único, cuando ambos automóviles están detenidos para una parada breve: (2 correctas)","explain":"EL AZUL ESTÁ BIEN DETENIDO SI NO OBSTACULIZA EL TRÁFICO, Y EL ROJO ESTÁ BIEN DETENIDO A LA DERECHA. Dos correctas.\n\nQUÉ VES. Calle de SENTIDO ÚNICO (cuadrado azul con flecha). El coche AZUL está detenido junto a la acera IZQUIERDA; el ROJO, al fondo, junto a la acera DERECHA.\n\nEN SENTIDO ÚNICO SE PUEDE PARAR A AMBOS LADOS, siempre junto al borde y sin estorbar. A la derecha, como siempre; a la izquierda, también.\n\n«A LA IZQUIERDA ESTÁ PROHIBIDO EN TODOS LOS CASOS» es el cebo: el «en todos los casos» delata la opción falsa.\n\nCLAVE: compárala con la 5576 y la 5585."},{"id":5592,"bg":"Върху платното за движение след този знак е разрешено да спрете за:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43470.png","v":null,"a":[{"t":"слизане на пътник от автомобила","ok":true,"i":null,"es":"la bajada de un pasajero del automóvil"},{"t":"извършване на товарно-разтоварна дейност","ok":true,"i":null,"es":"realizar operaciones de carga y descarga"},{"t":"качване на пътник в автомобила","ok":true,"i":null,"es":"la subida de un pasajero al automóvil"},{"t":"паркиране","ok":false,"i":null,"es":"aparcar"}],"f":6,"es":"En la calzada, después de esta señal, está permitido detenerse para: (3 correctas)","explain":"LA BAJADA DE UN PASAJERO, LAS OPERACIONES DE CARGA Y DESCARGA Y LA SUBIDA DE UN PASAJERO. Tres correctas.\n\nQUÉ VES. Calle urbana. A la derecha, la señal de UNA sola barra (prohibido estacionar). Llevas el intermitente DERECHO y vas a arrimarte a la acera, donde hay un hombre.\n\nUNA BARRA PROHÍBE SOLO APARCAR: puedes detenerte para que suba o baje alguien y para cargar o descargar, sin dejar el coche.\n\n«APARCAR» es justo lo prohibido.\n\nCLAVE: compárala con la 11590 (la misma escena con el aspa, donde todo está prohibido). Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5622,"bg":"Спирането за престой е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на места, където превозното средство би закрило пътен знак","ok":true,"i":null,"es":"en lugares donde el vehículo ocultaría una señal de tráfico"},{"t":"на места, където превозното средство би закрило сигнал на светофара","ok":true,"i":null,"es":"en lugares donde el vehículo ocultaría la señal de un semáforo"},{"t":"на улици, по които се движат трамваи","ok":false,"i":null,"es":"en calles por las que circulan tranvías"},{"t":"пред входовете на театри и кина","ok":false,"i":null,"es":"delante de las entradas de teatros y cines"}],"f":6,"es":"La detención (parada) está prohibida: (2 correctas)","explain":"Parada prohibida donde el vehículo ocultaría una señal de tráfico o un semáforo a los demás: dejarías a los otros conductores ciegos ante la regulación. En calles con tranvía y ante teatros lo prohibido es ESTACIONAR, no la parada breve."},{"id":5628,"bg":"Спирането за престой е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на място с ограничена видимост","ok":true,"i":null,"es":"en un lugar con visibilidad limitada"},{"t":"върху трамвайна линия","ok":true,"i":null,"es":"sobre vía de tranvía"},{"t":"върху железопътна линия","ok":true,"i":null,"es":"sobre una línea ferroviaria"},{"t":"на неосветен участък от пътя","ok":false,"i":null,"es":"en un tramo de la vía sin iluminación"}],"f":6,"es":"La detención (parada) está prohibida: (3 correctas)","explain":"Parada prohibida: con visibilidad limitada (no te ven a tiempo), sobre vía de tranvía y sobre línea ferroviaria (no pueden esquivarte). La falta de iluminación del tramo no prohíbe la parada."},{"id":5630,"bg":"Паркирането е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на велосипедна пътека","ok":true,"i":null,"es":"en un carril bici"},{"t":"на разстояние, по-малко от 5 метра преди велосипедна пътека","ok":true,"i":null,"es":"a menos de 5 metros ANTES de un carril bici"},{"t":"на разстояние, по-малко от 5 метра след велосипедна пътека","ok":false,"i":null,"es":"a menos de 5 metros DESPUÉS de un carril bici"}],"f":6,"es":"El aparcamiento está PROHIBIDO: (2 correctas)","explain":"Aparcar prohibido sobre el carril bici y a menos de 5 m ANTES de él: misma lógica que el paso de peatones: no tapar al ciclista donde va a cruzar. Después del carril, permitido."},{"id":5647,"bg":"Паркирането е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"непосредствено пред входовете на жилищни сгради, когато това затруднява достъпа до тях","ok":true,"i":null,"es":"justo delante de las entradas de edificios de viviendas, cuando dificulta el acceso a ellas"},{"t":"пред входовете на детските заведения и училищата","ok":true,"i":null,"es":"delante de las entradas de guarderías y escuelas"},{"t":"на прилежащите тротоари на детските заведения и училищата","ok":true,"i":null,"es":"en las aceras adyacentes a guarderías y escuelas"},{"t":"пред здравни заведения","ok":false,"i":null,"es":"delante de centros de salud"}],"f":6,"es":"El estacionamiento está prohibido: (3 correctas)","explain":"Prohibido estacionar: ante entradas de viviendas cuando dificulta el acceso, ante entradas de guarderías y escuelas y en sus aceras adyacentes (protección de los niños). Ante centros de salud no hay prohibición general: esa es la trampa."},{"id":5656,"bg":"При спиране за престой преди кръстовище водачът е в нарушение, ако разстоянието от автомобила до кръстовището е:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"2 м","ok":true,"i":null,"es":"2 m"},{"t":"4 м","ok":true,"i":null,"es":"4 m"},{"t":"6 м","ok":false,"i":null,"es":"6 m"},{"t":"10 м","ok":false,"i":null,"es":"10 m"}],"f":6,"es":"Al detenerse (parada) antes de una intersección, el conductor comete infracción si la distancia del automóvil a la intersección es: (2 correctas)","explain":"Hay infracción si paras a menos de 5 m de la intersección: 2 m y 4 m incumplen; 6 m y 10 m son legales. La distancia protege la visibilidad de los que giran."},{"id":11629,"bg":"Пътно превозно средство е в престой, когато е спряно за ограничено време:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"за качване на пътници","ok":true,"i":null,"es":"para la subida de pasajeros"},{"t":"за слизане на пътници","ok":true,"i":null,"es":"para la bajada de pasajeros"},{"t":"за извършване на товарно-разтоварни работи в присъствието на водача","ok":true,"i":null,"es":"para operaciones de carga y descarga en presencia del conductor"},{"t":"за изчакване пристигането на пътник","ok":false,"i":null,"es":"para esperar la llegada de un pasajero"}],"f":6,"es":"Un vehículo está en parada cuando está detenido por tiempo limitado: (3 correctas)","explain":"Es 'parada' la detención por tiempo limitado para subir o bajar pasajeros o para carga/descarga CON el conductor presente. Esperar la llegada de alguien no entra en la definición: eso ya es estacionar."},{"id":5679,"bg":"Допълнителни светлини за мъгла се използват само при значително намалена видимост:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"поради мъгла","ok":true,"i":null,"es":"por niebla"},{"t":"поради снеговалеж","ok":true,"i":null,"es":"por nevada"},{"t":"поради дъжд","ok":true,"i":null,"es":"por lluvia"},{"t":"през тъмната част от денонощието","ok":false,"i":null,"es":"durante las horas de oscuridad"}],"f":6,"es":"Las luces antiniebla adicionales se usan solo con visibilidad considerablemente reducida: (3 correctas)","explain":"Las antiniebla se usan solo con visibilidad considerablemente reducida por niebla, nevada o lluvia. La oscuridad de la noche NO es motivo: para eso están las luces normales; las antiniebla de noche despejada deslumbran."},{"id":11633,"bg":"”Дневните светлини” са предназначени:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"за подобряване на възприемането и видимостта на предната част на ППС при движението му","ok":true,"i":null,"es":"para mejorar la percepción y visibilidad de la parte delantera del vehículo en marcha"},{"t":"за обозначаване през деня на паркирано МПС","ok":false,"i":null,"es":"para señalizar de día un vehículo estacionado"},{"t":"за движение по осветен път през нощта","ok":false,"i":null,"es":"para circular de noche por una vía iluminada"},{"t":"за подобряване осветеността на пътя","ok":false,"i":null,"es":"para mejorar la iluminación de la vía"}],"f":6,"es":"Las \"luces diurnas\" están destinadas:","explain":"Las luces diurnas sirven para que el vehículo EN MARCHA se perciba mejor de frente durante el día. No iluminan la vía (son débiles), no señalizan vehículos parados y de noche no bastan: hay que pasar a cortas."},{"id":5725,"bg":"При движение на превозното средство разходът на гориво се увеличава при:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"превозване на предмети върху покрива на автомобила","ok":true,"i":null,"es":"transportar objetos sobre el techo del automóvil"},{"t":"понижено налягане на въздуха в автомобилните гуми","ok":true,"i":null,"es":"presión de aire baja en los neumáticos"},{"t":"по-рядко използване на спирачките","ok":false,"i":null,"es":"usar los frenos con menos frecuencia"},{"t":"рязко увеличаване на скоростта","ok":true,"i":null,"es":"aumentar bruscamente la velocidad"}],"f":6,"es":"Durante la marcha del vehículo, el consumo de combustible aumenta con: (3 correctas)","explain":"El consumo aumenta con: carga en el techo, presión baja de neumáticos Y acelerones bruscos. Usar MENOS los frenos (conducción fluida y anticipada) reduce el consumo: por eso esa opción también es correcta en su formulación."},{"id":6115,"bg":"При управление на автомобил под въздействие на алкохол водачът:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"няма реална преценка за скоростта","ok":true,"i":null,"es":"no tiene una percepción real de la velocidad"},{"t":"забавя реакциите","ok":true,"i":null,"es":"ralentiza las reacciones"},{"t":"има по-бързи реакции","ok":false,"i":null,"es":"tiene reacciones más rápidas"},{"t":"е по-концентриран","ok":false,"i":null,"es":"está más concentrado"}],"f":6,"es":"Al conducir un automóvil bajo los efectos del alcohol, el conductor: (2 correctas)","explain":"El alcohol distorsiona la percepción de la velocidad y RALENTIZA las reacciones: el conductor cree ir bien mientras reacciona tarde. 'Reacciones más rápidas' y 'más concentrado' son exactamente los mitos que el examen quiere desmontar."},{"id":6127,"bg":"Колко често водачът трябва да спира за почивка при продължително пътуване?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"на всеки четири часа","ok":false,"i":null,"es":"cada cuatro horas"},{"t":"достатъчна е почивката при спирането за хранене","ok":false,"i":null,"es":"basta con el descanso de las paradas para comer"},{"t":"винаги когато почувства умора","ok":true,"i":null,"es":"siempre que sienta fatiga"}],"f":6,"es":"¿Con qué frecuencia debe detenerse a descansar el conductor en un viaje prolongado?","explain":"Siempre que sienta fatiga: el cuerpo marca el ritmo, no el reloj. Un intervalo fijo de cuatro horas puede ser demasiado, y las paradas para comer no bastan si el sueño aparece antes."},{"id":6132,"bg":"Какво означава водачът да бъде предвидлив?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"да предвижва възможните опасности в пътното движение","ok":true,"i":null,"es":"prever los posibles peligros del tráfico"},{"t":"да взема своевременно мерки, за да не попадне в аварийна ситуация","ok":true,"i":null,"es":"tomar medidas a tiempo para no verse en una situación de emergencia"},{"t":"да поддържа висока средна скорост на движение","ok":false,"i":null,"es":"mantener una velocidad media alta"},{"t":"да управлява винаги с ниска скорост","ok":false,"i":null,"es":"conducir siempre a baja velocidad"}],"f":6,"es":"¿Qué significa que el conductor sea previsor? (2 correctas)","explain":"Ser previsor = anticipar los posibles peligros y tomar medidas A TIEMPO para no llegar a la emergencia. No es una cuestión de velocidad alta ni baja: es leer el tráfico por adelantado."},{"id":6140,"bg":"В коя част от денонощието водачът различава по-добре цветовете?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"през деня","ok":true,"i":null,"es":"durante el día"},{"t":"през нощта на светлината от фарове","ok":false,"i":null,"es":"de noche, a la luz de los faros"},{"t":"при свечеряване","ok":false,"i":null,"es":"al anochecer"},{"t":"през нощта при силно улично осветление","ok":false,"i":null,"es":"de noche, con alumbrado público intenso"}],"f":6,"es":"¿En qué parte del día distingue mejor los colores el conductor?","explain":"De DÍA: la visión del color necesita luz abundante (los conos de la retina). De noche, con faros o farolas, domina la visión en grises: por eso las señales dependen tanto de forma y reflectancia."},{"id":5994,"bg":"Задължение на водача е превозваният товар:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да не закрива огледалата за виждане назад","ok":true,"i":null,"es":"no tape los retrovisores"},{"t":"да не закрива светлинните и сигналните устройства на автомобила","ok":true,"i":null,"es":"no tape los dispositivos de iluminación y señalización"},{"t":"да е укрепен","ok":true,"i":null,"es":"esté asegurada"},{"t":"да е застрахован","ok":false,"i":null,"es":"esté asegurada con seguro"}],"f":6,"es":"El conductor está obligado a que la carga: (3 correctas)","explain":"La carga: no debe tapar retrovisores ni luces/señalización, y debe estar ASEGURADA (sujeta, amarrada). La trampa es 'asegurada con seguro': la palabra búlgara 'застрахован' (póliza) no es un requisito de la carga."},{"id":6003,"bg":"Разрешено ли е да превозвате пътници в туристическо ремарке?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":6,"es":"¿Está permitido transportar pasajeros en un remolque-caravana?","explain":"No: tampoco en remolque-caravana se transportan pasajeros durante la marcha. La caravana no tiene sistemas de retención homologados para personas en movimiento."},{"id":6016,"bg":"Кога водачът е задължен да предостави за проверка документите си за управление на МПС?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"във всички случаи, когато представител на контролните органи поиска това","ok":true,"i":null,"es":"en todos los casos en que un agente de las autoridades de control lo solicite"},{"t":"само когато е допуснал нарушение на правилата за движение","ok":false,"i":null,"es":"solo cuando haya cometido una infracción de las normas de circulación"},{"t":"само при участие в пътнотранспортно произшествие","ok":false,"i":null,"es":"solo si está implicado en un accidente de tráfico"}],"f":6,"es":"¿Cuándo está obligado el conductor a presentar para control sus documentos de conducción?","explain":"Siempre que un agente de control lo solicite: la presentación de documentos no depende de haber cometido infracción ni de estar en un accidente. El control es potestad del agente."},{"id":6021,"bg":"Движещите се по пътя три- и четириколесни моторни превозни средства трябва да бъдат оборудвани:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"с аптечка","ok":true,"i":null,"es":"botiquín de primeros auxilios"},{"t":"с пожарогасител","ok":true,"i":null,"es":"con extintor"},{"t":"с въже за теглене","ok":false,"i":null,"es":"con cuerda de remolque"},{"t":"с инструменти за ремонт","ok":false,"i":null,"es":"con herramientas de reparación"}],"f":6,"es":"Los vehículos de motor de tres y cuatro ruedas que circulan por la vía deben estar equipados: (2 correctas)","explain":"También son obligatorios el botiquín y el EXTINTOR. La cuerda de remolque y las herramientas son recomendables pero no exigidos por la norma: esa es la trampa de esta variante."},{"id":5429,"bg":"Извършва ли нарушение водач, който отстъпва управлението на МПС на лице, което не притежава съответното свидетелство за управление?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":6,"es":"¿Comete infracción el conductor que cede la conducción del vehículo a una persona que no posee el permiso de conducción correspondiente?","explain":"Sí: ceder el volante a alguien sin el permiso correspondiente es infracción del que cede, no solo del que conduce. Eres responsable de a quién dejas tu vehículo."},{"id":8292,"bg":"Моторно превозно средство временно се спира от движение когато:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"е технически неизправно","ok":true,"i":null,"es":"tiene deficiencias técnicas"},{"t":"съдържанието на вредни вещества в изгорелите газове са над установените норми","ok":true,"i":null,"es":"el contenido de sustancias nocivas en los gases de escape supera las normas establecidas"},{"t":"е със свалени шумозаглушители","ok":true,"i":null,"es":"lleva los silenciadores desmontados"},{"t":"неговият водач откаже да бъде проверен от контролните органи за наличие на алкохол в кръвта","ok":false,"i":null,"es":"su conductor se niegue a ser sometido por los agentes al control de alcohol en sangre"}],"f":6,"es":"Un vehículo de motor se inmoviliza temporalmente cuando: (3 correctas)","explain":"Se inmoviliza temporalmente el vehículo con deficiencias técnicas, con gases contaminantes sobre la norma o con los silenciadores desmontados: problemas DEL VEHÍCULO. Negarse al control de alcoholemia acarrea sanciones al CONDUCTOR, no la inmovilización por estado técnico: esa es la trampa."},{"id":8294,"bg":"При нарушение, установено и заснето с техническо средство, в отсъствието на контролен орган и на нарушител, издаденият електроннен фиш:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"подлежи на обжалване","ok":true,"i":null,"es":"puede recurrirse"},{"t":"не подлежи на обжалване, когато наложената глоба е до 50 лв. включително","ok":false,"i":null,"es":"no puede recurrirse cuando la multa impuesta es de hasta 50 leva inclusive"},{"t":"подлежи на обжалване, само когато автомобилът е управляван от собственика","ok":false,"i":null,"es":"puede recurrirse solo cuando el automóvil era conducido por el propietario"}],"f":6,"es":"En una infracción detectada y grabada con un dispositivo técnico, en ausencia de agente y de infractor, el boletín electrónico emitido:","explain":"El boletín electrónico (фиш) emitido por infracción grabada sin agente ni infractor presentes PUEDE recurrirse: el derecho al recurso no desaparece por el importe ni por quién conducía."},{"id":11387,"bg":"Счита ли се за връчен фиш за неправилно паркиране, издаден в отсъствието на водача и към МПС е закрепено уведомление за това?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":6,"es":"¿Se considera entregado un boletín por estacionamiento incorrecto, emitido en ausencia del conductor y con una notificación fijada al vehículo?","explain":"Sí: el boletín por estacionamiento incorrecto emitido en ausencia del conductor se considera entregado con la notificación fijada al vehículo. No hace falta entrega en mano."},{"id":5304,"bg":"Поради коя от изброените причини най-често настъпват пътнотранспортни произшествия?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"грешка на водача","ok":true,"i":null,"es":"error del conductor"},{"t":"лоши пътни условия","ok":false,"i":null,"es":"malas condiciones de la vía"},{"t":"неизправност на превозното средство","ok":false,"i":null,"es":"avería del vehículo"},{"t":"неправилно поведение на пешеходците","ok":false,"i":null,"es":"comportamiento incorrecto de los peatones"}],"f":6,"es":"¿Por cuál de las causas indicadas ocurren con más frecuencia los accidentes de tráfico?","explain":"El ERROR DEL CONDUCTOR es la causa más frecuente de accidente, con enorme diferencia sobre vía, vehículo o peatones. El factor humano causa alrededor del 90% de los siniestros."},{"id":5332,"bg":"При ПТП, в което е участник, водачът съобразно необходимостта трябва:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да вземе мерки за безопасността на движението","ok":true,"i":null,"es":"tomar medidas para la seguridad del tráfico"},{"t":"да окаже помощ на пострадалите и вземе мерки за превозването им до здравно заведение","ok":true,"i":null,"es":"prestar ayuda a los heridos y tomar medidas para su traslado a un centro de salud"},{"t":"да вземе мерки за запазване на следите от произшествието","ok":true,"i":null,"es":"tomar medidas para conservar las huellas del accidente"},{"t":"да отстрани повредите по автомобила","ok":false,"i":null,"es":"reparar los daños del automóvil"}],"f":6,"es":"En un accidente en el que está implicado, el conductor, según la necesidad, debe: (3 correctas)","explain":"Implicado en accidente, según necesidad: asegurar el tráfico, ayudar a los heridos y organizar su traslado, y conservar las huellas. Reparar los daños del coche es lo único que NO debe hacerse: destruiría la evidencia."},{"id":5333,"bg":"Предприемането на кое от изброените действия е най-важно при пристигане на мястото на ПТП?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да се осигури безопасността на участниците в движението","ok":true,"i":null,"es":"garantizar la seguridad de los usuarios de la vía"},{"t":"да се съобщи за произшествието на полицейските служби","ok":false,"i":null,"es":"comunicar el accidente a los servicios policiales"},{"t":"да се запазят следите от произшествието","ok":false,"i":null,"es":"conservar las huellas del accidente"},{"t":"да се установят участниците в произшествието","ok":false,"i":null,"es":"identificar a los implicados en el accidente"}],"f":6,"es":"¿Cuál de las acciones indicadas es la más importante al llegar al lugar de un accidente?","explain":"Lo primero al llegar a un accidente: garantizar la SEGURIDAD de los usuarios de la vía: evitar el segundo accidente, que suele ser peor. Avisar, conservar huellas e identificar vienen después."},{"id":5338,"bg":"Допускат ли се корекции в двустранния констативен протокол, подписан от участниците в ПТП?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"не, всяка поправка на текста го прави невалиден","ok":true,"i":null,"es":"no, cualquier corrección del texto lo invalida"},{"t":"да, но само в деня на съставянето на протокола","ok":false,"i":null,"es":"sí, pero solo el día en que se redacta el parte"},{"t":"да, но със съгласието на двамата водачи","ok":false,"i":null,"es":"sí, pero con el acuerdo de ambos conductores"}],"f":6,"es":"¿Se admiten correcciones en el parte amistoso firmado por los implicados en el accidente?","explain":"No: cualquier corrección en el parte amistoso firmado lo INVALIDA. Si hay que cambiar algo, se redacta un parte nuevo: la integridad del documento es su garantía."},{"id":5351,"bg":"Когато се уведомява за ПТП с участието на МПС обозначено с опознавателен знак за опасен товар, от най-съществено значение са данните:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"от опознавателния знак за вида на превозвания опасен товар","ok":true,"i":null,"es":"por el distintivo del tipo de mercancía peligrosa transportada"},{"t":"за регистрационния номер на превозното средство","ok":false,"i":null,"es":"de la matrícula del vehículo"},{"t":"за фирмата, чиято собственост е превозното средство","ok":false,"i":null,"es":"de la empresa propietaria del vehículo"}],"f":6,"es":"Al informar de un accidente con un vehículo señalizado con el distintivo de mercancías peligrosas, los datos más esenciales son:","explain":"Lo esencial al informar: el DISTINTIVO del tipo de mercancía peligrosa (los paneles naranjas con códigos): dice a los servicios de emergencia QUÉ sustancia afrontan y cómo actuar. La matrícula o la empresa no salvan vidas."},{"id":5355,"bg":"Кой е единният европейски телефонен номер за спешни и аварийни обаждания?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"112","ok":true,"i":null,"es":"112"},{"t":"144","ok":false,"i":null,"es":"144"},{"t":"160","ok":false,"i":null,"es":"160"},{"t":"196","ok":false,"i":null,"es":"196"}],"f":6,"es":"¿Cuál es el número único europeo de emergencias?","explain":"112: número único europeo de emergencias, gratuito y disponible desde cualquier teléfono. Los otros números del enunciado no son el número europeo."},{"id":11433,"bg":"Водач, който е участник в ПТП, уведомява за произшествието компетентната служба на МВР когато:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"при произшествието има пострадали хора","ok":true,"i":null,"es":"en el accidente hay personas heridas"},{"t":"ПТП е само с имуществени вреди, но между участниците няма съгласие относно обстоятелствата, свързани с него","ok":true,"i":null,"es":"el accidente tiene solo daños materiales, pero los implicados no están de acuerdo sobre sus circunstancias"},{"t":"винаги, независимо от обстоятелствата","ok":false,"i":null,"es":"siempre, independientemente de las circunstancias"}],"f":6,"es":"Un conductor implicado en un accidente avisa del accidente al servicio competente del MVR cuando: (2 correctas)","explain":"Se avisa al MVR: cuando hay heridos (siempre) y cuando, con solo daños materiales, los implicados NO se ponen de acuerdo. Con acuerdo y solo daños, basta el parte amistoso: por eso 'siempre' es falsa."},{"id":11649,"bg":"Когато в ПТП участва превозно средство, обозначено с опознавателен знак за опасен товар, трябва:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да стоим на безопасно разстояние, освен ако се налага да спасим нечий живот","ok":true,"i":null,"es":"mantenernos a distancia segura, salvo que haya que salvar la vida de alguien"},{"t":"да преместим това превозно средство извън платното за движение","ok":false,"i":null,"es":"apartar ese vehículo fuera de la calzada"},{"t":"да отстраним опасния товар от пътя","ok":false,"i":null,"es":"retirar la carga peligrosa de la vía"},{"t":"да покрием товара с подходящо покривало","ok":false,"i":null,"es":"cubrir la carga con una lona adecuada"}],"f":6,"es":"Cuando en un accidente participa un vehículo señalizado con el distintivo de mercancías peligrosas, hay que:","explain":"Con mercancías peligrosas: distancia segura salvo para salvar una vida. Mover el vehículo, retirar la carga o taparla con una lona son intervenciones de especialistas: un derrame químico no se improvisa."},{"id":9822,"bg":"Кой от пътните знаци предупреждава за стеснение на платното за движение?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":false,"es":"","i":"269866899"},{"t":"","ok":false,"es":"","i":"269866898"},{"t":"","ok":false,"es":"","i":"269866897"},{"t":"","ok":true,"es":"","i":"269866896"}],"f":6,"es":"¿Cuál de las señales advierte de estrechamiento de la calzada?","explain":"LA ÚLTIMA: TRIÁNGULO CON LA CALZADA QUE SE ESTRECHA POR AMBOS LADOS. Una sola correcta.\n\nQUÉ VES. Cuatro señales: 1) cuadrado azul con flecha blanca hacia arriba y flecha roja hacia abajo (preferencia sobre los que vienen de frente); 2) cuadrado azul con un carril que se une a otro; 3) triángulo con un coche junto a un arcén peligroso; 4) triángulo con dos líneas que se juntan por ambos lados.\n\nEL ESTRECHAMIENTO ES EL TRIÁNGULO DE LAS LÍNEAS QUE SE JUNTAN.\n\n«EL CARRIL QUE SE UNE» es el cebo fino: indica que se acaba un carril, no que se estreche la calzada, y es azul (información).\n\n«LA PREFERENCIA SOBRE LOS DE FRENTE» suele ir junto a un estrechamiento, pero no avisa de él: te dice quién pasa primero.\n\nCLAVE: compárala con la 5253 y la 5249. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6194,"bg":"На кой от пътните знаци значението е “Преминаване отдясно на знака”?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334697.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/45433.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/45469.png","es":""}],"f":6,"es":"¿En cuál de las señales el significado es 'Paso por la derecha de la señal'?","explain":"LA PRIMERA: CÍRCULO AZUL CON FLECHA OBLICUA HACIA ABAJO A LA DERECHA. Una sola correcta.\n\nQUÉ VES. Tres círculos azules: 1) flecha oblicua que baja hacia la derecha; 2) flecha que gira a la derecha; 3) flecha horizontal hacia la derecha.\n\nLA FLECHA OBLICUA HACIA ABAJO indica por qué lado de un obstáculo (una isleta, una obra) tienes que pasar: por la derecha de la señal.\n\n«LA FLECHA QUE GIRA» obliga a girar a la derecha en el cruce. «LA FLECHA HORIZONTAL» indica la dirección obligatoria (a la derecha).\n\nCLAVE: flecha oblicua hacia abajo = rodea el obstáculo por ese lado. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5254,"bg":"Кой от пътните знаци предупреждава за стръмен наклон при спускане?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/21368.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/21369.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334666.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/21371.png","es":""}],"f":6,"es":"¿Cuál de las señales advierte de pendiente pronunciada en bajada?","explain":"LA PRIMERA: TRIÁNGULO CON LA RAMPA QUE BAJA Y «10 %». Una sola correcta.\n\nQUÉ VES. Cuatro triángulos: 1) rampa que BAJA de izquierda a derecha con «10 %»; 2) rampa que SUBE con «10 %»; 3) sucesión de curvas; 4) estrechamiento por ambos lados.\n\nSE LEE DE IZQUIERDA A DERECHA, como si condujeras: si la rampa baja, es bajada.\n\n«LA SEGUNDA» es el cebo directo: es la subida (compárala con la 5222).\n\nCLAVE: mismo dibujo, dirección contraria; fíjate hacia dónde cae la rampa. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5483,"bg":"При светване на кой контролен индикатор от арматулното табло има опасност от сериозна повреда в двигателя, ако не преустановите движението?","p":1,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334685.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334684.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334683.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/30014.png","es":""}],"f":6,"es":"¿Con el encendido de qué indicador del cuadro de instrumentos existe peligro de avería grave del motor si no detiene la marcha?","explain":"LA SEGUNDA: LA ACEITERA ROJA. Una sola correcta.\n\nQUÉ VES. Cuatro testigos: 1) «P» en un círculo (freno de estacionamiento); 2) una ACEITERA con una gota (presión de aceite); 3) una BATERÍA (carga); 4) «ABS» en amarillo.\n\nLA ACEITERA ROJA = PRESIÓN DE ACEITE BAJA. Si sigues conduciendo, el motor se queda sin lubricación y puede griparse. Paras en cuanto sea seguro y apagas el motor.\n\n«LA BATERÍA» indica un fallo de carga: el coche seguirá hasta agotarla, pero el motor no se rompe por eso. «EL ABS» amarillo avisa de que el antibloqueo no funciona; los frenos siguen. «LA P» es el freno de mano.\n\nCLAVE: rojo = para ya; amarillo = revisa pronto."},{"id":5327,"bg":"Кое от показаните превозни средства е автомобил?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/128965.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/128966.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/128967.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/128968.png","es":""}],"f":6,"es":"¿Cuál de los vehículos mostrados es un automóvil? (3 correctas)","explain":"Automovil = vehiculo de motor para transporte de personas o mercancias, de 4+ ruedas, masa maxima hasta 3500 kg para cat. B."},{"id":9841,"bg":"На кой от пътните знаци значението е “Преминаване в платното за насрещно движение”?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/270043309.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/270043310.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/270043311.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/270043312.png","es":""}],"f":6,"es":"¿En cuál de las señales el significado es 'Circulación por el carril contrario'?","explain":"La senal de adelantamiento obligatorio por la izquierda se usa cuando hay obstaculos por la derecha."},{"id":6586,"bg":"След кой от тези знаци, при преминаване през кръстовището, превозното средство от другия път трябва да ви пропусне?","p":3,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/55245.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/55246.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/55247.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/55248.png","es":""}],"f":6,"es":"¿Después de cuál de estas señales, al cruzar la intersección, el vehículo del otro camino debe cederte el paso? (2 correctas)","explain":"LA PRIMERA Y LA SEGUNDA SEÑAL. Dos correctas.\n\nQUÉ VES. Cuatro señales:\n1) ROMBO amarillo con borde blanco: VÍA CON PRIORIDAD.\n2) Triángulo con un trazo GRUESO vertical cruzado por uno fino: CRUCE CON UNA VÍA SIN PRIORIDAD.\n3) Triángulo con flechas en círculo: aproximación a una ROTONDA.\n4) Cuadrado AZUL con flecha blanca hacia arriba y flecha roja hacia abajo: PRIORIDAD SOBRE LOS VEHÍCULOS QUE VIENEN DE FRENTE.\n\nLAS DOS PRIMERAS TE DAN PREFERENCIA EN EL CRUCE: los vehículos de la otra vía te ceden el paso.\n\n«LA ROTONDA» solo avisa de que se acerca una rotonda; no te da preferencia.\n\n«PRIORIDAD SOBRE LOS QUE VIENEN DE FRENTE» es el cebo fino: da preferencia, pero en un ESTRECHAMIENTO frente a los que vienen en sentido contrario, no en un cruce frente a los de la otra vía.\n\nCLAVE: preferencia en un cruce = rombo o triángulo de trazo grueso. La flecha blanca/roja es para estrechamientos.\n\nMÉTODO: 1) ¿la señal habla de un cruce o de un estrechamiento? 2) ¿me da preferencia a mí? Ver Leyes → «Señales verticales: la forma manda sobre el dibujo» y «Vía con prioridad»."},{"id":6185,"bg":"Кой от пътните знаци указва задължителна посока за движение на превозните средства?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43011.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43012.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43013.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43014.png","es":""}],"f":6,"es":"¿Cuál de las señales indica dirección de circulación obligatoria?","explain":"LA PRIMERA: CÍRCULO AZUL CON FLECHA DE GIRO A LA IZQUIERDA. Una sola correcta.\n\nQUÉ VES. Cuatro señales: 1) círculo AZUL con flecha que gira a la izquierda; 2) cuadrado azul con una U; 3) cuadrado azul con una T (calle sin salida); 4) triángulo de curva peligrosa.\n\nLAS DE DIRECCIÓN OBLIGATORIA SON CÍRCULOS AZULES con flecha blanca.\n\n«LA U» es un lugar para cambiar de sentido (información). «LA T» es una calle sin salida. «EL TRIÁNGULO» es un aviso de curva.\n\nCLAVE: círculo azul = obligación; cuadrado azul = información; triángulo = peligro. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5270,"bg":"Кой от пътните знаци предупреждава за приближаване към кръстовище?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334675.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/21411.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/25516.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/25590.png","es":""}],"f":6,"es":"¿Cuál de las señales advierte de la proximidad de una intersección?","explain":"EL TRIÁNGULO CON UNA X. Una sola correcta.\n\nQUÉ VES. Cuatro señales: 1) triángulo con una X; 2) triángulo con un signo de exclamación; 3) cuadrado azul con una flecha en U; 4) triángulo con un peatón sobre un paso de peatones.\n\nLA X AVISA DE UN CRUCE (de vías iguales, donde se aplica la regla de la derecha).\n\n«EL SIGNO DE EXCLAMACIÓN» es «otros peligros». «LA U AZUL» indica un lugar para cambiar de sentido. «EL PEATÓN» avisa de un paso de peatones.\n\nCLAVE: X en triángulo = cruce próximo sin prioridad para nadie. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6282,"bg":"Кой знак предупреждава за конкретна опасност?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/55703.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334695.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/55705.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/55706.png","es":""}],"f":6,"es":"¿Qué señal advierte de un peligro concreto?","explain":"LA PRIMERA: TRIÁNGULO DE CURVA PELIGROSA. Una sola correcta.\n\nQUÉ VES. Cuatro señales: 1) triángulo de CURVA PELIGROSA a la derecha; 2) círculo azul de giro obligatorio a la derecha; 3) círculo rojo de prohibido girar a la derecha; 4) cuadrado azul de calle sin salida.\n\nSOLO LOS TRIÁNGULOS AVISAN DE UN PELIGRO CONCRETO. Las demás obligan, prohíben o informan.\n\nCLAVE: forma triangular con borde rojo = peligro. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5513,"bg":"С кой от опознавателните знаци се обозначава полуремаркетата?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/23496.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/23497.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334739.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/23499.png","es":""}],"f":6,"es":"¿Con cuál de los signos distintivos se identifican los semirremolques? (2 correctas)","explain":"LA PRIMERA Y LA SEGUNDA: LAS PLACAS AMARILLAS CON BORDE ROJO. Dos correctas.\n\nQUÉ VES. Cuatro traseras: 1) dos placas verticales amarillas con borde rojo; 2) placas amarillas con borde rojo en forma de L; 3) dos placas con franjas diagonales rojas y amarillas; 4) una placa ancha con franjas diagonales.\n\nLAS PLACAS TRASERAS QUE SE CONFUNDEN:\n• AMARILLAS CON BORDE ROJO (lisas) = REMOLQUES y SEMIRREMOLQUES.\n• FRANJAS DIAGONALES ROJAS Y AMARILLAS = CAMIONES largos y pesados (más de 3,5 t y más de 7 m).\n\nLAS DOS PRIMERAS son de semirremolque (en sus dos disposiciones). LAS DE FRANJAS son de camión.\n\nCLAVE: compárala con la 5404 y la 11816."},{"id":5246,"bg":"Кой от пътните знаци предупреждава, че ще навлезете в опасен завой?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":false,"es":"","i":"21036"},{"t":"","ok":false,"es":"","i":"21056"},{"t":"","ok":true,"es":"","i":"21013"},{"t":"","ok":false,"es":"","i":"21035"}],"f":6,"es":"¿Cuál de las señales advierte de que entras en una curva peligrosa?","explain":"LA SEÑAL DE LAS CURVAS PELIGROSAS (TRIÁNGULO CON LA LÍNEA EN ZIGZAG). Una sola correcta.\n\nQUÉ VES. Cuatro señales: 1) círculo azul con flecha a la derecha (dirección obligatoria); 2) círculo rojo con flecha a la derecha tachada (prohibido girar a la derecha); 3) triángulo con una línea que dibuja una sucesión de curvas; 4) triángulo con un coche derrapando (calzada deslizante).\n\nLA ÚNICA QUE AVISA DE UNA CURVA PELIGROSA es el triángulo con la línea curvada.\n\nLAS CIRCULARES no avisan de nada: obligan o prohíben.\n\n«EL COCHE DERRAPANDO» avisa de calzada deslizante, no de curva.\n\nCLAVE: triángulo + línea que se dobla = curva(s). Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":13509,"bg":"При тази ситуация трябва да пропусна пешеходеца.","p":3,"s":"Раздел 4","i":"1382984687","v":null,"a":[{"t":"неправилно","ok":false,"es":"INCORRECTO"},{"t":"правилно","ok":true,"es":"correcto"}],"f":6,"es":"En esta situación debo ceder el paso al peatón. Esto es:","explain":"CORRECTO.\n\nQUÉ VES. Llevas el intermitente DERECHO y vas a girar a la derecha (flecha). El semáforo te da VERDE con flechas (izquierda; recto y derecha). En la calle a la que giras, una PEATONA está cruzando. De frente viene un coche rojo.\n\nAL GIRAR, CEDES A LOS PEATONES QUE CRUZAN LA CALLE A LA QUE ENTRAS. Da igual que tengas prioridad frente a los demás vehículos o que el paso esté o no pintado: al girar a la derecha o a la izquierda, los peatones que cruzan la vía en la que te metes pasan antes que tú. El verde te permite girar, pero no te permite pasar por encima de quien cruza.\n\n«INCORRECTO» es el cebo de quien piensa que el verde o la flecha le dan paso libre.\n\nCLAVE: semáforo en verde + giro + peatón cruzando la calle de destino = esperas al peatón.\n\nMÉTODO: 1) ¿giro? 2) ¿alguien cruza la calle a la que entro? 3) si cruza, cedo. Ver Leyes → «Paso de peatones»."},{"id":5245,"bg":"Кой от пътните знаци предупреждава, че ще навлезете в опасен завой?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/21014.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/21015.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/83151.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/21035.png","es":""}],"f":6,"es":"¿Cuál de las señales advierte de que entras en una curva peligrosa? (2 correctas)","explain":"Las curvas peligrosas se senalizan con triangulos que muestran la curva. La flecha indica la direction del giro."},{"id":6044,"bg":"Когато се подава с ръка, сигналът за отклоняване вдясно е:","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/27665.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/27666.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/27667.png","es":""}],"f":6,"es":"Cuando se da con el brazo, la señal para desviarse a la derecha es:","explain":"LA PRIMERA: BRAZO IZQUIERDO FUERA, CON EL ANTEBRAZO DOBLADO HACIA ARRIBA. Una sola correcta.\n\nQUÉ VES. Tres fotos de un coche visto desde atrás, con el conductor sacando el brazo IZQUIERDO por la ventanilla: 1) brazo hacia fuera con el antebrazo doblado hacia arriba; 2) brazo extendido en horizontal; 3) brazo levantado recto hacia arriba.\n\nEL CONDUCTOR SOLO PUEDE SACAR EL BRAZO IZQUIERDO, así que para indicar la DERECHA dobla el antebrazo hacia arriba.\n\n«BRAZO EN HORIZONTAL» indica desplazamiento a la IZQUIERDA.\n\n«BRAZO RECTO HACIA ARRIBA» indica que va a frenar o detenerse.\n\nCLAVE: horizontal = izquierda; doblado hacia arriba = derecha; recto arriba = frenar. Compárala con la 6046 (la moto puede usar el brazo de cada lado)."},{"id":6166,"bg":"Индикаторът на електронната стабилизираща система (ESP) на арматурното табло светва за определено време, когато:","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"се активира системата","ok":true,"i":null,"es":"el sistema se activa"},{"t":"системата е повредена","ok":false,"i":null,"es":"el sistema está averiado"},{"t":"автомобилът е спрян","ok":false,"i":null,"es":"el automóvil está detenido"}],"f":5,"es":"El indicador del sistema electrónico de estabilidad (ESP) del cuadro se enciende durante un tiempo determinado cuando:","explain":"El testigo del ESP se enciende un momento cuando el sistema SE ACTIVA (está corrigiendo una pérdida de adherencia en ese instante). Si quedara fijo indicaría avería: el parpadeo temporal es funcionamiento, no fallo."},{"id":5471,"bg":"Светването на този символ върху арматурното табло означава, че:","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334683.png","v":null,"a":[{"t":"не се зарежда акумулаторната батерия","ok":true,"i":null,"es":"la batería no se carga"},{"t":"не работи осветлението","ok":false,"i":null,"es":"el alumbrado no funciona"},{"t":"има повреда в запалителната уредба","ok":false,"i":null,"es":"hay una avería en el sistema de encendido"},{"t":"задължително трябва да се подмени акумулаторната батерия","ok":false,"i":null,"es":"es obligatorio sustituir la batería"}],"f":5,"es":"El encendido de este símbolo en el cuadro de instrumentos significa que:","explain":"LA BATERÍA NO SE CARGA. Una sola correcta.\n\nQUÉ VES. Un testigo ROJO con una BATERÍA (con «−» y «+»).\n\nENCENDIDO CON EL MOTOR EN MARCHA = EL ALTERNADOR NO ESTÁ CARGANDO LA BATERÍA. El coche funciona con la carga que queda hasta que se agote.\n\n«HAY QUE CAMBIAR LA BATERÍA» es el cebo: el fallo suele estar en la carga (alternador, correa), no en la batería.\n\n«NO FUNCIONA EL ALUMBRADO» y «AVERÍA EN EL ENCENDIDO» no son el significado de este testigo.\n\nCLAVE: compárala con la 5483."},{"id":5474,"bg":"При светването на този символ върху арматурното табло, има опасност от блокиране на двигателя:","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334684.png","v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcto"},{"t":"неправилно","ok":false,"i":null,"es":"INCORRECTO"}],"f":5,"es":"Con el encendido de este símbolo en el cuadro de instrumentos existe peligro de que el motor se gripe. Esto es:","explain":"CORRECTO.\n\nQUÉ VES. Un testigo ROJO con una ACEITERA y una gota.\n\nES LA PRESIÓN DE ACEITE BAJA. Sin presión de aceite, las piezas del motor rozan sin lubricar y el motor puede griparse (bloquearse).\n\n«INCORRECTO» es el cebo de quien lo toma por un simple aviso de nivel.\n\nCLAVE: compárala con la 5483 y la 5477."},{"id":5477,"bg":"Какво трябва да предприеме водачът, когато върху арматурното табло свети този символ?","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334684.png","v":null,"a":[{"t":"да спре на подходящо място","ok":true,"i":null,"es":"detenerse en un lugar adecuado"},{"t":"да изгаси двигателя","ok":true,"i":null,"es":"apagar el motor"},{"t":"да продължи движението, но на по-ниска предавка","ok":false,"i":null,"es":"continuar la marcha, pero en una marcha más corta"},{"t":"да продължи движението, но с по-високи обороти на двигателя","ok":false,"i":null,"es":"continuar la marcha, pero con el motor a más revoluciones"}],"f":5,"es":"¿Qué debe hacer el conductor cuando en el cuadro de instrumentos se enciende este símbolo? (2 correctas)","explain":"DETENERSE EN UN LUGAR ADECUADO Y APAGAR EL MOTOR. Dos correctas.\n\nQUÉ VES. El testigo ROJO de la ACEITERA: presión de aceite baja.\n\nCADA SEGUNDO CON EL MOTOR EN MARCHA SIN PRESIÓN DE ACEITE lo daña. Paras en cuanto sea seguro y lo apagas.\n\n«SEGUIR EN UNA MARCHA MÁS CORTA» y «SEGUIR CON MÁS REVOLUCIONES» son los cebos: hacen trabajar más al motor sin lubricación.\n\nCLAVE: testigo rojo = para y apaga."},{"id":5437,"bg":"Използването на вода като охладителна течност в охладителната уредба на МПС в зимни условия:","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"не се препоръчва, защото при температура под нула градуса водата замръзва","ok":true,"i":null,"es":"no se recomienda, porque a temperaturas bajo cero el agua se congela"},{"t":"не се използва, защото при кипене водата се изпарява","ok":false,"i":null,"es":"no se usa, porque al hervir el agua se evapora"},{"t":"не се използва, защото водата причинява корозия на охладителната уредба","ok":false,"i":null,"es":"no se usa, porque el agua causa corrosión en el sistema de refrigeración"},{"t":"е забранено","ok":false,"i":null,"es":"está prohibido"}],"f":5,"es":"El uso de agua como líquido refrigerante en el sistema de refrigeración del vehículo en condiciones invernales:","explain":"El agua no se recomienda en invierno porque SE CONGELA bajo cero: al congelarse se expande y revienta el bloque y los conductos. El anticongelante existe exactamente para eso."},{"id":5182,"bg":"Трамваят е релсово превозно средство, което се приравнява към групата на моторните превозни средства.","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":5,"es":"El tranvia es un vehículo de carretera ferroviario que se equipara al grupo de los vehículos de motor.","explain":"INCORRECTO: el tranvía se equipara a los VEHÍCULOS (ППС), no a los vehículos de motor (МПС). Es la distinción legal clásica: circula por raíles y tiene su propio régimen."},{"id":5234,"bg":"“Граница на платното за движение” е линията:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"с която се очертава “ВUS”-лентата","ok":true,"i":null,"es":"con la que se delimita el carril BUS"},{"t":"с която се очертава края на платното за движение","ok":true,"i":null,"es":"con la que se delimita el borde de la calzada"},{"t":"с която се очертават островите на платното за движение","ok":true,"i":null,"es":"con la que se delimitan las isletas de la calzada"},{"t":"с която се отделят пътните ленти","ok":false,"i":null,"es":"con la que se separan los carriles"}],"f":5,"es":"'Límite de calzada' es la línea: (3 correctas)","explain":"La línea de límite (ограничителна линия) delimita el borde de la calzada, las isletas y el carril BUS. Lo que NO hace es separar los carriles normales entre sí: para eso están las líneas divisorias discontinuas o continuas."},{"id":5315,"bg":"Видимостта е ограничена при:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"препятствия, които пречат на видимостта","ok":true,"i":null,"es":"obstáculos que impiden la visibilidad"},{"t":"крайпътни обекти, които ограничават видимостта","ok":true,"i":null,"es":"objetos junto a la vía que limitan la visibilidad"},{"t":"проливен дъжд","ok":false,"i":null,"es":"lluvia torrencial"},{"t":"силен снеговалеж","ok":false,"i":null,"es":"nevada intensa"}],"f":5,"es":"La visibilidad esta limitada en: (2 correctas)","explain":"Visibilidad LIMITADA: la que restringen obstáculos u objetos junto a la vía (y la geometría: curvas, rasantes). La lluvia torrencial y la nevada producen visibilidad REDUCIDA: fenómeno atmosférico, no físico-geométrico. El examen vive de esta distinción."},{"id":8246,"bg":"Триколесно МПС задвижвано от електродвигател, с конструктивна максимална скорост не по-висока от 45 km/h, се управлява с правоспособност за категория АМ ако максималната постоянна номинална мощност на двигателя е:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"не повече от 3 kW","ok":false,"i":null,"es":"no más de 3 kW"},{"t":"не повече от 4 kW","ok":true,"i":null,"es":"no más de 4 kW"},{"t":"не повече от 5 kW","ok":false,"i":null,"es":"no más de 5 kW"},{"t":"не повече от 6 kW","ok":false,"i":null,"es":"no más de 6 kW"}],"f":5,"es":"Un triciclo de motor eléctrico con velocidad máxima constructiva de hasta 45 km/h se conduce con categoría AM si la potencia nominal continua máxima del motor es:","explain":"4 kW: un triciclo eléctrico de hasta 45 km/h se conduce con categoría AM solo si su potencia nominal continua no supera los 4 kW. Con más potencia deja de ser asimilable a ciclomotor."},{"id":11903,"bg":"Участници в движението са:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"водачите","ok":true,"i":null,"es":"los conductores"},{"t":"автомобилите","ok":false,"i":null,"es":"los automóviles"},{"t":"пешеходците","ok":true,"i":null,"es":"los peatones"},{"t":"лицата, работещи на пътя","ok":true,"i":null,"es":"las personas que trabajan en la vía"}],"f":5,"es":"Son participantes en el tráfico: (3 correctas)","explain":"Participantes en el tráfico son PERSONAS: conductores, peatones y quienes trabajan en la vía. Los automóviles son objetos (vehículos), no participantes: es la trampa de definición."},{"id":12072,"bg":"Трамваите се приравняват към:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"пътните превозни средства","ok":true,"i":null,"es":"los vehículos"},{"t":"моторните превозни средства","ok":false,"i":null,"es":"los vehículos de motor"},{"t":"автомобилите със специално предназначение","ok":false,"i":null,"es":"los vehículos especiales"},{"t":"тролейбусите","ok":false,"i":null,"es":"los trolebuses"}],"f":5,"es":"Los tranvías están equiparados a:","explain":"Los tranvías se equiparan a los VEHÍCULOS (ППС) en general: circulan por vía férrea, no son 'vehículos de motor' (МПС) a efectos de la ley ni vehículos especiales."},{"id":5194,"bg":"Този пътен знак предупреждава за:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334667.png","v":null,"a":[{"t":"опасен пътен банкет","ok":true,"i":null,"es":"arcén peligroso"},{"t":"хлъзгав участък от пътя","ok":false,"i":null,"es":"tramo de vía deslizante"},{"t":"неравности по пътя","ok":false,"i":null,"es":"irregularidades (baches) en la vía"},{"t":"начин на паркиране","ok":false,"i":null,"es":"modo de estacionamiento"}],"f":5,"es":"Esta señal advierte de:","explain":"ARCÉN PELIGROSO. Una sola correcta.\n\nLA SEÑAL. Triángulo de peligro con un coche inclinado, con las ruedas de un lado sobre el borde de la calzada (arcén) y gravilla.\n\nAVISA DE QUE EL ARCÉN ESTÁ EN MAL ESTADO o más bajo que la calzada: si te sales a él, el coche puede volcarse o perder el control.\n\n«TRAMO DESLIZANTE» es el cebo más parecido: esa señal tiene un coche derrapando con huellas en zigzag, no inclinado sobre el borde.\n\n«IRREGULARIDADES (BACHES)» se dibuja con el perfil de la calzada ondulado. «MODO DE ESTACIONAMIENTO» es una placa azul, no un triángulo.\n\nCLAVE: coche inclinado sobre el borde = arcén peligroso; coche derrapando = deslizante. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5207,"bg":"При тази ситуация, жълтозеленият флуоресцентен светлоотразителен фон, върху който е поставен пътният знак:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/22896.png","v":null,"a":[{"t":"сигнализира, че пътният участък е с концентрация на пътнотранспортни произшествия","ok":true,"i":null,"es":"señaliza que el tramo tiene concentración de accidentes de tráfico"},{"t":"указва, че е забранено и изпреварването","ok":false,"i":null,"es":"indica que también está prohibido el adelantamiento"},{"t":"указва, че ограничението на скоростта се спазва само при движение в завой","ok":false,"i":null,"es":"indica que el límite de velocidad se aplica solo al circular en la curva"},{"t":"указва, че следва участък от пътя в ремонт","ok":false,"i":null,"es":"indica que sigue un tramo de vía en obras"}],"f":5,"es":"En esta situación, el fondo fluorescente amarillo-verde sobre el que está colocada la señal:","explain":"SEÑALIZA QUE EL TRAMO TIENE CONCENTRACIÓN DE ACCIDENTES DE TRÁFICO. Una sola correcta.\n\nQUÉ VES. Vista desde el asiento del conductor: una señal de velocidad máxima 50 colocada sobre un panel de FONDO AMARILLO-VERDE FLUORESCENTE.\n\nEL FONDO FLUORESCENTE NO CAMBIA LO QUE DICE LA SEÑAL; solo llama la atención porque ese tramo es un punto negro, con muchos accidentes.\n\n«TAMBIÉN PROHÍBE ADELANTAR» es el cebo: para eso haría falta la señal de prohibido adelantar.\n\n«SOLO EN LA CURVA» es el cebo de limitar la señal: el fondo no dice nada de dónde acaba.\n\n«TRAMO EN OBRAS» confunde el fondo amarillo-verde con las señales temporales de obras, que tienen fondo amarillo.\n\nCLAVE: fondo amarillo-verde fluorescente = punto negro (tramo de concentración de accidentes). Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5264,"bg":"Този пътен знак:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334675.png","v":null,"a":[{"t":"предупреждава за кръстовище, на което се пресичат равнозначни пътища","ok":true,"i":null,"es":"advierte de una intersección de vías de igual rango"},{"t":"указва началото на участък от пътя, в който е забранено навлизането","ok":false,"i":null,"es":"indica el inicio de un tramo de vía donde está prohibida la entrada"},{"t":"сигнализира участък от пътя, по който са забранени престоят и паркирането","ok":false,"i":null,"es":"señaliza un tramo de vía donde están prohibidas la parada y el estacionamiento"},{"t":"сигнализира за край на пътя с предимство","ok":false,"i":null,"es":"señaliza el fin de la vía con prioridad"}],"f":5,"es":"Esta señal:","explain":"ADVIERTE DE UNA INTERSECCIÓN DE VÍAS DE IGUAL RANGO. Una sola correcta.\n\nLA SEÑAL. Triángulo de peligro con una X.\n\nLA X SON DOS VÍAS IGUALES QUE SE CRUZAN: ninguna tiene prioridad, así que en ese cruce se aplica la regla de la derecha.\n\n«PROHIBIDA LA ENTRADA», «PROHIBIDO PARAR Y ESTACIONAR» y «FIN DE LA PRIORIDAD» son cebos: son señales circulares o el rombo tachado, no un triángulo. La X de «prohibido parar» va en un círculo azul con borde rojo.\n\nCLAVE: X en triángulo = cruce de vías iguales; X en círculo azul = prohibido parar y estacionar. Ver Leyes → «Regla de la derecha». Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5277,"bg":"Когато в близост няма пешеходна пътека, на пешеходците е разрешено да пресичат платното за движение извън определените за това места:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"по пътища извън населените места","ok":true,"i":null,"es":"en vías fuera de poblado"},{"t":"по двулентовите двупосочни пътища в населените места","ok":true,"i":null,"es":"en vías de dos carriles y doble sentido dentro de poblado"},{"t":"на пътните възли на автомагистралите","ok":false,"i":null,"es":"en los enlaces de las autopistas"},{"t":"по всички пътища отворени за обществено ползване","ok":false,"i":null,"es":"en todas las vías abiertas al uso público"}],"f":5,"es":"Cuando no hay paso de peatones cercano, los peatones pueden cruzar fuera de los pasos en: (2 correctas)","explain":"Fuera de los pasos se puede cruzar: en vías fuera de poblado y, dentro de poblado, en vías de dos carriles y doble sentido (cuando no hay paso cercano). Nunca en enlaces de autopista ni 'en todas las vías': esas generalizaciones son falsas."},{"id":9855,"bg":"При тази ситуация пешеходецът пресича платното за движение по пешеходна пътека.","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/270044518.png","v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcto"},{"t":"неправилно","ok":false,"i":null,"es":"INCORRECTO"}],"f":5,"es":"En esta situación el peatón cruza la calzada por un paso de peatones. Esto es:","explain":"CORRECTO.\n\nQUÉ VES. Un cruce con señal de vía con prioridad. Una PEATONA cruza la calzada en la esquina, siguiendo la línea de la acera, en una zona sin pintar; los pasos tipo cebra se ven más al fondo y a la derecha.\n\nEN UNA INTERSECCIÓN, LA PROLONGACIÓN DE LA ACERA ES UN PASO DE PEATONES aunque no tenga ninguna marca en el suelo. Ella cruza por donde tiene derecho, y tú le cedes el paso igual que en una cebra.\n\n«INCORRECTO» es el cebo de quien solo reconoce como paso de peatones el que está pintado.\n\nCLAVE: compárala con la 9856 y la 9854. Ver Leyes → «Paso de peatones»."},{"id":11602,"bg":"Този пътен знак сигнализира:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123577637.png","v":null,"a":[{"t":"за използването на пътя се изисква платена ТОЛ такса","ok":true,"i":null,"es":"para usar la vía se exige el pago de peaje (TOL)"},{"t":"двупосочно движение след знака","ok":false,"i":null,"es":"circulación en ambos sentidos después de la señal"},{"t":"движение само направо след знака","ok":false,"i":null,"es":"solo ir recto después"},{"t":"броя на пътните ленти за движение в една посока","ok":false,"i":null,"es":"el número de carriles de circulación en un sentido"}],"f":5,"es":"Esta señal señaliza:","explain":"PARA USAR LA VÍA SE EXIGE EL PAGO DE PEAJE (TOL). Una sola correcta.\n\nLA SEÑAL. Cuadrado AZUL con una carretera dibujada arriba y, debajo, «ТОЛ / TOLL» con un camión de más de 3,5 t y un autobús.\n\nINDICA QUE ESA VÍA ES DE PEAJE para los vehículos pesados (camiones de más de 3,5 t y autobuses). A diferencia de la 11601, aquí no aparece la viñeta.\n\n«DOBLE SENTIDO», «SOLO RECTO» y «NÚMERO DE CARRILES» son cebos que se fijan solo en el dibujo de la carretera.\n\nCLAVE: si la señal pone «ТОЛ», trata del pago. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":11605,"bg":"Този пътен знак предупреждава за:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123579826.png","v":null,"a":[{"t":"намалена видимост","ok":false,"i":null,"es":"visibilidad reducida"},{"t":"настъпило пътнотранспортно произшествие","ok":false,"i":null,"es":"accidente de tráfico ocurrido"},{"t":"възможна е поява на силен страничен вятър","ok":false,"i":null,"es":"posible viento lateral fuerte"},{"t":"образувано задръстване","ok":true,"i":null,"es":"retención formada"}],"f":5,"es":"Esta señal advierte de:","explain":"RETENCIÓN FORMADA. Una sola correcta.\n\nLA SEÑAL. Triángulo de peligro con FONDO AMARILLO (temporal) y TRES COCHES en fila, uno detrás de otro.\n\nLOS COCHES EN FILA SON UN ATASCO: más adelante el tráfico está parado o muy lento. Reduces a tiempo y vigilas el final de la cola.\n\n«VISIBILIDAD REDUCIDA» tiene líneas horizontales de niebla (compárala con la 11604). «ACCIDENTE» y «VIENTO LATERAL» tienen dibujos distintos.\n\nCLAVE: varios coches en fila = retención. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5383,"bg":"При приближаване към този автобус, водачът трябва:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/22878.png","v":null,"a":[{"t":"да осигури безопасността на децата","ok":true,"i":null,"es":"garantizar la seguridad de los niños"},{"t":"при необходимост да спре","ok":true,"i":null,"es":"detenerse si es necesario"},{"t":"да подаде звуков сигнал, преди да премине покрай автобуса","ok":false,"i":null,"es":"dar una señal acústica antes de pasar junto al autobús"},{"t":"да премине по-бързо покрай автобуса","ok":false,"i":null,"es":"pasar más rápido junto al autobús"}],"f":5,"es":"Al acercarse a este autobús, el conductor debe: (2 correctas)","explain":"GARANTIZAR LA SEGURIDAD DE LOS NIÑOS Y DETENERSE SI ES NECESARIO. Dos correctas.\n\nQUÉ VES. Calle urbana. De frente viene un AUTOBÚS con el distintivo NARANJA de transporte de niños (ampliado en la imagen), con las luces de emergencia. Delante de él, varios NIÑOS cruzan la calzada; en las aceras hay más gente.\n\nEL DISTINTIVO NARANJA DICE QUE LLEVA NIÑOS. Pueden bajar y cruzar por delante o por detrás del autobús sin mirar, como ya está pasando. Reduces, vigilas y paras si hace falta.\n\n«DAR UNA SEÑAL ACÚSTICA» es el cebo: el claxon puede asustar a un niño y hacerle correr justo hacia ti.\n\n«PASAR MÁS RÁPIDO» es el cebo absurdo: cuanto más rápido, menos tiempo para frenar.\n\nCLAVE: compárala con la 5381 (el mismo distintivo naranja). Ver Leyes → «Niños en la vía»."},{"id":5538,"bg":"Пътното превозно средство е извънгабаритно когато:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"височината му, включително товара, е 4,2 м","ok":true,"i":null,"es":"su ALTURA, incluyendo carga, es 4.2 m"},{"t":"широчината му, включително товара, е 2,2 м","ok":false,"i":null,"es":"su ANCHURA, incluyendo carga, es 2.2 m"},{"t":"дължината му, включително товара, е 12 м","ok":false,"i":null,"es":"su LONGITUD, incluyendo carga, es 12 m"}],"f":5,"es":"Un vehículo es 'fuera de gálibo' cuando:","explain":"El límite de altura es 4 m, así que 4,2 m ya es fuera de gálibo. La anchura de 2,2 m no supera los 2,55 m permitidos y la longitud de 12 m tampoco excede el límite."},{"id":5778,"bg":"При тази ситуация трябва:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/24570.png","v":null,"a":[{"t":"да управлявам с готовност за спиране","ok":true,"i":null,"es":"circular listo para frenar"},{"t":"да бъда внимателен към поведението на велосипедистите","ok":true,"i":null,"es":"estar atento al comportamiento de los ciclistas"},{"t":"да подам звуков сигнал за да привлека вниманието на велосипедистите","ok":false,"i":null,"es":"dar una señal acústica para llamar la atención de los ciclistas"}],"f":5,"es":"En esta situación debes: (2 correctas)","explain":"CIRCULAR LISTO PARA FRENAR Y ESTAR ATENTO AL COMPORTAMIENTO DE LOS CICLISTAS. Dos correctas.\n\nQUÉ VES. Calle urbana. Justo delante, en tu carril, va una CICLISTA con casco; al otro lado de la calle viene otro ciclista y, más al fondo, un coche rojo.\n\nLOS CICLISTAS PUEDEN DESVIARSE, CAERSE O GIRAR sin avisar. Mantienes distancia, vas preparado para frenar y vigilas qué hacen.\n\n«DAR UNA SEÑAL ACÚSTICA» es el cebo: el claxon puede sobresaltar al ciclista y hacer que pierda el equilibrio justo delante de ti.\n\nCLAVE: con ciclistas cerca, freno preparado, no claxon. Compárala con la 5552."},{"id":6042,"bg":"Водачът на ППС е задължен да подаде сигнал към останалите участници в движението:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"преди да завие в кръстовище","ok":true,"i":null,"es":"antes de girar en una intersección"},{"t":"преди да започне маневра, свързана с отклонение встрани","ok":true,"i":null,"es":"antes de iniciar una maniobra que implique desviarse lateralmente"},{"t":"преди да се включи в движението","ok":true,"i":null,"es":"antes de incorporarse al tráfico"},{"t":"преди рязко намаляване на скоростта","ok":false,"i":null,"es":"antes de reducir bruscamente la velocidad"}],"f":5,"es":"El conductor de un vehículo está obligado a dar señal a los otros participantes en el tráfico: (3 correctas)","explain":"Se señaliza antes de: girar en intersección, cualquier maniobra con desplazamiento lateral e incorporarse al tráfico. La reducción brusca de velocidad no se anuncia con intermitente: se anuncia sola con las luces de freno."},{"id":6053,"bg":"Кога при движение в населено място е разрешено да се използва звуков сигнал?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"само в случаите за предотвратяване на ПТП","ok":true,"i":null,"es":"solo en los casos necesarios para evitar un accidente de tráfico"},{"t":"при приближаване към пешеходна пътека, по която се движат пешеходци","ok":false,"i":null,"es":"al acercarse a un paso de peatones por el que cruzan peatones"},{"t":"винаги","ok":false,"i":null,"es":"siempre"}],"f":5,"es":"¿Cuándo está permitido usar el claxon en población?","explain":"En población el claxon solo se usa para evitar un accidente inminente: es la única excepción legal. Usarlo ante un paso con peatones cruzando o 'siempre' es infracción y además intimida a quien tiene la prioridad."},{"id":12004,"bg":"Какво трябва да направите в тази ситуация?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":5,"a":[{"t":"подавам звуков сигнал на велосипедиста, за да ме пропусне","ok":false,"i":null,"es":"doy señal acústica al ciclista para que me deje pasar"},{"t":"изпреварвам велосипедиста","ok":false,"i":null,"es":"adelanto al ciclista"},{"t":"продължавам движението си зад велосипедиста","ok":true,"i":null,"es":"continúo circulando detrás del ciclista"}],"f":5,"es":"¿Qué debes hacer en esta situación?","explain":"Un ciclista circula delante de mí en zona de intersección urbana con tráfico de frente: lo correcto es CONTINUAR detrás de él hasta que exista espacio seguro. El claxon para 'apartarlo' es un uso prohibido de la señal acústica (el ciclista tiene su derecho a la vía), y adelantar aquí — cruce + tráfico en sentido contrario — no permite la separación lateral obligatoria. Paciencia: el ciclista no es un obstáculo, es tráfico."},{"id":12020,"bg":"При тази ситуация трябва да намалите скоростта с готовност за спиране заради:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":2,"a":[{"t":"белия автомобил, паркиран от дясната страна","ok":false,"i":null,"es":"el coche blanco aparcado a la derecha"},{"t":"детето","ok":true,"i":null,"es":"el niño"},{"t":"мотоциклета","ok":false,"i":null,"es":"la moto"}],"f":5,"es":"En esta situación debes reducir la velocidad con disposición de frenar por:","explain":"Un coche blanco aparcado a la derecha y un NIÑO en esa zona: el niño puede saltar a la calzada oculto por el coche estacionado, sin mirar — reduzco con el pie preparado sobre el freno POR EL NIÑO. El coche blanco en sí no hace nada (está aparcado) y la moto no corta mi trayectoria: distractores. Con niños cerca de vehículos aparcados, asume siempre que aparecerán por el hueco menos visible."},{"id":12025,"bg":"Какъв е правилният начин на действие при тази ситуация?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":9,"a":[{"t":"продължавам движението си, без да променям скоростта","ok":false,"i":null,"es":"continúo sin cambiar velocidad"},{"t":"преминавам наляво","ok":false,"i":null,"es":"giro a la izquierda"},{"t":"намалявам скоростта и при необходимост спирам","ok":true,"i":null,"es":"reduzco velocidad y si es necesario paro"}],"f":5,"es":"¿Cuál es la actuación correcta en esta situación?","explain":"Reduce velocidad y para si es necesario. Ante cualquier incertidumbre, la respuesta correcta es reducir."},{"id":12074,"bg":"С този опознавателен знак се обозначават:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1173451119.png","v":null,"a":[{"t":"МПС, превозващи опасни товари","ok":true,"i":null,"es":"vehículos que transportan mercancías peligrosas"},{"t":"бавнодвижещи се МПС","ok":false,"i":null,"es":"vehículos lentos"},{"t":"МПС с извънгабаритен товар","ok":false,"i":null,"es":"vehículos de motor con carga de dimensiones excepcionales"},{"t":"автомобилите със специално предназначение","ok":false,"i":null,"es":"los vehículos especiales"}],"f":5,"es":"Con este signo distintivo se identifican:","explain":"VEHÍCULOS QUE TRANSPORTAN MERCANCÍAS PELIGROSAS. Una sola correcta.\n\nQUÉ VES. Un panel rectangular NARANJA con borde negro, dividido en dos: arriba «33» y abajo «1088».\n\nEL PANEL NARANJA ES EL DE LA MERCANCÍA PELIGROSA. El número de arriba indica el tipo de peligro y el de abajo, la sustancia concreta.\n\n«VEHÍCULOS LENTOS» llevan un triángulo rojo. «CARGA DE DIMENSIONES EXCEPCIONALES» y «VEHÍCULOS ESPECIALES» tienen otras placas y luces.\n\nCLAVE: compárala con la 5526 (el mismo panel entre otros distintivos)."},{"id":5936,"bg":"Този пътен знак предупреждава:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/41210.png","v":null,"a":[{"t":"за приближаване към подвижен мост","ok":true,"i":null,"es":"de la proximidad de un PUENTE MÓVIL"},{"t":"за приближаване към повреден мост","ok":false,"i":null,"es":"de la proximidad de un puente dañado"},{"t":"че пътят води до кей или бряг","ok":false,"i":null,"es":"que el camino lleva a un muelle o ribera"},{"t":"че пътят е затворен за движение","ok":false,"i":null,"es":"que la vía está cerrada"}],"f":5,"es":"Esta señal advierte:","explain":"DE LA PROXIMIDAD DE UN PUENTE MÓVIL. Una sola correcta.\n\nLA SEÑAL. Triángulo de peligro con un PUENTE LEVADIZO (un tablero que se levanta) sobre el AGUA.\n\nEL TABLERO LEVANTADO es el puente móvil: puede estar abierto para dejar pasar barcos.\n\n«MUELLE O RIBERA» es el cebo más parecido: ese dibujo es un coche cayendo al agua desde un borde (compárala con la 5939).\n\n«PUENTE DAÑADO» y «VÍA CERRADA» no son el significado.\n\nCLAVE: tablero levantado = puente móvil; coche cayendo = muelle. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5962,"bg":"Този пътен знак:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/46532.png","v":null,"a":[{"t":"забранява влизането на ППС срещу него","ok":true,"i":null,"es":"prohíbe la entrada de vehículos en su sentido"},{"t":"забранява влизането само на леки автомобили срещу знака","ok":false,"i":null,"es":"prohíbe la entrada solo de turismos en el sentido de la señal"},{"t":"разрешава влизането на мотоциклетисти срещу знака","ok":false,"i":null,"es":"permite la entrada de motociclistas en el sentido de la señal"},{"t":"указва, че пътят е без изход","ok":false,"i":null,"es":"indica que la vía no tiene salida (calle sin salida)"}],"f":5,"es":"Esta señal:","explain":"PROHÍBE LA ENTRADA DE VEHÍCULOS EN SU SENTIDO. Una sola correcta.\n\nLA SEÑAL. Círculo ROJO con una barra horizontal BLANCA: PROHIBIDA LA ENTRADA (dirección prohibida).\n\nPROHÍBE ENTRAR A TODOS LOS VEHÍCULOS que vienen de frente a la señal; normalmente es la salida de una calle de sentido único.\n\n«SOLO A TURISMOS» y «PERMITE A LOS MOTORISTAS» son cebos que confunden esta señal con la de la 5973 (que sí exceptúa motos).\n\n«CALLE SIN SALIDA» es un cuadrado azul con una T.\n\nCLAVE: barra blanca en círculo rojo = nadie entra por ese lado. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5973,"bg":"Този пътен знак забранява влизането:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334705.png","v":null,"a":[{"t":"на МПС, с изключение на мотоциклети без кош и мотопеди","ok":true,"i":null,"es":"de vehículos a motor excepto motos sin sidecar y ciclomotores"},{"t":"на всички МПС","ok":false,"i":null,"es":"a todos los vehículos de motor"},{"t":"само на леки автомобили","ok":false,"i":null,"es":"solo de turismos"},{"t":"на всички ППС","ok":false,"i":null,"es":"de todos los vehículos"}],"f":5,"es":"Esta señal prohíbe la entrada:","explain":"A LOS VEHÍCULOS DE MOTOR, EXCEPTO MOTOCICLETAS SIN SIDECAR Y CICLOMOTORES. Una sola correcta.\n\nLA SEÑAL. Círculo con borde ROJO y fondo blanco con la silueta negra de un COCHE de frente.\n\nEL COCHE REPRESENTA A LOS VEHÍCULOS DE MOTOR en general, pero la señal deja fuera a las motos sin sidecar y a los ciclomotores (como la de prohibido adelantar).\n\n«SOLO A TURISMOS» es el cebo de leer el dibujo al pie de la letra.\n\n«A TODOS LOS VEHÍCULOS DE MOTOR» olvida la excepción. «A TODOS LOS VEHÍCULOS» incluiría también bicicletas y carros.\n\nCLAVE: compárala con la 5962 (barra blanca = nadie) y la 5334 (el coche en azul = vía rápida). Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6186,"bg":"Този пътен знак:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334694.png","v":null,"a":[{"t":"задължава водачите да се движат само направо след знака","ok":true,"i":null,"es":"obliga a circular solo RECTO después de la señal"},{"t":"сигнализира за еднопосочно движение след знака","ok":false,"i":null,"es":"señaliza tráfico de sentido único después"},{"t":"указва посоката на пътя с предимство","ok":false,"i":null,"es":"indica la dirección de la vía preferente"},{"t":"препоръчва на водачите да се движат направо след знака","ok":false,"i":null,"es":"recomienda ir recto"}],"f":5,"es":"Esta señal:","explain":"OBLIGA A CIRCULAR SOLO RECTO DESPUÉS DE LA SEÑAL. Una sola correcta.\n\nLA SEÑAL. Círculo AZUL con una flecha blanca recta hacia arriba.\n\nCÍRCULO AZUL = OBLIGACIÓN: en el cruce siguiente solo puedes seguir recto.\n\n«SENTIDO ÚNICO» es el CUADRADO azul con la misma flecha (compárala con la 6199).\n\n«RECOMIENDA» es el cebo: las señales azules circulares obligan. «DIRECCIÓN DE LA VÍA PREFERENTE» se indica con un panel bajo el rombo.\n\nCLAVE: compárala con la 6187. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6263,"bg":"Допълнителната табела към пътния знак указва:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/54814.png","v":null,"a":[{"t":"начало на участъка, в който е забранено паркирането","ok":true,"i":null,"es":"INICIO del tramo donde está prohibido aparcar"},{"t":"край на участъка, в който е забранено паркирането","ok":false,"i":null,"es":"FIN del tramo donde está prohibido aparcar"}],"f":5,"es":"La tablilla complementaria junto a la señal indica:","explain":"INICIO DEL TRAMO DONDE ESTÁ PROHIBIDO APARCAR.\n\nQUÉ VES. Señal de PROHIBIDO ESTACIONAR (círculo azul con borde rojo y una sola barra) con una placa con una flecha VERTICAL de una sola punta hacia ARRIBA.\n\nLA FLECHA DE UNA SOLA PUNTA EN LA PLACA:\n• hacia DELANTE (arriba, en una señal de frente) = aquí EMPIEZA la zona;\n• hacia ATRÁS (abajo) = aquí TERMINA;\n• de DOS puntas = sigues dentro de la zona.\n\n«FIN DEL TRAMO» llevaría la flecha hacia abajo (compárala con la 6258).\n\nCLAVE: flecha hacia delante = empieza. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6300,"bg":"При тази ситуация забраната за движение със скорост, по-висока от означената, е валидна:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/56929.png","v":null,"a":[{"t":"до края на опасността, сигнализирана с предупредителния пътен знак","ok":true,"i":null,"es":"hasta el final del peligro señalizado por la señal de advertencia"},{"t":"до знак, който отменя забраната","ok":false,"i":null,"es":"hasta la señal que cancela la prohibición"},{"t":"до следващото кръстовище","ok":false,"i":null,"es":"hasta la próxima intersección"},{"t":"на 50м след знака","ok":false,"i":null,"es":"a 50 m después de la señal"}],"f":5,"es":"En esta situación la prohibición de circular a velocidad superior a la indicada es válida:","explain":"HASTA EL FINAL DEL PELIGRO SEÑALIZADO POR LA SEÑAL DE ADVERTENCIA. Una sola correcta.\n\nQUÉ VES. Una curva balizada con paneles direccionales y, a la derecha, el triángulo de curvas sucesivas con un círculo rojo de 50 km/h justo debajo.\n\nCUANDO EL LÍMITE ACOMPAÑA A UNA SEÑAL DE PELIGRO, su vigencia se ata a ese peligro: rige mientras dura la curva y termina con ella. La limitación existe POR el peligro, así que se acaba cuando el peligro se acaba.\n\n«HASTA LA PRÓXIMA INTERSECCIÓN» es la regla general de las prohibiciones — la de la pregunta 6295 — y es correcta cuando el límite va solo. Aquí no va solo: va vinculado a un aviso concreto.\n\n«HASTA LA SEÑAL QUE CANCELA LA PROHIBICIÓN» describe el caso en que hay una señal de fin explícita. Tampoco es necesaria aquí.\n\n«A 50 m DESPUÉS DE LA SEÑAL» confunde el número del límite con una distancia. El 50 del círculo son kilómetros por hora, no metros.\n\nCLAVE: mira si el límite viene solo o pegado a un triángulo de peligro. Solo, dura hasta el cruce siguiente. Acompañando a un peligro, dura lo que dure el peligro.\n\nMÉTODO DE SEÑALES: la FORMA dice el tipo antes que el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5895,"bg":"Значението на този сигнал на светофара е:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/40074.png","v":null,"a":[{"t":"„Забранено е преминаването направо или завиването надясно”","ok":true,"i":null,"es":"'Prohibido continuar recto o girar a la derecha'"},{"t":"„Забранено е навлизането в кръстовището за всички участници в движението”","ok":false,"i":null,"es":"'Prohibida la entrada para todos los participantes'"},{"t":"„Забранено е преминаването, освен на ППС, преминаващи направо или завиващи надясно”","ok":false,"i":null,"es":"'Prohibido pasar excepto los que van recto o giran a la derecha'"}],"f":5,"es":"El significado de esta señal de semáforo es:","explain":"«PROHIBIDO CONTINUAR RECTO O GIRAR A LA DERECHA». Una sola correcta.\n\nQUÉ VES. Un semáforo con la luz ROJA encendida y, dibujadas en negro sobre ella, FLECHAS hacia arriba y hacia la derecha.\n\nUNA LUZ CON FLECHAS SOLO AFECTA A ESAS DIRECCIONES. El rojo con flechas de recto y derecha prohíbe precisamente seguir recto y girar a la derecha. No dice nada de la izquierda.\n\n«PROHIBIDA LA ENTRADA PARA TODOS» es el cebo: sería un rojo sin flechas.\n\n«PROHIBIDO PASAR EXCEPTO LOS QUE VAN RECTO O GIRAN A LA DERECHA» es justo lo contrario: lee las flechas como permitidas cuando están en rojo.\n\nCLAVE: las flechas dicen a qué direcciones se aplica el color de la luz. Ver Leyes → «El semáforo: cada luz tiene un nombre oficial»."},{"id":6087,"bg":"При тази ситуация, на път извън населено място, на водачите е разрешено:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/140619.png","v":null,"a":[{"t":"да се движат в най-дясната свободна пътна лента","ok":true,"i":null,"es":"circular por el carril libre situado más a la derecha"},{"t":"да се движат в средната пътна лента, когато дясната е заета","ok":true,"i":null,"es":"circular en el carril central cuando el derecho está ocupado"},{"t":"да навлизат в средната лента при изпреварване","ok":true,"i":null,"es":"entrar en el carril central para adelantar"},{"t":"да навлизат в крайната лява лента при изпреварване","ok":false,"i":null,"es":"entrar en el carril extremo izquierdo al adelantar"}],"f":5,"es":"En esta situación, en vía fuera de poblado, a los conductores les está permitido: (3 correctas)","explain":"CIRCULAR POR EL CARRIL DERECHO DISPONIBLE, USAR EL CENTRAL CUANDO EL DERECHO ESTÁ OCUPADO Y ENTRAR EN EL CENTRAL PARA ADELANTAR. Tres correctas.\n\nQUÉ VES. La misma escena que la 6085: fuera de población, TRES carriles; la señal azul indica DOS carriles en tu sentido (flechas hacia arriba) y UNO en sentido contrario (flecha hacia abajo, el de la izquierda).\n\nTUS CARRILES SON EL DERECHO Y EL CENTRAL. Vas por el derecho si está libre; usas el central cuando el derecho está ocupado o para adelantar.\n\n«ENTRAR EN EL CARRIL IZQUIERDO PARA ADELANTAR» es el cebo: según la señal, ese carril es del sentido contrario.\n\nCLAVE: lee primero la señal de carriles: cuántas flechas son tuyas y cuántas del otro sentido. Ver Leyes → «Carril: dónde debes circular»."},{"id":6432,"bg":"При тази ситуация ще извърша нарушение ако:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64279.png","v":null,"a":[{"t":"продължа движението си в същата пътна лента","ok":true,"i":null,"es":"continúo en el mismo carril"},{"t":"премина в лявата пътна лента","ok":true,"i":null,"es":"paso al carril izquierdo"},{"t":"спра пред светофара, в лентата, над която е поставен","ok":true,"i":null,"es":"paro ante el semáforo, en el carril sobre el que está colocado"},{"t":"премина в дясната пътна лента","ok":false,"i":null,"es":"paso al carril derecho"}],"f":5,"es":"En esta situación COMETERÉ infracción si: (3 correctas)","explain":"SEGUIR EN EL MISMO CARRIL, PASAR AL CARRIL IZQUIERDO Y PARARSE ANTE EL SEMÁFORO EN SU CARRIL. Tres correctas (son las tres infracciones).\n\nQUÉ VES. Un pórtico con semáforos de carril. Sobre TU carril hay un ASPA ROJA: ese carril está cerrado. El carril de tu derecha no tiene aspa.\n\nEL ASPA ROJA TE OBLIGA A SALIR DE ESE CARRIL hacia uno abierto. Por eso son infracción:\n• seguir por el mismo carril (está cerrado);\n• pasar al carril izquierdo (no es el carril abierto que te corresponde);\n• pararte bajo el aspa (el aspa no significa «para», significa «deja este carril»).\n\nLO ÚNICO CORRECTO es pasar al carril DERECHO.\n\nCLAVE: la pregunta pide las infracciones; marca todo lo que NO sea cambiarte al carril abierto. Compárala con la 5933 y la 6443. Ver Leyes → «El semáforo: cada luz tiene un nombre oficial»."},{"id":5840,"bg":"Коефициентът на сцепление на автомобилните гуми с пътя е най-голям когато пътната настилка е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"суха","ok":true,"i":null,"es":"seco"},{"t":"мокра","ok":false,"i":null,"es":"mojado"},{"t":"заснежена","ok":false,"i":null,"es":"con nieve"},{"t":"заледена","ok":false,"i":null,"es":"helado"}],"f":5,"es":"El coeficiente de rozamiento entre neumáticos y calzada es mayor cuando el pavimento está:","explain":"El rozamiento es máximo en pavimento SECO. Mojado, nieve y hielo lo reducen progresivamente (el hielo es el peor caso), alargando la distancia de frenado."},{"id":5854,"bg":"Влияе ли масата на превозното средство върху дължината на неговия спирачен път?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":5,"es":"¿Afecta la masa del vehículo a su distancia de frenado?","explain":"Sí: a más masa, más energía cinética que disipar con los mismos frenos, y por tanto más metros de frenado. Por eso un vehículo cargado frena peor que vacío."},{"id":5863,"bg":"Най-важният фактор за избягване на сблъсък с движещия се отпред автомобил е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"поддържане на необходимата дистанция","ok":true,"i":null,"es":"mantener la distancia de seguridad necesaria"},{"t":"движението с постоянна скорост","ok":false,"i":null,"es":"circular a velocidad constante"},{"t":"автомобилът да бъде оборудван с подходящи гуми","ok":false,"i":null,"es":"llevar neumáticos adecuados"},{"t":"автомобилът да бъде с нисък център на тежестта","ok":false,"i":null,"es":"tener el centro de gravedad bajo"}],"f":5,"es":"El factor más importante para evitar una colisión con el vehículo de delante es:","explain":"La distancia de seguridad es el factor decisivo: te da el tiempo y el espacio de reacción cuando el de delante frena. Velocidad constante, neumáticos o centro de gravedad ayudan, pero sin distancia no hay margen posible."},{"id":5870,"bg":"При избиране скоростта на движение, водачите на пътни превозни средства:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"трябва да се съобразяват със състоянието на превозното средство","ok":true,"i":null,"es":"el estado del vehículo"},{"t":"трябва да се съобразяват с превозвания товар","ok":true,"i":null,"es":"la carga transportada"},{"t":"не са длъжни да се съобразяват с характера и интензивността на движението","ok":false,"i":null,"es":"no están obligados a considerar la intensidad del tráfico"},{"t":"не са длъжни да се съобразяват с конкретните условия на видимост","ok":false,"i":null,"es":"no están obligados a considerar las condiciones de visibilidad"}],"f":5,"es":"Al elegir la velocidad, los conductores deben tener en cuenta: (2 correctas)","explain":"Al elegir velocidad debes considerar el estado del vehículo y la carga transportada, y TAMBIÉN la intensidad del tráfico y la visibilidad: por eso las dos opciones que dicen 'no están obligados' son falsas."},{"id":5889,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57891.png","v":null,"a":[{"t":"трябва да намаля скоростта","ok":true,"i":null,"es":"debo reducir velocidad"},{"t":"трябва да управлявам с готовност за спиране","ok":true,"i":null,"es":"debo circular listo para frenar"},{"t":"пешеходците не са на платното за движение и не съм задължен да променям скоростта","ok":false,"i":null,"es":"los peatones no están en la calzada y no tengo que cambiar velocidad"},{"t":"движа се по път с предимство и не съм задължен да намалявам скоростта","ok":false,"i":null,"es":"circulo por vía preferente y no tengo que reducir"}],"f":5,"es":"En esta situación: (2 correctas)","explain":"DEBO REDUCIR LA VELOCIDAD Y DEBO CIRCULAR LISTO PARA FRENAR. Dos correctas.\n\nQUÉ VES. La misma escena que la 5886: carretera con señal de VÍA CON PRIORIDAD, un coche AMARILLO detenido a la derecha con varias PERSONAS alrededor, entre ellas un NIÑO junto a la señal.\n\nPERSONAS JUNTO A LA CALZADA = REDUCIR Y PREPARARSE. Pueden cruzar o salir de detrás del coche en cualquier momento.\n\n«LOS PEATONES NO ESTÁN EN LA CALZADA, NO TENGO QUE CAMBIAR LA VELOCIDAD» es el cebo: esperar a que estén en la calzada es reaccionar tarde.\n\n«VOY POR VÍA CON PRIORIDAD Y NO TENGO QUE REDUCIR» es el otro cebo: la prioridad vale frente a otros vehículos en los cruces, no frente al peligro de los peatones.\n\nCLAVE: la prioridad no te exime de la prudencia.\n\nMÉTODO: 1) ¿hay peatones, sobre todo niños, junto a la calzada? 2) si los hay, reduzco y voy listo para frenar. Ver Leyes → «Niños en la vía»."},{"id":5892,"bg":"Как ще постъпите при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57963.png","v":null,"a":[{"t":"намалявам скоростта","ok":true,"i":null,"es":"reduzco la velocidad"},{"t":"при необходимост спирам, докато се убедя, че преминаването е безопасно","ok":true,"i":null,"es":"si es necesario, paro hasta asegurarme de que es seguro pasar"},{"t":"предупреждавам децата със звуков сигнал да освободят пътя","ok":false,"i":null,"es":"aviso a los niños con el claxon para que cedan el paso"},{"t":"преминавам в съседната пътна лента","ok":false,"i":null,"es":"paso al carril adyacente"}],"f":5,"es":"¿Cómo actuarás en esta situación? (2 correctas)","explain":"REDUZCO LA VELOCIDAD Y, SI ES NECESARIO, PARO HASTA ASEGURARME DE QUE ES SEGURO PASAR. Dos correctas.\n\nQUÉ VES. Llevas el intermitente IZQUIERDO: vas a rodear un CAMIÓN rojo parado a tu derecha. Por delante del camión salen unos NIÑOS, uno de ellos en monopatín, hacia tu carril. De frente viene un coche rojo.\n\nLOS NIÑOS SALEN DE DETRÁS DEL CAMIÓN. El camión los tapa y pueden aparecer más. Reduces y, si hace falta, te detienes hasta ver que no viene nadie.\n\n«AVISO A LOS NIÑOS CON EL CLAXON PARA QUE ME DEJEN PASAR» es el cebo: el claxon no da preferencia y puede asustarlos.\n\n«PASO AL CARRIL ADYACENTE» es el otro cebo: por ahí viene un coche de frente, y los niños pueden seguir avanzando hacia ese carril.\n\nCLAVE: niños saliendo de detrás de un obstáculo = reducir y, si hace falta, parar. Ver Leyes → «Niños en la vía»."},{"id":5893,"bg":"След като преминат децата, увеличавам скоростта и продължавам движението.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/58063.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":5,"es":"Cuando pasan los niños, aumento la velocidad y continúo. Esto es:","explain":"INCORRECTO.\n\nQUÉ VES. La misma calle: un CAMIÓN parado a tu derecha y unos NIÑOS cruzando por delante de él. En la acera de la IZQUIERDA hay más niños.\n\nQUE HAYAN PASADO UNOS NO SIGNIFICA QUE NO VENGAN OTROS. Los niños suelen ir en grupo y detrás del camión puede haber más. Además, los de la acera izquierda pueden cruzar. Sigues despacio y atento hasta haber pasado la zona.\n\n«CORRECTO» es el cebo de quien vuelve a la velocidad normal en cuanto el primer peligro desaparece.\n\nCLAVE: donde hay un niño, puede haber otro. Ver Leyes → «Niños en la vía»."},{"id":5899,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/58149.png","v":null,"a":[{"t":"намалявам скоростта","ok":true,"i":null,"es":"reduzco la velocidad"},{"t":"управлявам с готовност за спиране","ok":true,"i":null,"es":"circulo listo para frenar"},{"t":"подавам звуков сигнал за да привлека вниманието на велосипедистите","ok":false,"i":null,"es":"toco el claxon para avisar a los ciclistas"},{"t":"подавам авариен сигнал","ok":false,"i":null,"es":"activo las luces de emergencia"}],"f":5,"es":"En esta situación: (2 correctas)","explain":"REDUZCO LA VELOCIDAD Y CIRCULO LISTO PARA FRENAR. Dos correctas.\n\nQUÉ VES. Calle urbana. Por el lado izquierdo de la calzada vienen DOS CICLISTAS jóvenes; uno de ellos circula hacia el centro de la calzada.\n\nCICLISTAS CERCA DE TU TRAYECTORIA = REDUCIR Y PREPARARSE. Pueden desviarse, caerse o meterse en tu carril. Te das margen de tiempo y espacio.\n\n«TOCO EL CLAXON PARA AVISAR A LOS CICLISTAS» es el cebo: puede asustarlos y provocar una maniobra brusca.\n\n«ACTIVO LAS LUCES DE EMERGENCIA» no sirve aquí: esas luces son para señalar un peligro o una detención anómala de tu vehículo.\n\nCLAVE: ciclistas imprevisibles = menos velocidad y pie preparado. Compárala con la 5901 (la misma escena). Ver Leyes → «Carril: dónde debes circular»."},{"id":6699,"bg":"При заобикаляне на спрелия пред пешеходната пътека автобус:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/58433.png","v":null,"a":[{"t":"трябва да намаля скоростта","ok":true,"i":null,"es":"debo reducir velocidad"},{"t":"трябва да управлявам с готовност да спра пред пешеходната пътека","ok":true,"i":null,"es":"debo estar listo para parar ante el paso de peatones"},{"t":"не съм задължен да намалявам скоростта","ok":false,"i":null,"es":"no estoy obligado a reducir"}],"f":5,"es":"Al rodear un autobús parado antes del paso de peatones: (2 correctas)","explain":"DEBO REDUCIR LA VELOCIDAD Y DEBO ESTAR LISTO PARA PARAR ANTE EL PASO DE PEATONES. Dos correctas.\n\nQUÉ VES. Calle urbana. A tu derecha hay un AUTOBÚS detenido justo antes de un PASO DE PEATONES (señal azul). Llevas el intermitente IZQUIERDO para rodearlo.\n\nEL AUTOBÚS TE TAPA EL PASO DE PEATONES. Puede haberse detenido precisamente para dejar cruzar a alguien que tú no ves. Reduces y vas preparado para parar antes del paso.\n\n«NO ESTOY OBLIGADO A REDUCIR» es el cebo: pasar junto a un vehículo detenido ante un paso de peatones es una de las situaciones más peligrosas para un peatón.\n\nCLAVE: vehículo parado ante un paso de peatones = alguien puede estar cruzando delante de él. Ver Leyes → «Paso de peatones»."},{"id":11692,"bg":"Когато няма други ограничения, водачите на леки моторни превозни средства с четири колела от категория АМ, при движение извън населено място, не трябва да превишават:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"45 km/h","ok":true,"i":null,"es":"45 km/h"},{"t":"50 km/h","ok":false,"i":null,"es":"50 km/h"},{"t":"40 km/h","ok":false,"i":null,"es":"40 km/h"},{"t":"55 km/h","ok":false,"i":null,"es":"55 km/h"}],"f":5,"es":"Sin otras restricciones, el conductor de un cuatriciclo ligero (categoría AM) no debe superar:","explain":"45 km/h: es la velocidad máxima de los cuatriciclos ligeros (categoría AM), limitada por su propia construcción y por la norma."},{"id":11698,"bg":"Когато разрешената максимална скорост за движение в населено място не е сигнализирана с пътен знак, водачите на леки автомобили не трябва да превишават:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"50 km/h","ok":true,"i":null,"es":"50 km/h"},{"t":"40 km/h","ok":false,"i":null,"es":"40 km/h"},{"t":"60 km/h","ok":false,"i":null,"es":"60 km/h"},{"t":"45 km/h","ok":false,"i":null,"es":"45 km/h"}],"f":5,"es":"Cuando la velocidad máxima en zona urbana no está señalizada con señal de tráfico, el límite es:","explain":"50 km/h: es el límite urbano por defecto en Bulgaria cuando no hay señal que indique otro valor. 40 o 30 solo rigen si están señalizados."},{"id":11703,"bg":"Когато няма други ограничения, водачът на товарен автомобил с допустима максимална маса 3 t., при движение извън населено място, не трябва да превишава:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"90 km/h","ok":true,"i":null,"es":"90 km/h"},{"t":"70 km/h","ok":false,"i":null,"es":"70 km/h"},{"t":"80 km/h","ok":false,"i":null,"es":"80 km/h"},{"t":"60 km/h","ok":false,"i":null,"es":"60 km/h"}],"f":5,"es":"Sin otras restricciones, el conductor de camión de 3 t fuera de población no debe superar:","explain":"90 km/h: fuera de población, en vía convencional, un camión de hasta 3,5 t tiene el mismo límite general de 90 km/h. Los valores inferiores solo rigen con señalización."},{"id":12028,"bg":"Какъв е правилният начин на действие при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":14,"a":[{"t":"да се движа възможно най-вдясно","ok":true,"i":null,"es":"circulo todo lo posible a la derecha"},{"t":"да не променям скоростта си и разположението на автомобила","ok":false,"i":null,"es":"no cambio velocidad ni posición"},{"t":"да намаля скоростта и при необходимост да спра","ok":true,"i":null,"es":"reducir velocidad y si es necesario parar"}],"f":5,"es":"¿Cuál es la actuación correcta en esta situación? (2 correctas)"},{"id":6232,"bg":"При тази ситуация кой от водачите трябва да осигури предимство?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/69636.png","v":null,"a":[{"t":"на товарния автомобил, защото навлиза в съседната пътна лента","ok":true,"i":null,"es":"el camión, porque entra en el carril adyacente"},{"t":"на товарния автомобил, защото се намира отдясно","ok":false,"i":null,"es":"el camión, porque está a la derecha"},{"t":"на лекия автомобил, защото не е подал сигнал за маневра","ok":false,"i":null,"es":"el turismo, porque no señalizó"},{"t":"на лекия автомобил, защото е по-назад от товарния","ok":false,"i":null,"es":"el turismo, porque está más atrás"}],"f":5,"es":"En esta situación, ¿cuál de los conductores debe ceder el paso?","explain":"EL CAMIÓN, PORQUE ENTRA EN EL CARRIL ADYACENTE. Una sola correcta.\n\nQUÉ VES. Carretera de dos carriles en el mismo sentido. Un CAMIÓN va por el carril DERECHO con el intermitente IZQUIERDO, para pasarse al izquierdo (delante de él hay una zona rayada). Por el carril IZQUIERDO circula un turismo ROJO.\n\nCEDE EL QUE CAMBIA DE CARRIL. El camión entra en el carril por el que ya circula el rojo: le cede el paso.\n\n«EL CAMIÓN, PORQUE ESTÁ A LA DERECHA» es el cebo fino: la respuesta (el camión) es correcta, pero la razón no. La regla de la derecha no da prioridad a quien cambia de carril.\n\n«EL TURISMO, PORQUE NO SEÑALIZÓ» y «EL TURISMO, PORQUE ESTÁ MÁS ATRÁS» son cebos: el turismo no hace ninguna maniobra, sigue por su carril.\n\nCLAVE: en las preguntas con «porque», la razón tiene que ser la correcta, no solo la conclusión. Ver Leyes → «Carril: dónde debes circular»."},{"id":6237,"bg":"Когато има остров в средата на пътно платно с двупосочно движение, водачът:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/124137.png","v":null,"a":[{"t":"трябва да премине от неговата дясна страна","ok":true,"i":null,"es":"debe pasar por su lado DERECHO"},{"t":"трябва да премине от неговата лява страна","ok":false,"i":null,"es":"debe pasar por su lado IZQUIERDO"},{"t":"може да премине от неговата дясна или лява страна","ok":false,"i":null,"es":"puede pasar por cualquier lado"}],"f":5,"es":"Cuando hay una isla en el centro de la calzada de doble sentido, el conductor:","explain":"DEBE PASAR POR SU LADO DERECHO. Una sola correcta.\n\nQUÉ VES. Una calle de DOBLE SENTIDO con una ISLETA alargada en el centro y un bolardo de señalización en su extremo.\n\nLA ISLETA SE DEJA SIEMPRE A LA IZQUIERDA. En una calzada de doble sentido, pasas por la DERECHA de la isleta: así sigues en tu mitad de la calzada.\n\n«POR SU LADO IZQUIERDO» es meterte en el sentido contrario.\n\n«POR CUALQUIER LADO» es el cebo cómodo: solo valdría si una señal lo permitiera expresamente.\n\nCLAVE: isleta en el centro de una calle de doble sentido = por la derecha. Es la misma lógica que en la rotonda (compárala con la 6378). Ver Leyes → «Carril: dónde debes circular»."},{"id":6252,"bg":"При тази ситуация трябва да пропусна пешеходеца.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/69884.png","v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcto"},{"t":"неправилно","ok":false,"i":null,"es":"INCORRECTO"}],"f":5,"es":"En esta situación debo dejar pasar al peatón. Esto es:","explain":"CORRECTO.\n\nQUÉ VES. Llevas el intermitente DERECHO y vas a girar a la derecha (flecha). En la calle a la que vas a entrar, un PEATÓN está cruzando.\n\nAL GIRAR, CEDES A LOS PEATONES QUE CRUZAN LA CALLE A LA QUE ENTRAS, aunque no haya paso pintado y aunque tengas preferencia frente a los vehículos.\n\n«INCORRECTO» es el cebo de quien piensa que solo se cede al peatón en un paso de peatones.\n\nCLAVE: es la misma escena que la 6254. Giro + peatón cruzando la calle de destino = cedo. Ver Leyes → «Paso de peatones»."}];
